window.FO_PACKS=window.FO_PACKS||{};window.FO_PACKS["FK1"]={"FK1-001":{"objectives":["Fransızca merhaba ve hoşça kal demek","Adını söylemek ve arkadaşının adını sormak","Nasılsın sorusuna Fransızca cevap vermek"],"dialogues":[{"title":"Le premier jour","setting":"Okulun ilk gününde Léa yeni arkadaşı Hugo ile tanışıyor.","lines":[{"s":"Léa","en":"Bonjour ! Je m'appelle Léa.","tr":"Merhaba! Benim adım Léa."},{"s":"Hugo","en":"Salut, Léa ! Moi, c'est Hugo.","tr":"Selam Léa! Ben Hugo."},{"s":"Léa","en":"Enchantée, Hugo ! Tu es mon ami ?","tr":"Memnun oldum Hugo! Sen benim arkadaşım mısın?"},{"s":"Hugo","en":"Oui ! Ça va, Léa ?","tr":"Evet! İyi misin Léa?"},{"s":"Léa","en":"Ça va bien, merci. Et toi ?","tr":"İyiyim, teşekkürler. Ya sen?"},{"s":"Hugo","en":"Ça va très bien ! On joue ?","tr":"Çok iyiyim! Oynayalım mı?"},{"s":"Léa","en":"Oui, on joue !","tr":"Evet, oynayalım!"}]},{"title":"Bonjour, Madame !","setting":"Madame Martin sınıfa giriyor ve çocuklarla tanışıyor.","lines":[{"s":"Madame Martin","en":"Bonjour, les enfants !","tr":"Günaydın çocuklar!"},{"s":"Elif","en":"Bonjour, Madame !","tr":"Günaydın öğretmenim!"},{"s":"Madame Martin","en":"Comment tu t'appelles ?","tr":"Senin adın ne?"},{"s":"Elif","en":"Je m'appelle Elif.","tr":"Benim adım Elif."},{"s":"Madame Martin","en":"Enchantée, Elif ! Et toi ?","tr":"Memnun oldum Elif! Ya senin adın?"},{"s":"Léa","en":"Moi, je m'appelle Léa.","tr":"Benim adım Léa."},{"s":"Madame Martin","en":"Bienvenue à l'école !","tr":"Okula hoş geldiniz!"}]},{"title":"À demain !","setting":"Okul bitti. Léa Hugo'ya veda ediyor, akşam da babasına iyi geceler diyor.","lines":[{"s":"Léa","en":"Au revoir, Hugo ! À demain !","tr":"Hoşça kal Hugo! Yarın görüşürüz!"},{"s":"Hugo","en":"Au revoir, Léa ! À demain !","tr":"Hoşça kal Léa! Yarın görüşürüz!"},{"s":"Papa","en":"Bonsoir, Léa ! Ça va ?","tr":"İyi akşamlar Léa! İyi misin?"},{"s":"Léa","en":"Bonsoir, Papa ! Ça va bien.","tr":"İyi akşamlar baba! İyiyim."},{"s":"Papa","en":"Il est tard, Léa. Bonne nuit !","tr":"Geç oldu Léa. İyi geceler!"},{"s":"Léa","en":"Bonne nuit, Papa !","tr":"İyi geceler baba!"}]}],"reading":{"title":"Je dis bonjour","paras":[{"en":"Je m'appelle Léa. J'ai sept ans. Voici mon frère. Il s'appelle Tom. Voici mon chat. Il s'appelle Minou. À l'école, je dis : « Bonjour, Madame ! » Le soir, je dis : « Bonne nuit ! » J'aime dire bonjour à mes amis. C'est super !","tr":"Benim adım Léa. Yedi yaşındayım. Bu benim erkek kardeşim. Adı Tom. Bu benim kedim. Adı Minou. Okulda « Günaydın öğretmenim! » derim. Akşam « İyi geceler! » derim. Arkadaşlarıma merhaba demeyi severim. Çok güzel!"}]},"vocab":[{"w":"bonjour","ipa":"/bɔ̃.ʒuʁ/","pos":"👋","tr":"merhaba, günaydın","ex":"Bonjour, Madame !","exTr":"Günaydın öğretmenim!"},{"w":"salut","ipa":"/sa.ly/","pos":"🙋","tr":"selam","ex":"Salut, Léa !","exTr":"Selam Léa!"},{"w":"au revoir","ipa":"/o ʁə.vwaʁ/","pos":"🖐️","tr":"hoşça kal","ex":"Au revoir, Hugo !","exTr":"Hoşça kal Hugo!"},{"w":"merci","ipa":"/mɛʁ.si/","pos":"🙏","tr":"teşekkürler","ex":"Ça va bien, merci.","exTr":"İyiyim, teşekkürler."},{"w":"bonne nuit","ipa":"/bɔn nɥi/","pos":"🌙","tr":"iyi geceler","ex":"Bonne nuit, Papa !","exTr":"İyi geceler baba!"},{"w":"l'école","ipa":"/le.kɔl/","pos":"🏫","tr":"okul","ex":"Bienvenue à l'école !","exTr":"Okula hoş geldiniz!"},{"w":"un ami","ipa":"/œ̃ na.mi/","pos":"🧒","tr":"bir arkadaş","ex":"Tu es mon ami ?","exTr":"Sen benim arkadaşım mısın?"},{"w":"oui","ipa":"/wi/","pos":"✅","tr":"evet","ex":"Oui, on joue !","exTr":"Evet, oynayalım!"}],"chunks":[{"en":"Je m'appelle…","tr":"Benim adım…"},{"en":"Comment tu t'appelles ?","tr":"Senin adın ne?"},{"en":"Ça va bien, merci.","tr":"İyiyim, teşekkürler."},{"en":"À demain !","tr":"Yarın görüşürüz!"}],"grammar":{"point":"Je m'appelle…","tr":"Adını söylemek için « Je m'appelle… » deriz, yani « benim adım… ». Birinin adını sormak için « Comment tu t'appelles ? » deriz. Arkadaşına « Moi, c'est… » da diyebilirsin: « Ben … ».","examples":["Je m'appelle Léa.","Il s'appelle Tom.","Comment tu t'appelles ?","Moi, c'est Hugo."]},"questions":[{"q":"Comment s'appelle la fille de l'histoire ?","a":"Elle s'appelle Léa."},{"q":"Comment s'appelle le frère de Léa ?","a":"Il s'appelle Tom."},{"q":"Que dit Léa le soir ?","a":"Elle dit : « Bonne nuit ! »"}],"quiz":[{"q":"Le matin, tu dis…","o":["Bonne nuit","Bonjour","Merci"],"a":1,"why":""},{"q":"« Au revoir » veut dire…","o":["merhaba","teşekkürler","hoşça kal"],"a":2,"why":"Au revoir = hoşça kal"},{"q":"Le chat de Léa s'appelle…","o":["Rex","Minou","Hugo"],"a":1,"why":""},{"q":"Pour demander le prénom, on dit : « Comment tu ___ ? »","o":["t'appelles","es","joues"],"a":0,"why":"Comment tu t'appelles ? = Senin adın ne?"}],"drills":[{"type":"Yerine koyma","prompt":"Je m'appelle Léa.","cue":"Elif","answer":"Je m'appelle Elif."},{"type":"Yerine koyma","prompt":"Bonjour, Madame !","cue":"Salut / Hugo","answer":"Salut, Hugo !"},{"type":"Soru yap","prompt":"Je m'appelle Léa.","cue":"Comment…?","answer":"Comment tu t'appelles ?"}],"sounds":[{"focus":"/ʁ/","tr":"Fransızca r, Türkçedeki r gibi dilin ucuyla çıkmaz. Dilin ucu alt dişlerin arkasında kalır, gırtlağının arkasından hafifçe gargara yapar gibi 'rrh' dersin: 'bonjour', 'au revoir', 'merci'.","pairs":["roue / loup","riz / lit"]}],"mission":{"brief":"Oyun: Yeni arkadaş! Claude, arkadaşın Léa olacak. Ona Fransızca merhaba de, adını sor ve nasıl olduğunu öğren.","persona":"Léa, a cheerful 7-year-old French girl. Speaks in very short, simple French sentences and encourages the child. Asks one question at a time. Hidden fact: Léa has a cat called Minou, but she only tells it if the child asks « Tu as un animal ? ».","goal":"Léa'ya merhaba de, adını sor ve 'Ça va ?' ile nasıl olduğunu öğren.","opener":"Bonjour ! Je m'appelle Léa. Et toi, comment tu t'appelles ?"}},"FK1-002":{"objectives":["Aile üyelerini Fransızca söylemek","'Voici mon / ma…' ile ailesini tanıtmak","'Tu as un frère ?' diye sormak ve cevaplamak"],"dialogues":[{"title":"La photo de famille","setting":"Léa, arkadaşı Hugo'ya aile fotoğrafını gösteriyor.","lines":[{"s":"Léa","en":"Regarde, Hugo ! Voici ma famille.","tr":"Bak Hugo! Bu benim ailem."},{"s":"Hugo","en":"Qui est-ce ?","tr":"Bu kim?"},{"s":"Léa","en":"C'est ma maman. Et voici mon papa.","tr":"Bu annem. Bu da babam."},{"s":"Hugo","en":"Et le petit garçon ?","tr":"Peki şu küçük oğlan kim?"},{"s":"Léa","en":"C'est mon frère. Il s'appelle Tom.","tr":"Bu benim erkek kardeşim. Adı Tom."},{"s":"Hugo","en":"Il a quel âge ?","tr":"Kaç yaşında?"},{"s":"Léa","en":"Il a cinq ans !","tr":"Beş yaşında!"}]},{"title":"Chez Mamie","setting":"Hafta sonu Léa ve Tom büyükanne ile büyükbabalarını ziyaret ediyor.","lines":[{"s":"Tom","en":"Mamie ! Papi ! Voilà Léa et moi !","tr":"Anneanne! Dede! İşte Léa ile ben!"},{"s":"Mamie","en":"Bonjour, mes chéris ! Ça va ?","tr":"Merhaba tatlılarım! İyi misiniz?"},{"s":"Léa","en":"Ça va bien, Mamie !","tr":"İyiyiz anneanne!"},{"s":"Papi","en":"Voici votre gâteau, les enfants.","tr":"İşte pastanız çocuklar."},{"s":"Tom","en":"Merci, Papi ! J'aime ma famille !","tr":"Teşekkürler dede! Ailemi seviyorum!"},{"s":"Mamie","en":"Nous aussi, on vous aime !","tr":"Biz de sizi seviyoruz!"}]},{"title":"Une amie turque","setting":"Elif sınıfta Léa'ya kendi ailesini anlatıyor.","lines":[{"s":"Léa","en":"Elif, tu as un frère ?","tr":"Elif, senin erkek kardeşin var mı?"},{"s":"Elif","en":"Non, mais j'ai une sœur. Elle s'appelle Defne.","tr":"Hayır, ama bir kız kardeşim var. Adı Defne."},{"s":"Léa","en":"Elle est petite ?","tr":"O küçük mü?"},{"s":"Elif","en":"Oui, elle a trois ans.","tr":"Evet, üç yaşında."},{"s":"Léa","en":"Moi, j'ai un frère et un chat !","tr":"Benim bir erkek kardeşim ve bir kedim var!"},{"s":"Elif","en":"Super ! Ta famille est sympa.","tr":"Harika! Ailen çok sevimli."}]}],"reading":{"title":"La famille de Léa","paras":[{"en":"Voici ma famille. Il y a ma maman et mon papa. Il y a aussi mon frère Tom. Il est petit. Voici ma mamie et mon papi. Ils sont gentils. Nous avons un chat, Minou. Dans ma famille, on joue et on rit. J'aime ma famille !","tr":"İşte ailem. Annem ve babam var. Ayrıca erkek kardeşim Tom var. O küçük. İşte anneannem ve dedem. Çok iyiler. Bir kedimiz var, Minou. Ailemde oynarız ve güleriz. Ailemi seviyorum!"}]},"vocab":[{"w":"la famille","ipa":"/la fa.mij/","pos":"👨‍👩‍👧‍👦","tr":"aile","ex":"Voici ma famille.","exTr":"İşte ailem."},{"w":"la maman","ipa":"/la ma.mɑ̃/","pos":"👩","tr":"anne","ex":"C'est ma maman.","exTr":"Bu benim annem."},{"w":"le papa","ipa":"/lə pa.pa/","pos":"👨","tr":"baba","ex":"Voici mon papa.","exTr":"İşte babam."},{"w":"le frère","ipa":"/lə fʁɛʁ/","pos":"👦","tr":"erkek kardeş","ex":"C'est mon frère.","exTr":"Bu benim erkek kardeşim."},{"w":"la sœur","ipa":"/la sœʁ/","pos":"👧","tr":"kız kardeş","ex":"J'ai une sœur.","exTr":"Bir kız kardeşim var."},{"w":"la mamie","ipa":"/la ma.mi/","pos":"👵","tr":"büyükanne","ex":"Bonjour, Mamie !","exTr":"Merhaba anneanne!"},{"w":"le papi","ipa":"/lə pa.pi/","pos":"👴","tr":"büyükbaba","ex":"Merci, Papi !","exTr":"Teşekkürler dede!"},{"w":"le chat","ipa":"/lə ʃa/","pos":"🐱","tr":"kedi","ex":"Nous avons un chat.","exTr":"Bir kedimiz var."}],"chunks":[{"en":"Voici ma famille.","tr":"İşte ailem."},{"en":"C'est mon frère.","tr":"Bu benim erkek kardeşim."},{"en":"Tu as un frère ?","tr":"Erkek kardeşin var mı?"},{"en":"J'aime ma famille !","tr":"Ailemi seviyorum!"}],"grammar":{"point":"Mon / ma","tr":"'Benim' demek için erkek sözcüklerin önüne « mon » (mon papa, mon frère), kız sözcüklerin önüne « ma » (ma maman, ma sœur) koyarız. Sözcük sesli harfle başlıyorsa kız sözcüklerde bile « mon » kullanırız, ama şimdilik buna takılma!","examples":["Voici mon papa.","Voici ma maman.","C'est mon frère.","C'est ma sœur."]},"questions":[{"q":"Qui est Tom ?","a":"C'est le frère de Léa."},{"q":"Comment s'appelle la sœur d'Elif ?","a":"Elle s'appelle Defne."},{"q":"Comment s'appelle le chat de la famille ?","a":"Il s'appelle Minou."}],"quiz":[{"q":"Voici ___ maman.","o":["mon","ma","un"],"a":1,"why":"maman kız sözcük: ma maman"},{"q":"Tom est le ___ de Léa.","o":["frère","sœur","papi"],"a":0,"why":""},{"q":"Defne a… ","o":["cinq ans","trois ans","sept ans"],"a":1,"why":""},{"q":"« Mamie » veut dire…","o":["büyükanne","kız kardeş","anne"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Voici mon papa.","cue":"frère","answer":"Voici mon frère."},{"type":"Yerine koyma","prompt":"C'est ma maman.","cue":"sœur","answer":"C'est ma sœur."},{"type":"Soru yap","prompt":"Tu as un frère.","cue":"Est-ce que…?","answer":"Tu as un frère ?"}],"sounds":[{"focus":"/ɔ̃/","tr":"Fransızca 'mon' ve 'bon' sözcüklerinde n harfi okunmaz. Ağzını yuvarlak yap, 'o' de ve sesi burnundan çıkar, dilin n için dişlere dokunmasın: 'mon', 'bon'.","pairs":["bon / bonne","mon / mine"]}],"mission":{"brief":"Oyun: Aile sohbeti! Claude, Léa'nın küçük kardeşi Tom olacak. Ona ailesi hakkında Fransızca sorular sor.","persona":"Tom, a lively 5-year-old French boy. Uses extremely short French sentences. Asks one question at a time. Hidden fact: Tom's favourite family member is Papi, because Papi bakes cakes. He only tells it if the child asks « Qui est ton préféré ? ».","goal":"Tom'a ailesini sor ve en az iki aile üyesinin adını 'Voici…' ile öğren.","opener":"Salut ! Moi, c'est Tom. Voici ma famille. Et toi, tu as un frère ?"}},"FK1-003":{"objectives":["Temel renkleri Fransızca söylemek","'De quelle couleur est… ?' sorusunu sormak","'Il est / elle est…' ile renk söylemek"],"dialogues":[{"title":"Le ballon de Hugo","setting":"Hugo ve Léa parkta top oynuyor.","lines":[{"s":"Hugo","en":"Regarde mon ballon, Léa !","tr":"Bak topuma Léa!"},{"s":"Léa","en":"De quelle couleur est-il ?","tr":"Ne renk o?"},{"s":"Hugo","en":"Il est rouge.","tr":"Kırmızı."},{"s":"Léa","en":"J'aime le rouge ! Moi, j'ai un ballon bleu.","tr":"Kırmızıyı severim! Benim de mavi bir topum var."},{"s":"Hugo","en":"Super ! On joue avec les deux ballons ?","tr":"Harika! İki topla birlikte oynayalım mı?"},{"s":"Léa","en":"Oui, vite !","tr":"Evet, hadi çabuk!"}]},{"title":"Dans le jardin","setting":"Mamie, Léa ile bahçede renkleri arıyor.","lines":[{"s":"Mamie","en":"De quelle couleur est le ciel, Léa ?","tr":"Gökyüzü ne renk Léa?"},{"s":"Léa","en":"Il est bleu !","tr":"Mavi!"},{"s":"Mamie","en":"Et l'herbe ?","tr":"Peki çimen?"},{"s":"Léa","en":"Elle est verte !","tr":"Yeşil!"},{"s":"Mamie","en":"Et la fleur ?","tr":"Peki çiçek?"},{"s":"Léa","en":"Elle est rose. J'aime le rose !","tr":"Pembe. Pembeyi severim!"},{"s":"Mamie","en":"Bravo, ma chérie !","tr":"Aferin canım!"}]},{"title":"Mon chat Minou","setting":"Léa, Elif'e kedisini anlatıyor.","lines":[{"s":"Elif","en":"De quelle couleur est ton chat ?","tr":"Kedinin rengi ne?"},{"s":"Léa","en":"Minou est noir et blanc.","tr":"Minou siyah beyaz."},{"s":"Elif","en":"Et le soleil ? Il est noir ?","tr":"Peki güneş? O siyah mı?"},{"s":"Léa","en":"Mais non ! Il est jaune !","tr":"Hayır canım! O sarı!"},{"s":"Elif","en":"Haha ! Et ma robe est orange.","tr":"Haha! Benim elbisem de turuncu."},{"s":"Léa","en":"Elle est jolie !","tr":"Çok güzel!"}]}],"reading":{"title":"Les couleurs de Léa","paras":[{"en":"J'aime les couleurs ! Le ciel est bleu. L'herbe est verte. Le soleil est jaune. Mon ballon est rouge. La fleur est rose. Mon chat Minou est noir et blanc. La robe d'Elif est orange. Je prends mes crayons et je dessine un arc-en-ciel.","tr":"Renkleri severim! Gökyüzü mavi. Çimen yeşil. Güneş sarı. Topum kırmızı. Çiçek pembe. Kedim Minou siyah beyaz. Elif'in elbisesi turuncu. Boya kalemlerimi alırım ve bir gökkuşağı çizerim."}]},"vocab":[{"w":"rouge","ipa":"/ʁuʒ/","pos":"🔴","tr":"kırmızı","ex":"Mon ballon est rouge.","exTr":"Topum kırmızı."},{"w":"bleu","ipa":"/blø/","pos":"🔵","tr":"mavi","ex":"Le ciel est bleu.","exTr":"Gökyüzü mavi."},{"w":"vert","ipa":"/vɛʁ/","pos":"🟢","tr":"yeşil","ex":"L'herbe est verte.","exTr":"Çimen yeşil."},{"w":"jaune","ipa":"/ʒon/","pos":"🟡","tr":"sarı","ex":"Le soleil est jaune.","exTr":"Güneş sarı."},{"w":"rose","ipa":"/ʁoz/","pos":"🌸","tr":"pembe","ex":"La fleur est rose.","exTr":"Çiçek pembe."},{"w":"noir","ipa":"/nwaʁ/","pos":"⚫","tr":"siyah","ex":"Minou est noir et blanc.","exTr":"Minou siyah beyaz."},{"w":"blanc","ipa":"/blɑ̃/","pos":"⚪","tr":"beyaz","ex":"Minou est noir et blanc.","exTr":"Minou siyah beyaz."},{"w":"orange","ipa":"/ɔ.ʁɑ̃ʒ/","pos":"🟠","tr":"turuncu","ex":"La robe est orange.","exTr":"Elbise turuncu."}],"chunks":[{"en":"De quelle couleur est-il ?","tr":"Ne renk o?"},{"en":"Il est rouge.","tr":"O kırmızı."},{"en":"J'aime le bleu.","tr":"Maviyi severim."},{"en":"Bravo !","tr":"Aferin!"}],"grammar":{"point":"Il est / elle est","tr":"Erkek sözcükler için « il est » (il est bleu), kız sözcükler için « elle est » (elle est rose) deriz. Bazı renkler kız sözcüklerde değişir: vert → verte, blanc → blanche. Rouge, jaune, rose ve orange hiç değişmez.","examples":["Il est rouge.","Elle est verte.","Le ciel est bleu.","La fleur est rose."]},"questions":[{"q":"De quelle couleur est le ciel ?","a":"Il est bleu."},{"q":"De quelle couleur est Minou ?","a":"Il est noir et blanc."},{"q":"Que dessine Léa ?","a":"Elle dessine un arc-en-ciel."}],"quiz":[{"q":"🟡 est…","o":["jaune","rouge","vert"],"a":0,"why":""},{"q":"L'herbe ___ verte.","o":["il est","elle est","c'est un"],"a":1,"why":"herbe kız sözcük: elle est verte"},{"q":"« Noir » veut dire…","o":["beyaz","siyah","pembe"],"a":1,"why":""},{"q":"Le ballon de Hugo est…","o":["bleu","rose","rouge"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Mon ballon est rouge.","cue":"bleu","answer":"Mon ballon est bleu."},{"type":"Yerine koyma","prompt":"Le ciel est bleu.","cue":"l'herbe / verte","answer":"L'herbe est verte."},{"type":"Soru yap","prompt":"Il est jaune.","cue":"De quelle couleur…?","answer":"De quelle couleur est-il ?"}],"sounds":[{"focus":"/y/","tr":"Fransızca u harfi, Türkçedeki ü gibi okunur. Dudaklarını 'u' der gibi büz, ama dilini 'i' deyişindeki gibi öne al. 'ou' ise Türkçedeki u gibidir: 'rue' ile 'roue' farklıdır!","pairs":["rue / roue","tu / tout"]}],"mission":{"brief":"Oyun: Renk avı! Claude, arkadaşın Hugo olacak. Hugo'ya nesnelerin rengini Fransızca sor ve cevapla.","persona":"Hugo, a friendly 7-year-old French boy. Uses very short French sentences and encourages the child. Asks one question at a time. Hidden fact: Hugo's favourite colour is green (vert), but he only says it if the child asks « Quelle est ta couleur préférée ? ».","goal":"En az üç nesnenin rengini 'Il est… / Elle est…' ile söyle.","opener":"Salut ! Regarde mon ballon. De quelle couleur est-il ?"}},"FK1-004":{"objectives":["1'den 20'ye kadar Fransızca saymak","'J'ai … ans' ile yaşını söylemek","'Combien de… ?' sorusunu sormak"],"dialogues":[{"title":"Les pommes de Maman","setting":"Mutfakta Léa ve annesi elmaları sayıyor.","lines":[{"s":"Léa","en":"Maman, combien de pommes ?","tr":"Anne, kaç elma var?"},{"s":"Maman","en":"Compte avec moi !","tr":"Benimle birlikte say!"},{"s":"Léa","en":"Un, deux, trois, quatre, cinq !","tr":"Bir, iki, üç, dört, beş!"},{"s":"Maman","en":"Oui ! Et encore cinq.","tr":"Evet! Bir de beş tane daha."},{"s":"Léa","en":"Il y a dix pommes !","tr":"On elma var!"},{"s":"Maman","en":"Bravo, Léa !","tr":"Aferin Léa!"}]},{"title":"Quel âge as-tu ?","setting":"Hugo ve Léa yaşlarını konuşuyor.","lines":[{"s":"Hugo","en":"Tu as quel âge, Léa ?","tr":"Kaç yaşındasın Léa?"},{"s":"Léa","en":"J'ai sept ans. Et toi ?","tr":"Yedi yaşındayım. Ya sen?"},{"s":"Hugo","en":"Moi aussi, j'ai sept ans !","tr":"Ben de yedi yaşındayım!"},{"s":"Léa","en":"Tom a cinq ans.","tr":"Tom beş yaşında."},{"s":"Hugo","en":"Et Mamie ?","tr":"Peki Mamie?"},{"s":"Léa","en":"Mamie a un secret : elle ne dit pas son âge !","tr":"Mamie'nin bir sırrı var: yaşını söylemez!"}]},{"title":"En classe","setting":"Madame Martin sınıftaki çocukları sayıyor.","lines":[{"s":"Madame Martin","en":"Combien d'enfants dans la classe ?","tr":"Sınıfta kaç çocuk var?"},{"s":"Can","en":"Il y a quinze filles et cinq garçons.","tr":"On beş kız ve beş erkek var."},{"s":"Madame Martin","en":"Quinze et cinq, ça fait vingt !","tr":"On beş artı beş yirmi eder!"},{"s":"Léa","en":"Vingt enfants, c'est beaucoup !","tr":"Yirmi çocuk, bu çok!"},{"s":"Madame Martin","en":"Oui ! Comptons ensemble : dix, onze, douze !","tr":"Evet! Birlikte sayalım: on, on bir, on iki!"},{"s":"Les enfants","en":"Treize, quatorze, quinze !","tr":"On üç, on dört, on beş!"}]}],"reading":{"title":"Je compte","paras":[{"en":"J'aime compter ! Dans ma classe, il y a vingt enfants. J'ai sept ans et Tom a cinq ans. À la maison, il y a trois chats dans le jardin : un, deux, trois ! Mamie a dix pommes dans son panier. Je compte avec Papa : un, deux, trois, quatre, cinq !","tr":"Saymayı severim! Sınıfımda yirmi çocuk var. Ben yedi yaşındayım, Tom beş yaşında. Evde bahçede üç kedi var: bir, iki, üç! Mamie'nin sepetinde on elma var. Babamla sayarım: bir, iki, üç, dört, beş!"}]},"vocab":[{"w":"un","ipa":"/œ̃/","pos":"1️⃣","tr":"bir","ex":"Un chat.","exTr":"Bir kedi."},{"w":"deux","ipa":"/dø/","pos":"2️⃣","tr":"iki","ex":"Deux pommes.","exTr":"İki elma."},{"w":"trois","ipa":"/tʁwa/","pos":"3️⃣","tr":"üç","ex":"Il y a trois chats.","exTr":"Üç kedi var."},{"w":"cinq","ipa":"/sɛ̃k/","pos":"5️⃣","tr":"beş","ex":"Tom a cinq ans.","exTr":"Tom beş yaşında."},{"w":"sept","ipa":"/sɛt/","pos":"7️⃣","tr":"yedi","ex":"J'ai sept ans.","exTr":"Yedi yaşındayım."},{"w":"dix","ipa":"/dis/","pos":"🔟","tr":"on","ex":"Il y a dix pommes.","exTr":"On elma var."},{"w":"quinze","ipa":"/kɛ̃z/","pos":"🧒","tr":"on beş","ex":"Il y a quinze filles.","exTr":"On beş kız var."},{"w":"vingt","ipa":"/vɛ̃/","pos":"🎉","tr":"yirmi","ex":"Il y a vingt enfants.","exTr":"Yirmi çocuk var."}],"chunks":[{"en":"J'ai sept ans.","tr":"Yedi yaşındayım."},{"en":"Tu as quel âge ?","tr":"Kaç yaşındasın?"},{"en":"Combien de pommes ?","tr":"Kaç elma?"},{"en":"Compte avec moi !","tr":"Benimle say!"}],"grammar":{"point":"J'ai… ans","tr":"Fransızcada yaşı söylerken 'sahip olmak' fiilini kullanırız: « J'ai sept ans » yani 'yedi yaşım var'. Sorarken « Tu as quel âge ? » deriz. Başkası için « il a / elle a » kullanırız: « Tom a cinq ans ».","examples":["J'ai sept ans.","Tom a cinq ans.","Tu as quel âge ?","Il y a dix pommes."]},"questions":[{"q":"Quel âge a Léa ?","a":"Elle a sept ans."},{"q":"Combien d'enfants y a-t-il dans la classe ?","a":"Il y a vingt enfants."},{"q":"Combien de pommes a Mamie ?","a":"Elle a dix pommes."}],"quiz":[{"q":"Tom a… ","o":["trois ans","cinq ans","dix ans"],"a":1,"why":""},{"q":"5 + 5 = ?","o":["quinze","dix","vingt"],"a":1,"why":"cinq et cinq = dix"},{"q":"« Vingt » veut dire…","o":["on","on beş","yirmi"],"a":2,"why":""},{"q":"Je ___ sept ans.","o":["suis","ai","a"],"a":1,"why":"Fransızcada yaş için 'avoir': j'ai"}],"drills":[{"type":"Yerine koyma","prompt":"J'ai sept ans.","cue":"huit","answer":"J'ai huit ans."},{"type":"Yerine koyma","prompt":"Tom a cinq ans.","cue":"Léa / sept","answer":"Léa a sept ans."},{"type":"Soru yap","prompt":"Léa a sept ans.","cue":"Quel âge…?","answer":"Quel âge a Léa ?"}],"sounds":[{"focus":"Liaison","tr":"Sayılar sesli harfle başlayan bir sözcüğün önüne gelince, son harf sese dönüşür ve sözcükler birbirine bağlanır: 'deux ans' → 'dö-zan', 'trois enfants' → 'trua-zanfan'. Sözcükler arasında durma!","pairs":["deux ans / deux chats","trois enfants / trois pommes"]}],"mission":{"brief":"Oyun: Elma sayma! Claude, Mamie olacak. Mamie'nin sepetindeki elmaları Fransızca sor, sayıyı söylesin.","persona":"Mamie, a warm French grandmother. Speaks in very short, slow French sentences. Asks one question at a time. Hidden fact: Mamie has fifteen apples (quinze pommes) in her basket, but she only says the number if the child asks « Combien de pommes ? ».","goal":"'Combien de pommes ?' diye sor ve cevabı Fransızca söyle.","opener":"Bonjour, ma puce ! Regarde mon panier. Il y a des pommes."}},"FK1-005":{"objectives":["Oyuncakların adlarını Fransızca söylemek","'J'ai un / une…' ile elindekini söylemek","'Tu as… ?' diye sormak ve 'J'aime…' demek"],"dialogues":[{"title":"Dans la chambre","setting":"Léa ve Tom odalarında oyuncaklarını gösteriyor.","lines":[{"s":"Tom","en":"Regarde, Léa ! J'ai un robot.","tr":"Bak Léa! Benim bir robotum var."},{"s":"Léa","en":"Il est super ! Moi, j'ai une poupée.","tr":"Çok güzel! Benim de bir bebeğim var."},{"s":"Tom","en":"Tu as un nounours ?","tr":"Senin bir oyuncak ayın var mı?"},{"s":"Léa","en":"Oui, il est dans mon lit.","tr":"Evet, yatağımda."},{"s":"Tom","en":"On joue avec le train ?","tr":"Trenle oynayalım mı?"},{"s":"Léa","en":"Oui ! Tchou-tchou !","tr":"Evet! Çuf çuf!"}]},{"title":"Chez Hugo","setting":"Léa, arkadaşı Hugo'nun evinde oyuncaklara bakıyor.","lines":[{"s":"Léa","en":"Tu as beaucoup de jouets, Hugo !","tr":"Çok oyuncağın var Hugo!"},{"s":"Hugo","en":"Oui ! J'ai un vélo et un ballon.","tr":"Evet! Bir bisikletim ve bir topum var."},{"s":"Léa","en":"Et ça, c'est quoi ?","tr":"Peki şu ne?"},{"s":"Hugo","en":"C'est un puzzle. Tu aimes les puzzles ?","tr":"Bu bir yapboz. Yapbozları sever misin?"},{"s":"Léa","en":"Oui, j'aime les puzzles !","tr":"Evet, yapbozları severim!"},{"s":"Hugo","en":"Alors, on joue ensemble.","tr":"O zaman birlikte oynayalım."}]},{"title":"Un cadeau de Mamie","setting":"Mamie, Tom'a doğum günü hediyesi veriyor.","lines":[{"s":"Mamie","en":"Joyeux anniversaire, Tom ! C'est pour toi.","tr":"Doğum günün kutlu olsun Tom! Bu senin için."},{"s":"Tom","en":"Oh ! C'est une voiture !","tr":"Oh! Bu bir araba!"},{"s":"Mamie","en":"Elle est rouge et elle est rapide.","tr":"Kırmızı ve çok hızlı."},{"s":"Tom","en":"Merci, Mamie ! J'adore ma voiture !","tr":"Teşekkürler Mamie! Arabama bayılıyorum!"},{"s":"Léa","en":"Tom, on joue avec ta voiture ?","tr":"Tom, arabanla oynayalım mı?"},{"s":"Tom","en":"Oui ! Mais doucement !","tr":"Evet! Ama yavaş yavaş!"}]}],"reading":{"title":"Mes jouets","paras":[{"en":"J'ai beaucoup de jouets dans ma chambre. J'ai une poupée et un nounours. Tom a un robot et une voiture. Hugo a un vélo. Moi, j'aime le puzzle. Le soir, je joue avec Tom. Nous jouons au train. Après, nous rangeons nos jouets. C'est facile !","tr":"Odamda çok oyuncağım var. Bir bebeğim ve bir oyuncak ayım var. Tom'un bir robotu ve bir arabası var. Hugo'nun bir bisikleti var. Ben yapbozu severim. Akşam Tom'la oynarım. Trenle oynarız. Sonra oyuncaklarımızı toplarız. Çok kolay!"}]},"vocab":[{"w":"le ballon","ipa":"/lə ba.lɔ̃/","pos":"⚽","tr":"top","ex":"J'ai un ballon.","exTr":"Bir topum var."},{"w":"la poupée","ipa":"/la pu.pe/","pos":"🪆","tr":"bebek","ex":"J'ai une poupée.","exTr":"Bir bebeğim var."},{"w":"le nounours","ipa":"/lə nu.nuʁs/","pos":"🧸","tr":"oyuncak ayı","ex":"Tu as un nounours ?","exTr":"Oyuncak ayın var mı?"},{"w":"la voiture","ipa":"/la vwa.tyʁ/","pos":"🚗","tr":"araba","ex":"C'est une voiture !","exTr":"Bu bir araba!"},{"w":"le robot","ipa":"/lə ʁɔ.bo/","pos":"🤖","tr":"robot","ex":"J'ai un robot.","exTr":"Bir robotum var."},{"w":"le puzzle","ipa":"/lə pœzl/","pos":"🧩","tr":"yapboz","ex":"C'est un puzzle.","exTr":"Bu bir yapboz."},{"w":"le train","ipa":"/lə tʁɛ̃/","pos":"🚂","tr":"tren","ex":"On joue avec le train ?","exTr":"Trenle oynayalım mı?"},{"w":"le vélo","ipa":"/lə ve.lo/","pos":"🚲","tr":"bisiklet","ex":"J'ai un vélo.","exTr":"Bir bisikletim var."}],"chunks":[{"en":"J'ai un robot.","tr":"Bir robotum var."},{"en":"Tu as un nounours ?","tr":"Oyuncak ayın var mı?"},{"en":"J'aime les puzzles.","tr":"Yapbozları severim."},{"en":"On joue ensemble ?","tr":"Birlikte oynayalım mı?"}],"grammar":{"point":"Un / une","tr":"Erkek sözcüklerin önüne « un » (un ballon, un robot), kız sözcüklerin önüne « une » (une poupée, une voiture) koyarız. « J'ai un… » demek 'bir … var' demektir, sormak için « Tu as un… ? » deriz.","examples":["J'ai un ballon.","J'ai une poupée.","Tu as un robot ?","Tom a une voiture."]},"questions":[{"q":"Qu'est-ce que Léa a dans son lit ?","a":"Elle a un nounours."},{"q":"Qu'est-ce que Mamie donne à Tom ?","a":"Elle donne une voiture."},{"q":"Qu'est-ce que Hugo a ?","a":"Il a un vélo et un ballon."}],"quiz":[{"q":"J'ai ___ poupée.","o":["un","une","le"],"a":1,"why":"poupée kız sözcük: une poupée"},{"q":"🤖 c'est…","o":["un robot","une voiture","un train"],"a":0,"why":""},{"q":"« Ballon » veut dire…","o":["top","araba","bebek"],"a":0,"why":""},{"q":"Tom a… ","o":["un vélo","une voiture","un puzzle"],"a":1,"why":"Mamie lui donne une voiture"}],"drills":[{"type":"Yerine koyma","prompt":"J'ai un ballon.","cue":"robot","answer":"J'ai un robot."},{"type":"Yerine koyma","prompt":"J'ai une poupée.","cue":"voiture","answer":"J'ai une voiture."},{"type":"Soru yap","prompt":"Tu as un vélo.","cue":"Est-ce que…?","answer":"Tu as un vélo ?"}],"sounds":[{"focus":"Lettres muettes","tr":"Fransızcada sözcüğün sonundaki bazı harfler okunmaz. 'Jouets' sözcüğünde t ve s söylenmez: 'jouè'. 'Ballons' sözcüğünde de s yoktur. Sondaki harfi söylememeye çalış!","pairs":["jouet / jouets","ballon / ballons"]}],"mission":{"brief":"Oyun: Oyuncak sohbeti! Claude, küçük Tom olacak. Ona oyuncaklarını sor ve kendi oyuncaklarını anlat.","persona":"Tom, a lively 5-year-old French boy. Uses extremely short French sentences. Asks one question at a time. Hidden fact: Tom's favourite toy is a robot named Bip, but he only says it if the child asks « Quel est ton jouet préféré ? ».","goal":"Tom'a oyuncaklarını sor ve 'J'ai un / une…' ile en az iki oyuncağını söyle.","opener":"Salut ! Moi, j'ai un robot. Et toi, tu as un jouet ?"}},"FK1-006":{"objectives":["Çiftlik hayvanlarının adlarını Fransızca söylemek","'Il y a… ' ile ne olduğunu söylemek","Hayvan seslerini ve 'J'aime…' ile sevdiğini anlatmak"],"dialogues":[{"title":"À la ferme de Mamie","setting":"Léa ve Tom, Mamie'nin çiftliğine ilk kez geliyor.","lines":[{"s":"Tom","en":"Mamie, il y a une vache !","tr":"Mamie, bir inek var!"},{"s":"Mamie","en":"Oui, elle s'appelle Marguerite. Elle fait « meuh » !","tr":"Evet, adı Marguerite. « Möö » der!"},{"s":"Léa","en":"Et là, il y a un cochon rose !","tr":"Şurada da pembe bir domuz var!"},{"s":"Mamie","en":"Il est gourmand. Il aime les pommes.","tr":"O çok obur. Elmaları sever."},{"s":"Tom","en":"Et les poules ? Elles font quoi ?","tr":"Peki tavuklar? Onlar ne der?"},{"s":"Mamie","en":"Elles font « cot-cot » !","tr":"« Gıt gıt » derler!"}]},{"title":"Le jeu des animaux","setting":"Papa, Léa ve Tom hayvan tahmin oyunu oynuyor.","lines":[{"s":"Papa","en":"Je suis blanc. Je fais « bêê ». Qui suis-je ?","tr":"Ben beyazım. « Mee » derim. Ben kimim?"},{"s":"Tom","en":"C'est un mouton !","tr":"Bir koyun!"},{"s":"Papa","en":"Bravo ! Je suis jaune. Je fais « coin-coin ».","tr":"Aferin! Ben sarıyım. « Vak vak » derim."},{"s":"Léa","en":"C'est un canard !","tr":"Bir ördek!"},{"s":"Papa","en":"Je suis grand. J'aime l'herbe.","tr":"Ben büyüğüm. Otu severim."},{"s":"Léa","en":"C'est un cheval !","tr":"Bir at!"}]},{"title":"Mon animal préféré","setting":"Elif ve Léa en sevdikleri hayvanları anlatıyor.","lines":[{"s":"Elif","en":"Léa, tu aimes les chevaux ?","tr":"Léa, atları sever misin?"},{"s":"Léa","en":"Oui, mais j'aime aussi le chien et le chat.","tr":"Evet, ama köpeği ve kediyi de severim."},{"s":"Elif","en":"Moi, j'ai un chien. Il s'appelle Rex.","tr":"Benim bir köpeğim var. Adı Rex."},{"s":"Léa","en":"Rex ? C'est aussi le chien de Mamie !","tr":"Rex mi? Mamie'nin köpeğinin adı da Rex!"},{"s":"Elif","en":"Haha ! Il y a beaucoup de Rex !","tr":"Haha! Çok fazla Rex var!"},{"s":"Léa","en":"On va à la ferme demain ?","tr":"Yarın çiftliğe gidelim mi?"}]}],"reading":{"title":"Les animaux de Mamie","paras":[{"en":"Mamie a une ferme. Il y a une vache, un cochon et un cheval. Il y a aussi trois poules et un mouton. Les canards sont dans la mare. Le chien de Mamie s'appelle Rex. Il garde les animaux. Le soir, le chat dort dans la grange. J'aime la ferme de Mamie !","tr":"Mamie'nin bir çiftliği var. Bir inek, bir domuz ve bir at var. Ayrıca üç tavuk ve bir koyun var. Ördekler gölette. Mamie'nin köpeğinin adı Rex. Hayvanları korur. Akşam kedi ahırda uyur. Mamie'nin çiftliğini seviyorum!"}]},"vocab":[{"w":"la vache","ipa":"/la vaʃ/","pos":"🐄","tr":"inek","ex":"Il y a une vache.","exTr":"Bir inek var."},{"w":"le cochon","ipa":"/lə kɔ.ʃɔ̃/","pos":"🐖","tr":"domuz","ex":"Il y a un cochon rose.","exTr":"Pembe bir domuz var."},{"w":"le cheval","ipa":"/lə ʃə.val/","pos":"🐴","tr":"at","ex":"C'est un cheval !","exTr":"Bu bir at!"},{"w":"la poule","ipa":"/la pul/","pos":"🐔","tr":"tavuk","ex":"Il y a trois poules.","exTr":"Üç tavuk var."},{"w":"le mouton","ipa":"/lə mu.tɔ̃/","pos":"🐑","tr":"koyun","ex":"C'est un mouton !","exTr":"Bu bir koyun!"},{"w":"le canard","ipa":"/lə ka.naʁ/","pos":"🦆","tr":"ördek","ex":"C'est un canard !","exTr":"Bu bir ördek!"},{"w":"le chien","ipa":"/lə ʃjɛ̃/","pos":"🐕","tr":"köpek","ex":"Le chien s'appelle Rex.","exTr":"Köpeğin adı Rex."},{"w":"le chat","ipa":"/lə ʃa/","pos":"🐈","tr":"kedi","ex":"Le chat dort dans la grange.","exTr":"Kedi ahırda uyur."}],"chunks":[{"en":"Il y a une vache.","tr":"Bir inek var."},{"en":"C'est quoi ?","tr":"Bu ne?"},{"en":"Il fait « coin-coin ».","tr":"« Vak vak » der."},{"en":"J'aime les animaux.","tr":"Hayvanları severim."}],"grammar":{"point":"Il y a…","tr":"Bir yerde bir şey olduğunu söylemek için « Il y a… » deriz. Hem tek hem çok sözcükle kullanılır: « Il y a un cheval », « Il y a trois poules ». Sormak için « Qu'est-ce qu'il y a ? » deriz, yani 'Orada ne var?'.","examples":["Il y a une vache.","Il y a un cheval.","Il y a trois poules.","Il y a un chien et un chat."]},"questions":[{"q":"Comment s'appelle la vache ?","a":"Elle s'appelle Marguerite."},{"q":"Comment s'appelle le chien de Mamie ?","a":"Il s'appelle Rex."},{"q":"Où sont les canards ?","a":"Ils sont dans la mare."}],"quiz":[{"q":"La vache fait…","o":["meuh","coin-coin","cot-cot"],"a":0,"why":""},{"q":"🐑 c'est…","o":["un cheval","un mouton","un cochon"],"a":1,"why":""},{"q":"Il y a ___ poules.","o":["trois","un","une"],"a":0,"why":"poules çoğul: trois poules"},{"q":"« Canard » veut dire…","o":["inek","at","ördek"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Il y a une vache.","cue":"cheval","answer":"Il y a un cheval."},{"type":"Yerine koyma","prompt":"Il y a un cochon.","cue":"poule / une","answer":"Il y a une poule."},{"type":"Genişletme","prompt":"Il y a un chien.","cue":"et un chat","answer":"Il y a un chien et un chat."}],"sounds":[{"focus":"/ɛ̃/","tr":"'Chien' sözcüğündeki 'ien' sesi burun sesidir. Ağzını 'e' der gibi aç, sesi burnundan çıkar ve n sesini söyleme: 'chien', 'pain'. 'Chat' ile karıştırma: 'chat' burun sesi içermez!","pairs":["chien / chat","pain / pas"]}],"mission":{"brief":"Oyun: Çiftlik gezisi! Claude, Mamie olacak. Çiftlikte ne olduğunu Fransızca sor ve hayvanların adlarını öğren.","persona":"Mamie, a warm French grandmother who owns a farm. Speaks in very short, slow French sentences. Asks one question at a time. Hidden fact: there is a baby lamb called Neige on the farm, but Mamie only tells it if the child asks « Il y a un bébé mouton ? ».","goal":"En az üç hayvanın adını 'Il y a…' ile söyle ya da sor.","opener":"Bonjour ! Bienvenue à ma ferme. Qu'est-ce que tu vois ?"}},"FK1-007":{"objectives":["Vahşi hayvanların adlarını Fransızca söylemek","'C'est un… / C'est une…' ile hayvanları tanıtmak","Hayvanları 'Il est grand !' gibi basit sözlerle tarif etmek"],"dialogues":[{"title":"Au zoo","setting":"Léa, Tom ve Papa hayvanat bahçesinde hayvanlara bakıyor.","lines":[{"s":"Papa","en":"Regardez, les enfants ! Nous sommes au zoo.","tr":"Bakın çocuklar! Hayvanat bahçesindeyiz."},{"s":"Tom","en":"Papa, c'est un lion ?","tr":"Baba, bu bir aslan mı?"},{"s":"Papa","en":"Oui, c'est un lion. Il est grand !","tr":"Evet, bu bir aslan. Çok büyük!"},{"s":"Léa","en":"Et là, c'est un tigre ?","tr":"Peki orada, o bir kaplan mı?"},{"s":"Papa","en":"Oui, Léa. C'est un tigre.","tr":"Evet Léa. O bir kaplan."},{"s":"Tom","en":"J'ai peur !","tr":"Korkuyorum!"},{"s":"Léa","en":"Ne t'inquiète pas, Tom. Je suis là !","tr":"Merak etme Tom. Ben yanındayım!"}]},{"title":"Les singes","setting":"Léa ve arkadaşı Elif maymunlara ve zürafaya bakıyor.","lines":[{"s":"Léa","en":"Elif, regarde le singe !","tr":"Elif, maymuna bak!"},{"s":"Elif","en":"Il est drôle ! Il mange une banane.","tr":"Çok komik! Muz yiyor."},{"s":"Léa","en":"Il y a deux singes.","tr":"İki maymun var."},{"s":"Elif","en":"Où est la girafe ?","tr":"Zürafa nerede?"},{"s":"Léa","en":"La girafe est là. Elle est très grande !","tr":"Zürafa şurada. Çok uzun!"},{"s":"Elif","en":"Oh oui, j'aime la girafe !","tr":"Evet, zürafayı seviyorum!"}]},{"title":"Quel animal ?","setting":"Madame Martin sınıfta hayvan tahmin oyunu oynatıyor.","lines":[{"s":"Madame Martin","en":"Quel animal est gris et très gros ?","tr":"Hangi hayvan gri ve çok iri?"},{"s":"Hugo","en":"C'est l'éléphant !","tr":"Fil!"},{"s":"Madame Martin","en":"Bravo, Hugo ! Quel animal est noir et blanc ?","tr":"Aferin Hugo! Hangi hayvan siyah beyaz?"},{"s":"Léa","en":"C'est le zèbre !","tr":"Zebra!"},{"s":"Madame Martin","en":"Oui ! Et l'ours, il est comment ?","tr":"Evet! Peki ayı nasıl?"},{"s":"Hugo","en":"Il est brun et il est fort !","tr":"Kahverengi ve güçlü!"},{"s":"Madame Martin","en":"Très bien ! Vous connaissez bien les animaux.","tr":"Çok güzel! Hayvanları iyi tanıyorsunuz."}]}],"reading":{"title":"Mon zoo","paras":[{"en":"Je m'appelle Léa. J'aime les animaux sauvages. Au zoo, il y a un lion et un tigre. Le lion est grand et fort. Il y a aussi un éléphant gris et une girafe jaune. Les singes sont drôles ! Mais je n'aime pas le serpent. Il fait peur à Tom. Moi, je préfère l'ours brun. C'est mon animal préféré !","tr":"Benim adım Léa. Vahşi hayvanları severim. Hayvanat bahçesinde bir aslan ve bir kaplan var. Aslan büyük ve güçlü. Ayrıca gri bir fil ve sarı bir zürafa var. Maymunlar çok komik! Ama yılanı sevmem. Tom'u korkutuyor. Ben kahverengi ayıyı tercih ederim. En sevdiğim hayvan o!"}]},"vocab":[{"w":"le lion","ipa":"/lə ljɔ̃/","pos":"🦁","tr":"aslan","ex":"C'est un lion.","exTr":"Bu bir aslan."},{"w":"l'éléphant","ipa":"/le.le.fɑ̃/","pos":"🐘","tr":"fil","ex":"C'est l'éléphant !","exTr":"Bu fil!"},{"w":"le singe","ipa":"/lə sɛ̃ʒ/","pos":"🐵","tr":"maymun","ex":"Regarde le singe !","exTr":"Maymuna bak!"},{"w":"la girafe","ipa":"/la ʒi.ʁaf/","pos":"🦒","tr":"zürafa","ex":"La girafe est très grande.","exTr":"Zürafa çok uzun."},{"w":"le tigre","ipa":"/lə tigʁ/","pos":"🐯","tr":"kaplan","ex":"C'est un tigre.","exTr":"Bu bir kaplan."},{"w":"l'ours","ipa":"/luʁs/","pos":"🐻","tr":"ayı","ex":"L'ours est brun.","exTr":"Ayı kahverengi."},{"w":"le zèbre","ipa":"/lə zɛbʁ/","pos":"🦓","tr":"zebra","ex":"C'est le zèbre !","exTr":"Bu zebra!"},{"w":"le serpent","ipa":"/lə sɛʁ.pɑ̃/","pos":"🐍","tr":"yılan","ex":"Je n'aime pas le serpent.","exTr":"Yılanı sevmem."}],"chunks":[{"en":"Regarde le lion !","tr":"Aslana bak!"},{"en":"C'est un tigre.","tr":"Bu bir kaplan."},{"en":"Il est grand !","tr":"Çok büyük!"},{"en":"J'ai peur !","tr":"Korkuyorum!"}],"grammar":{"point":"C'est un / une…","tr":"Bir şeyi tanıtırken 'C'est' deriz. Eril kelimelerin önüne 'un', dişil kelimelerin önüne 'une' gelir: 'C'est un lion.' 'C'est une girafe.' Sesli harfle başlayan kelimelerde 'le/la' yerine l' kullanırız: l'éléphant.","examples":["C'est un tigre.","C'est une girafe.","C'est l'éléphant !","C'est un singe ?"]},"questions":[{"q":"Où sont Léa, Tom et Papa ?","a":"Ils sont au zoo."},{"q":"Quel animal est gris et très gros ?","a":"C'est l'éléphant."},{"q":"Quel est l'animal préféré de Léa ?","a":"C'est l'ours brun."}],"quiz":[{"q":"🦒 C'est…","o":["un girafe","une girafe","le girafe"],"a":1,"why":"Girafe dişil olduğu için 'une' kullanılır."},{"q":"Quel animal est noir et blanc ?","o":["Le lion","L'éléphant","Le zèbre"],"a":2,"why":""},{"q":"Tom dit : « J'ai … ! »","o":["peur","faim","chaud"],"a":0,"why":"J'ai peur = Korkuyorum."},{"q":"Léa préfère…","o":["le serpent","l'ours","le tigre"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"C'est un lion.","cue":"tigre","answer":"C'est un tigre."},{"type":"Yerine koyma","prompt":"C'est un tigre.","cue":"girafe","answer":"C'est une girafe."},{"type":"Genişletme","prompt":"L'éléphant est gris.","cue":"+ très gros","answer":"L'éléphant est gris et très gros."}],"sounds":[{"focus":"/ɑ̃/ ve /ɔ̃/","tr":"Fransızca 'an, en' (/ɑ̃/) ve 'on' (/ɔ̃/) sesleri burundan çıkar ve sondaki n ayrıca söylenmez. Ağzını 'a' ya da 'o' der gibi şekillendir, sesi burnuna ver; Türkçedeki gibi 'an-n' deme: 'éléphant', 'serpent', 'lion'.","pairs":["blanc / bon","éléphant / lion","singe / serpent"]}],"mission":{"brief":"Oyun: Hayvanat bahçesi! Claude, arkadaşın Hugo olacak. Hayvanları Fransızca tanıt ve Hugo'ya en sevdiği hayvanı sor.","persona":"Hugo, a cheerful 7-year-old French boy at the zoo. Uses very short, simple French sentences and lots of encouragement. Asks one question at a time. Hidden fact: Hugo's favourite animal is the giraffe, but he only says it if the child asks « Quel est ton animal préféré ? ».","goal":"En az üç hayvanı 'C'est un / une…' ile tanıt.","opener":"Salut ! Je m'appelle Hugo. Regarde, un grand animal jaune ! C'est quoi ?"}},"FK1-008":{"objectives":["Vücut bölümlerinin adlarını Fransızca söylemek","'J'ai…' ile vücudumuzla ilgili basit cümleler kurmak","'J'ai mal à…' ile nerenin ağrıdığını söylemek"],"dialogues":[{"title":"Le jeu du corps","setting":"Madame Martin sınıfta vücut bölümleri oyunu oynatıyor.","lines":[{"s":"Madame Martin","en":"Les enfants, touchez votre nez !","tr":"Çocuklar, burnunuza dokunun!"},{"s":"Hugo","en":"Voilà mon nez !","tr":"İşte burnum!"},{"s":"Madame Martin","en":"Maintenant, touchez votre bouche.","tr":"Şimdi ağzınıza dokunun."},{"s":"Léa","en":"Ma bouche est ici !","tr":"Ağzım burada!"},{"s":"Madame Martin","en":"Levez la main !","tr":"Elinizi kaldırın!"},{"s":"Elif","en":"Madame, regardez mon bras !","tr":"Öğretmenim, koluma bakın!"},{"s":"Madame Martin","en":"Bravo, Elif ! Tu joues très bien.","tr":"Aferin Elif! Çok iyi oynuyorsun."}]},{"title":"Aïe !","setting":"Léa'nın ayağı ve bacağı ağrıyor, annesi ona bakıyor.","lines":[{"s":"Léa","en":"Aïe ! J'ai mal !","tr":"Of! Canım acıyor!"},{"s":"Maman","en":"Où as-tu mal, Léa ?","tr":"Neren ağrıyor Léa?"},{"s":"Léa","en":"J'ai mal au pied !","tr":"Ayağım ağrıyor!"},{"s":"Maman","en":"Ce n'est pas grave. Un petit bisou !","tr":"Önemli değil. Küçük bir öpücük!"},{"s":"Léa","en":"Mais j'ai mal à la jambe aussi.","tr":"Ama bacağım da ağrıyor."},{"s":"Maman","en":"Alors, repose-toi un peu.","tr":"O zaman biraz dinlen."},{"s":"Léa","en":"D'accord, Maman.","tr":"Tamam anne."}]},{"title":"Le monstre de Tom","setting":"Tom babasına çizdiği tuhaf canavarı gösteriyor.","lines":[{"s":"Tom","en":"Papa, regarde mon monstre ! Il a un œil.","tr":"Baba, canavarıma bak! Bir gözü var."},{"s":"Papa","en":"Un seul œil ? Et le nez ?","tr":"Tek göz mü? Peki burnu?"},{"s":"Tom","en":"Il a un grand nez et deux oreilles.","tr":"Büyük bir burnu ve iki kulağı var."},{"s":"Papa","en":"Et la bouche ?","tr":"Ya ağzı?"},{"s":"Tom","en":"Il a une bouche rouge et quatre bras !","tr":"Kırmızı bir ağzı ve dört kolu var!"},{"s":"Papa","en":"Quatre bras ! Il est super, ton monstre.","tr":"Dört kol! Canavarın harika."}]}],"reading":{"title":"Mon corps","paras":[{"en":"Voici mon corps. J'ai deux yeux, un nez et une bouche. J'ai aussi deux oreilles. Avec mes mains, je dessine. Avec mes pieds, je cours. Mes bras sont forts et mes jambes sont longues. Le monstre de Tom a un œil et quatre bras, mais moi, j'ai un corps normal. C'est super !","tr":"İşte vücudum. İki gözüm, bir burnum ve bir ağzım var. Ayrıca iki kulağım var. Ellerimle çizim yaparım. Ayaklarımla koşarım. Kollarım güçlü, bacaklarım uzun. Tom'un canavarının bir gözü ve dört kolu var ama benim vücudum normal. Harika!"}]},"vocab":[{"w":"la main","ipa":"/la mɛ̃/","pos":"✋","tr":"el","ex":"Levez la main !","exTr":"Elini kaldır!"},{"w":"le pied","ipa":"/lə pje/","pos":"🦶","tr":"ayak","ex":"J'ai mal au pied.","exTr":"Ayağım ağrıyor."},{"w":"l'œil","ipa":"/lœj/","pos":"👀","tr":"göz","ex":"Il a un œil.","exTr":"Bir gözü var."},{"w":"la bouche","ipa":"/la buʃ/","pos":"👄","tr":"ağız","ex":"Ma bouche est ici !","exTr":"Ağzım burada!"},{"w":"le nez","ipa":"/lə ne/","pos":"👃","tr":"burun","ex":"Touchez votre nez !","exTr":"Burnunuza dokunun!"},{"w":"l'oreille","ipa":"/lɔ.ʁɛj/","pos":"👂","tr":"kulak","ex":"Il a deux oreilles.","exTr":"İki kulağı var."},{"w":"la jambe","ipa":"/la ʒɑ̃b/","pos":"🦵","tr":"bacak","ex":"J'ai mal à la jambe.","exTr":"Bacağım ağrıyor."},{"w":"le bras","ipa":"/lə bʁa/","pos":"💪","tr":"kol","ex":"Regardez mon bras !","exTr":"Koluma bakın!"}],"chunks":[{"en":"Touchez votre nez !","tr":"Burnunuza dokunun!"},{"en":"Levez la main !","tr":"Elinizi kaldırın!"},{"en":"Où as-tu mal ?","tr":"Neren ağrıyor?"},{"en":"J'ai mal au pied.","tr":"Ayağım ağrıyor."}],"grammar":{"point":"J'ai… / Il a…","tr":"'Avoir' fiili 'sahip olmak' demektir. Ben için 'J'ai', o için 'il a / elle a' deriz: 'J'ai deux mains.' (İki elim var.) 'Je' sesli harf olan 'ai' ile karşılaşınca j'ai diye birleşir.","examples":["J'ai deux mains.","J'ai un grand nez.","Il a un œil.","Elle a deux oreilles."]},"questions":[{"q":"Qu'est-ce que Hugo touche ?","a":"Il touche son nez."},{"q":"Où Léa a-t-elle mal ?","a":"Elle a mal au pied et à la jambe."},{"q":"Combien de bras a le monstre de Tom ?","a":"Il a quatre bras."}],"quiz":[{"q":"👃 C'est…","o":["la bouche","le nez","l'oreille"],"a":1,"why":""},{"q":"J'ai deux ___.","o":["main","mains","le main"],"a":1,"why":"İki tane olduğu için 'mains' deriz."},{"q":"Léa a mal…","o":["à la jambe","à l'œil","au nez"],"a":0,"why":""},{"q":"Le monstre de Tom a ___ bras.","o":["un","deux","quatre"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"J'ai mal au pied.","cue":"jambe","answer":"J'ai mal à la jambe."},{"type":"Yerine koyma","prompt":"Il a un œil.","cue":"deux oreilles","answer":"Il a deux oreilles."},{"type":"Dönüştürme","prompt":"J'ai deux mains.","cue":"il","answer":"Il a deux mains."}],"sounds":[{"focus":"/y/ ve /u/","tr":"Fransızca 'u' (/y/) Türkçedeki 'ü' gibidir: dudaklarını yuvarla ve dilini 'i' derken olduğu gibi öne ver. 'ou' (/u/) ise Türkçedeki 'u' gibidir. 'rue' ile 'roue' farklı kelimelerdir, dikkat!","pairs":["roue / rue","bouche / bûche","tout / tu"]}],"mission":{"brief":"Oyun: Doktor oyunu! Claude, 5 yaşındaki Tom olacak. Sen doktorsun. Tom'a nerenin ağrıdığını sor ve vücut bölümlerini Fransızca söyle.","persona":"Tom, a 5-year-old French boy playing the patient. Uses very short, simple French and says « Aïe ! » a lot. Hidden fact: Tom has mal au bras, but he only says it if the child asks « Où as-tu mal ? ».","goal":"Tom'a 'Où as-tu mal ?' diye sor ve en az iki vücut bölümü söyle.","opener":"Bonjour, docteur ! Aïe, aïe, aïe !"}},"FK1-009":{"objectives":["Giysi adlarını Fransızca söylemek","'Je porte…' ile ne giydiğini anlatmak","Giysileri renkleriyle birlikte tarif etmek"],"dialogues":[{"title":"Il fait froid !","setting":"Léa sabah okula gitmeden önce annesiyle giyiniyor.","lines":[{"s":"Maman","en":"Léa, il fait froid ! Mets ton manteau.","tr":"Léa, hava soğuk! Montunu giy."},{"s":"Léa","en":"Je veux ma robe rouge, Maman !","tr":"Kırmızı elbisemi istiyorum anne!"},{"s":"Maman","en":"D'accord, mais avec le manteau.","tr":"Tamam ama montla birlikte."},{"s":"Léa","en":"Et mon écharpe ?","tr":"Peki atkım?"},{"s":"Maman","en":"La voilà ! Et tes gants aussi.","tr":"İşte burada! Eldivenlerin de."},{"s":"Léa","en":"Je suis prête !","tr":"Hazırım!"},{"s":"Maman","en":"Tu es très belle, ma chérie.","tr":"Çok güzelsin canım."}]},{"title":"Un cadeau de Mamie","setting":"Mamie, Tom'a yeni giysiler getirmiş.","lines":[{"s":"Mamie","en":"Tom, regarde ! Un pantalon bleu.","tr":"Tom bak! Mavi bir pantolon."},{"s":"Tom","en":"C'est pour qui ? Pour moi ?","tr":"Kimin için? Benim için mi?"},{"s":"Mamie","en":"Oui, c'est pour toi ! Et voici un t-shirt jaune.","tr":"Evet, senin için! İşte sarı bir tişört de."},{"s":"Tom","en":"J'aime le jaune ! Merci, Mamie !","tr":"Sarıyı severim! Teşekkürler Mamie!"},{"s":"Mamie","en":"Essaie ton t-shirt !","tr":"Tişörtünü bir dene!"},{"s":"Tom","en":"Il est trop grand !","tr":"Çok büyük!"},{"s":"Mamie","en":"Ce n'est pas grave, tu vas grandir !","tr":"Önemli değil, büyüyeceksin!"}]},{"title":"Dans la cour","setting":"Hugo ve Can okul bahçesinde yeni giysilerinden söz ediyor.","lines":[{"s":"Hugo","en":"Can, tu as un chapeau ?","tr":"Can, şapkan var mı?"},{"s":"Can","en":"Oui, j'ai un chapeau noir.","tr":"Evet, siyah bir şapkam var."},{"s":"Hugo","en":"Moi, j'ai de nouvelles chaussures.","tr":"Benim yeni ayakkabılarım var."},{"s":"Can","en":"Elles sont belles !","tr":"Çok güzeller!"},{"s":"Hugo","en":"Merci ! Elles sont vertes.","tr":"Teşekkürler! Yeşiller."},{"s":"Can","en":"Super ! Allons jouer dehors.","tr":"Süper! Hadi dışarıda oynayalım."}]}],"reading":{"title":"Mes vêtements","paras":[{"en":"Aujourd'hui, il fait froid. Je porte mon manteau rouge et mon écharpe. Je porte aussi des gants. Tom porte un pantalon bleu et un chapeau. Il est drôle ! À l'école, je porte une robe verte et mes chaussures blanches. Et toi, qu'est-ce que tu portes ?","tr":"Bugün hava soğuk. Kırmızı montumu ve atkımı giyiyorum. Eldiven de takıyorum. Tom mavi bir pantolon giyiyor ve bir şapka takıyor. Çok komik! Okulda yeşil bir elbise ve beyaz ayakkabılarımı giyerim. Peki sen ne giyiyorsun?"}]},"vocab":[{"w":"le pantalon","ipa":"/lə pɑ̃.ta.lɔ̃/","pos":"👖","tr":"pantolon","ex":"Tom porte un pantalon bleu.","exTr":"Tom mavi bir pantolon giyiyor."},{"w":"la robe","ipa":"/la ʁɔb/","pos":"👗","tr":"elbise","ex":"Je veux ma robe rouge.","exTr":"Kırmızı elbisemi istiyorum."},{"w":"le t-shirt","ipa":"/lə ti.ʃœʁt/","pos":"👕","tr":"tişört","ex":"Voici un t-shirt jaune.","exTr":"İşte sarı bir tişört."},{"w":"les chaussures","ipa":"/le ʃo.syʁ/","pos":"👟","tr":"ayakkabılar","ex":"Elles sont vertes.","exTr":"Yeşiller."},{"w":"le manteau","ipa":"/lə mɑ̃.to/","pos":"🧥","tr":"mont, palto","ex":"Mets ton manteau.","exTr":"Montunu giy."},{"w":"le chapeau","ipa":"/lə ʃa.po/","pos":"👒","tr":"şapka","ex":"J'ai un chapeau noir.","exTr":"Siyah bir şapkam var."},{"w":"l'écharpe","ipa":"/le.ʃaʁp/","pos":"🧣","tr":"atkı","ex":"Et mon écharpe ?","exTr":"Peki atkım?"},{"w":"les gants","ipa":"/le ɡɑ̃/","pos":"🧤","tr":"eldivenler","ex":"Et tes gants aussi.","exTr":"Eldivenlerin de."}],"chunks":[{"en":"Je porte une robe.","tr":"Elbise giyiyorum."},{"en":"Mets ton manteau !","tr":"Montunu giy!"},{"en":"Il fait froid.","tr":"Hava soğuk."},{"en":"Je suis prête !","tr":"Hazırım!"}],"grammar":{"point":"Je porte…","tr":"'Porter' giymek, takmak demektir. 'Je porte' = giyiyorum, 'il porte / elle porte' = o giyiyor. Eril kelimenin önüne 'un', dişil kelimenin önüne 'une', çoğul kelimenin önüne 'des' koyarız.","examples":["Je porte un pantalon.","Tom porte un chapeau.","Elle porte une robe.","Je porte des gants."]},"questions":[{"q":"Pourquoi Léa porte un manteau ?","a":"Parce qu'il fait froid."},{"q":"De quelle couleur est le pantalon de Tom ?","a":"Il est bleu."},{"q":"De quelle couleur sont les chaussures de Hugo ?","a":"Elles sont vertes."}],"quiz":[{"q":"🧤 Ce sont…","o":["un gant","des gants","une gants"],"a":1,"why":"Eldiven çoğul olduğu için 'des gants' deriz."},{"q":"Tom porte un pantalon…","o":["vert","jaune","bleu"],"a":2,"why":""},{"q":"Qui offre des vêtements à Tom ?","o":["Mamie","Maman","Papa"],"a":0,"why":""},{"q":"Hugo a de nouvelles…","o":["gants","chaussures","écharpes"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Tom porte un pantalon.","cue":"Léa / robe","answer":"Léa porte une robe."},{"type":"Dönüştürme","prompt":"Je porte une robe.","cue":"elle","answer":"Elle porte une robe."},{"type":"Genişletme","prompt":"Je porte un manteau.","cue":"rouge","answer":"Je porte un manteau rouge."}],"sounds":[{"focus":"Liaison /z/","tr":"Fransızca'da sesli harfle başlayan kelimeden önce, normalde okunmayan son 's' bağlanarak 'z' gibi okunur: 'les écharpes' → 'lez-écharpes'. Ama 'les gants'te bağ yoktur. Kelimeleri tek parça gibi söyle.","pairs":["les gants / les écharpes","des pantalons / des amis"]}],"mission":{"brief":"Oyun: Mamie'nin hediyesi! Claude, büyükanne Mamie olacak. Mamie'ye sorular sor ve giysilerin adlarını Fransızca söyle.","persona":"Mamie, a warm French grandmother who is knitting something. Uses very short, simple French and calls the child « ma puce ». Hidden fact: she is knitting a yellow hat for Tom, but she only says it if the child asks « C'est pour qui ? ».","goal":"Mamie'ye 'C'est pour qui ?' diye sor ve en az iki giysi söyle.","opener":"Coucou, ma puce ! Regarde, je tricote. Qu'est-ce que c'est ?"}},"FK1-010":{"objectives":["Sınıftaki eşyaların adlarını Fransızca söylemek","'Il y a…' ile sınıfta neler olduğunu anlatmak","'Où est… ?' ile bir şeyin nerede olduğunu sormak"],"dialogues":[{"title":"Bonjour, madame !","setting":"Sabah sınıfta Madame Martin dersi başlatıyor.","lines":[{"s":"Madame Martin","en":"Bonjour, les enfants ! Ouvrez votre cahier.","tr":"Günaydın çocuklar! Defterinizi açın."},{"s":"Léa","en":"Madame, où est mon crayon ?","tr":"Öğretmenim, kalemim nerede?"},{"s":"Madame Martin","en":"Regarde dans ta trousse.","tr":"Kalem kutuna bak."},{"s":"Léa","en":"Ah, le voilà ! Merci, madame.","tr":"Ah, işte burada! Teşekkürler öğretmenim."},{"s":"Madame Martin","en":"Maintenant, regardez le tableau.","tr":"Şimdi tahtaya bakın."},{"s":"Hugo","en":"Il y a un grand cœur !","tr":"Büyük bir kalp var!"},{"s":"Madame Martin","en":"Oui, Hugo. C'est un beau dessin.","tr":"Evet Hugo. Güzel bir çizim."}]},{"title":"Dans le cartable","setting":"Léa ve Elif çantalarında neler olduğunu konuşuyor.","lines":[{"s":"Elif","en":"Léa, qu'est-ce qu'il y a dans ton cartable ?","tr":"Léa, çantanda ne var?"},{"s":"Léa","en":"Il y a un livre et un cahier.","tr":"Bir kitap ve bir defter var."},{"s":"Elif","en":"Il y a une règle aussi ?","tr":"Cetvel de var mı?"},{"s":"Léa","en":"Non, ma règle est sur ma chaise.","tr":"Hayır, cetvelim sandalyemin üstünde."},{"s":"Elif","en":"Je te prête ma règle.","tr":"Sana cetvelimi ödünç veririm."},{"s":"Léa","en":"Merci, Elif ! Tu es gentille.","tr":"Teşekkürler Elif! Çok naziksin."}]},{"title":"Ma classe","setting":"Léa akşam babasına sınıfını anlatıyor.","lines":[{"s":"Papa","en":"Comment est ta classe, Léa ?","tr":"Sınıfın nasıl Léa?"},{"s":"Léa","en":"Elle est grande ! Il y a vingt chaises.","tr":"Büyük! Yirmi sandalye var."},{"s":"Papa","en":"Et il y a un tableau ?","tr":"Peki tahta var mı?"},{"s":"Léa","en":"Oui, un grand tableau vert !","tr":"Evet, büyük yeşil bir tahta!"},{"s":"Papa","en":"Tu aimes ta classe ?","tr":"Sınıfını seviyor musun?"},{"s":"Léa","en":"Oui, j'adore ma classe !","tr":"Evet, sınıfımı çok seviyorum!"}]}],"reading":{"title":"Ma classe","paras":[{"en":"Voici ma classe. Elle est grande et jolie. Il y a vingt chaises et un grand tableau vert. Sur mon bureau, il y a mon cahier, mon livre et ma trousse. Dans ma trousse, il y a un crayon et une règle. Mon cartable est rouge. J'aime ma classe, et j'aime Madame Martin !","tr":"İşte sınıfım. Büyük ve güzel. Yirmi sandalye ve büyük, yeşil bir tahta var. Sırada defterim, kitabım ve kalem kutum var. Kalem kutumda bir kurşun kalem ve bir cetvel var. Çantam kırmızı. Sınıfımı seviyorum ve Madame Martin'i seviyorum!"}]},"vocab":[{"w":"le cahier","ipa":"/lə ka.je/","pos":"📓","tr":"defter","ex":"Ouvrez votre cahier.","exTr":"Defterinizi açın."},{"w":"le crayon","ipa":"/lə kʁɛ.jɔ̃/","pos":"🖍","tr":"kurşun kalem","ex":"Où est mon crayon ?","exTr":"Kalemim nerede?"},{"w":"le livre","ipa":"/lə livʁ/","pos":"📖","tr":"kitap","ex":"Il y a un livre.","exTr":"Bir kitap var."},{"w":"la règle","ipa":"/la ʁɛɡl/","pos":"📏","tr":"cetvel","ex":"Je te prête ma règle.","exTr":"Sana cetvelimi ödünç veririm."},{"w":"la trousse","ipa":"/la tʁus/","pos":"👝","tr":"kalem kutusu","ex":"Regarde dans ta trousse.","exTr":"Kalem kutuna bak."},{"w":"le cartable","ipa":"/lə kaʁ.tabl/","pos":"🎒","tr":"okul çantası","ex":"Mon cartable est rouge.","exTr":"Okul çantam kırmızı."},{"w":"le tableau","ipa":"/lə ta.blo/","pos":"📋","tr":"tahta","ex":"Regardez le tableau.","exTr":"Tahtaya bakın."},{"w":"la chaise","ipa":"/la ʃɛz/","pos":"🪑","tr":"sandalye","ex":"Il y a vingt chaises.","exTr":"Yirmi sandalye var."}],"chunks":[{"en":"Où est mon crayon ?","tr":"Kalemim nerede?"},{"en":"Il y a un tableau.","tr":"Bir tahta var."},{"en":"Ouvrez votre cahier.","tr":"Defterinizi açın."},{"en":"Le voilà !","tr":"İşte burada!"}],"grammar":{"point":"Il y a…","tr":"Bir yerde bir şey olduğunu söylerken 'Il y a' deriz; 'var' demektir. Tekil ve çoğul için aynıdır: 'Il y a un livre.' 'Il y a vingt chaises.' Soru için 'Qu'est-ce qu'il y a ?' (Ne var?) deriz.","examples":["Il y a un livre.","Il y a une règle.","Il y a vingt chaises.","Qu'est-ce qu'il y a dans ton cartable ?"]},"questions":[{"q":"Où est le crayon de Léa ?","a":"Il est dans sa trousse."},{"q":"Qu'est-ce qu'il y a dans le cartable de Léa ?","a":"Il y a un livre et un cahier."},{"q":"Comment est la classe de Léa ?","a":"Elle est grande. Il y a vingt chaises."}],"quiz":[{"q":"📏 C'est…","o":["un cahier","une règle","un crayon"],"a":1,"why":"Règle dişil olduğu için 'une' deriz."},{"q":"Il y a ___ tableau vert.","o":["un","une","des"],"a":0,"why":"Tableau eril bir kelimedir."},{"q":"'Où est mon crayon ?' ne demek?","o":["Bu benim kalemim.","Kalem istiyorum.","Kalemim nerede?"],"a":2,"why":""},{"q":"Dans le cartable, il y a un livre et un…","o":["tableau","cahier","chaise"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Il y a un livre.","cue":"cahier","answer":"Il y a un cahier."},{"type":"Yerine koyma","prompt":"Il y a un crayon.","cue":"règle","answer":"Il y a une règle."},{"type":"Soru yap","prompt":"Mon crayon est dans la trousse.","cue":"Où… ?","answer":"Où est mon crayon ?"}],"sounds":[{"focus":"/ʁ/","tr":"Fransızca r, Türkçedeki gibi dil ucuyla değil, boğazın arkasından çıkar; hafif gargara yapar gibi, 'h' ile 'g' arası bir ses. Dilin ucu aşağıda kalır: 'règle', 'livre', 'cartable'.","pairs":["rire / lire","riz / lit"]}],"mission":{"brief":"Oyun: Kayıp kalem kutusu! Claude, öğretmen Madame Martin olacak. Madame Martin'e kalem kutusunda ne olduğunu sor ve sınıftaki eşyaları Fransızca söyle.","persona":"Madame Martin, a kind French primary-school teacher who has lost her pencil case (la trousse) in the classroom. Uses very short, simple French. Hidden fact: her trousse contains a green ruler and two pencils, but she only says it if the child asks « Qu'est-ce qu'il y a dans ta trousse ? ».","goal":"'Il y a…' ile sınıftaki en az üç şeyi söyle.","opener":"Bonjour ! Oh là là, je cherche ma trousse. Tu m'aides ?"}},"FK1-011":{"objectives":["Meyve ve sebze adlarını Fransızca söylemek","'J'aime…' ve 'Je n'aime pas…' ile sevdiğin ve sevmediğin şeyleri söylemek","Pazarda 's'il vous plaît' diyerek bir şey istemek"],"dialogues":[{"title":"Au marché","setting":"Léa ve annesi cumartesi pazarında meyve alıyor.","lines":[{"s":"Le marchand","en":"Bonjour ! Qu'est-ce que vous voulez ?","tr":"Günaydın! Ne istersiniz?"},{"s":"Maman","en":"Bonjour, monsieur. Des pommes, s'il vous plaît.","tr":"Günaydın efendim. Elma lütfen."},{"s":"Léa","en":"Maman, je veux des fraises !","tr":"Anne, çilek istiyorum!"},{"s":"Le marchand","en":"Voilà des fraises rouges et sucrées.","tr":"İşte kırmızı, tatlı çilekler."},{"s":"Maman","en":"Et deux bananes, s'il vous plaît.","tr":"Bir de iki muz lütfen."},{"s":"Léa","en":"Et du raisin, Maman ?","tr":"Üzüm de alalım mı anne?"},{"s":"Maman","en":"Oui, du raisin aussi. Merci, monsieur !","tr":"Evet, üzüm de. Teşekkürler efendim!"}]},{"title":"Les légumes","setting":"Papa, Tom'a hangi sebzeleri sevdiğini soruyor.","lines":[{"s":"Papa","en":"Tom, tu aimes les carottes ?","tr":"Tom, havuçları sever misin?"},{"s":"Tom","en":"Non, je n'aime pas les carottes.","tr":"Hayır, havuçları sevmem."},{"s":"Papa","en":"Et les tomates ?","tr":"Peki domatesler?"},{"s":"Tom","en":"J'aime les tomates !","tr":"Domatesleri severim!"},{"s":"Papa","en":"Et les pommes de terre ?","tr":"Ya patatesler?"},{"s":"Tom","en":"Oui ! J'adore les pommes de terre !","tr":"Evet! Patatesleri çok severim!"},{"s":"Papa","en":"Alors ce soir, il y a des pommes de terre et des tomates !","tr":"O zaman bu akşam patates ve domates var!"}]},{"title":"Le goûter","setting":"Hugo ve Elif okulda ikindi atıştırmalığını paylaşıyor.","lines":[{"s":"Hugo","en":"Elif, tu as une orange ?","tr":"Elif, portakalın var mı?"},{"s":"Elif","en":"Oui, j'ai une orange et une banane.","tr":"Evet, bir portakalım ve bir muzum var."},{"s":"Hugo","en":"Moi, j'ai une pomme.","tr":"Benim bir elmam var."},{"s":"Elif","en":"Tu veux mon orange ?","tr":"Portakalımı ister misin?"},{"s":"Hugo","en":"Oui, merci ! Tu veux ma pomme ?","tr":"Evet, sağ ol! Sen elmamı ister misin?"},{"s":"Elif","en":"Oui, avec plaisir !","tr":"Evet, memnuniyetle!"}]}],"reading":{"title":"Au marché","paras":[{"en":"Le samedi, je vais au marché avec Maman. Il y a des fruits et des légumes. J'aime les fraises et les bananes. Tom aime les tomates, mais il n'aime pas les carottes. Maman achète du raisin, des oranges et des pommes de terre. Le marché est beau et coloré. Moi, j'adore le samedi !","tr":"Cumartesi günleri annemle pazara giderim. Orada meyveler ve sebzeler var. Çilekleri ve muzları severim. Tom domatesleri seviyor ama havuçları sevmiyor. Annem üzüm, portakal ve patates alıyor. Pazar güzel ve rengârenk. Cumartesiyi çok seviyorum!"}]},"vocab":[{"w":"la pomme","ipa":"/la pɔm/","pos":"🍎","tr":"elma","ex":"Des pommes, s'il vous plaît.","exTr":"Elma lütfen."},{"w":"la banane","ipa":"/la ba.nan/","pos":"🍌","tr":"muz","ex":"J'ai une orange et une banane.","exTr":"Bir portakalım ve bir muzum var."},{"w":"la fraise","ipa":"/la fʁɛz/","pos":"🍓","tr":"çilek","ex":"Je veux des fraises !","exTr":"Çilek istiyorum!"},{"w":"l'orange","ipa":"/lɔ.ʁɑ̃ʒ/","pos":"🍊","tr":"portakal","ex":"Tu as une orange ?","exTr":"Portakalın var mı?"},{"w":"la carotte","ipa":"/la ka.ʁɔt/","pos":"🥕","tr":"havuç","ex":"Je n'aime pas les carottes.","exTr":"Havuçları sevmem."},{"w":"la tomate","ipa":"/la tɔ.mat/","pos":"🍅","tr":"domates","ex":"J'aime les tomates !","exTr":"Domatesleri severim!"},{"w":"la pomme de terre","ipa":"/la pɔm də tɛʁ/","pos":"🥔","tr":"patates","ex":"J'adore les pommes de terre !","exTr":"Patatesleri çok severim!"},{"w":"le raisin","ipa":"/lə ʁɛ.zɛ̃/","pos":"🍇","tr":"üzüm","ex":"Et du raisin, Maman ?","exTr":"Üzüm de alalım mı anne?"}],"chunks":[{"en":"Des pommes, s'il vous plaît.","tr":"Elma lütfen."},{"en":"J'aime les fraises.","tr":"Çilekleri severim."},{"en":"Je n'aime pas les carottes.","tr":"Havuçları sevmem."},{"en":"Tu veux mon orange ?","tr":"Portakalımı ister misin?"}],"grammar":{"point":"J'aime… / Je n'aime pas…","tr":"Sevdiğimiz şeyi 'J'aime', sevmediğimizi 'Je n'aime pas' diye söyleriz. Genel olarak ya da çoğul söylerken 'les' kullanırız: 'J'aime les fraises.' Soru için 'Tu aimes… ?' deriz.","examples":["J'aime les fraises.","J'aime les tomates.","Je n'aime pas les carottes.","Tu aimes les bananes ?"]},"questions":[{"q":"Qu'est-ce que Léa veut au marché ?","a":"Elle veut des fraises."},{"q":"Est-ce que Tom aime les carottes ?","a":"Non, il n'aime pas les carottes."},{"q":"Qu'est-ce que Hugo donne à Elif ?","a":"Il donne une pomme."}],"quiz":[{"q":"🍓 C'est…","o":["un fraise","une orange","une fraise"],"a":2,"why":"Fraise dişil olduğu için 'une' deriz."},{"q":"Tom n'aime pas les…","o":["carottes","tomates","pommes de terre"],"a":0,"why":""},{"q":"'Je n'aime pas' ne demek?","o":["Seviyorum","Sevmiyorum","İstiyorum"],"a":1,"why":""},{"q":"Les fraises du marchand sont…","o":["rouges","bleues","vertes"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"J'aime les fraises.","cue":"tomates","answer":"J'aime les tomates."},{"type":"Dönüştürme","prompt":"J'aime les carottes.","cue":"négatif","answer":"Je n'aime pas les carottes."},{"type":"Yerine koyma","prompt":"J'ai une orange.","cue":"pomme","answer":"J'ai une pomme."}],"sounds":[{"focus":"/ɛ̃/","tr":"Fransızca 'in, ain, ein' yazılışları burundan çıkan /ɛ̃/ sesini verir. Ağzını 'e' ile 'a' arası bir şekilde aç, sesi burnundan geçir ve sondaki n'yi ayrıca söyleme: 'raisin', 'pain'.","pairs":["pain / main","raisin / matin"]}],"mission":{"brief":"Oyun: Pazar! Claude, manav Monsieur Paul olacak. 'Des pommes, s'il vous plaît' diyerek meyve ve sebze iste ve ne sevdiğini söyle.","persona":"Monsieur Paul, a friendly French fruit-and-vegetable seller at a market. Uses very short, simple French and smiles a lot. Hidden fact: his favourite fruit is the orange, but he only says it if the child asks « Quel est ton fruit préféré ? ».","goal":"En az üç meyve veya sebze iste ve 'J'aime…' ile bir şey söyle.","opener":"Bonjour, mademoiselle ! Qu'est-ce que vous voulez ?"}},"FK1-012":{"objectives":["Yemek adlarını Fransızca söylemek","'Mon plat préféré, c'est…' ile en sevdiği yemeği anlatmak","'Quel est ton plat préféré ?' sorusunu sormak"],"dialogues":[{"title":"À table !","setting":"Léa ve Tom annesiyle akşam yemeğinde.","lines":[{"s":"Maman","en":"À table, les enfants ! Il y a du poulet et du riz.","tr":"Sofraya çocuklar! Tavuk ve pilav var."},{"s":"Tom","en":"Beurk ! Je n'aime pas le riz !","tr":"İğ! Pilavı sevmem!"},{"s":"Léa","en":"Moi, j'aime le riz avec le poulet.","tr":"Ben pilavı tavukla severim."},{"s":"Maman","en":"Tom, goûte un peu.","tr":"Tom, azıcık tat."},{"s":"Tom","en":"Mmm… C'est bon !","tr":"Mmm… Güzelmiş!"},{"s":"Léa","en":"Tu vois ? Le riz, c'est bon !","tr":"Gördün mü? Pilav güzel!"},{"s":"Maman","en":"Bravo, mes chéris !","tr":"Aferin canlarım!"}]},{"title":"Chez Mamie","setting":"Léa hafta sonu Mamie'nin evinde yemek yiyor.","lines":[{"s":"Mamie","en":"Léa, aujourd'hui, il y a de la soupe.","tr":"Léa, bugün çorba var."},{"s":"Léa","en":"Miam ! Et un gâteau, Mamie ?","tr":"Yaşasın! Peki pasta var mı Mamie?"},{"s":"Mamie","en":"Oui, un gâteau au chocolat. Mais d'abord, la soupe.","tr":"Evet, çikolatalı pasta. Ama önce çorba."},{"s":"Léa","en":"D'accord. Je mange la soupe avec du pain.","tr":"Tamam. Çorbayı ekmekle yerim."},{"s":"Mamie","en":"Tu es gentille, ma puce.","tr":"Çok tatlısın küçüğüm."},{"s":"Léa","en":"Et après, le gâteau !","tr":"Sonra da pasta!"}]},{"title":"Quel est ton plat préféré ?","setting":"Madame Martin sınıfta çocuklara en sevdikleri yemeği soruyor.","lines":[{"s":"Madame Martin","en":"Hugo, quel est ton plat préféré ?","tr":"Hugo, en sevdiğin yemek ne?"},{"s":"Hugo","en":"Mon plat préféré, c'est la pizza !","tr":"En sevdiğim yemek pizza!"},{"s":"Madame Martin","en":"Et toi, Léa ?","tr":"Peki sen Léa?"},{"s":"Léa","en":"J'adore les pâtes avec du fromage !","tr":"Peynirli makarnaya bayılırım!"},{"s":"Madame Martin","en":"Hmm, du fromage, miam ! Et Elif ?","tr":"Hmm, peynir, nefis! Peki Elif?"},{"s":"Elif","en":"Mon plat préféré, c'est le gâteau de ma maman.","tr":"En sevdiğim yemek annemin pastası."},{"s":"Madame Martin","en":"Maintenant, tout le monde a faim !","tr":"Şimdi herkesin karnı acıktı!"}]}],"reading":{"title":"Le dimanche","paras":[{"en":"Le dimanche, nous mangeons tous ensemble. Mon plat préféré, ce sont les pâtes avec du fromage. Papa fait les pâtes. Tom aime le poulet avec du riz. Mamie fait une bonne soupe avec du pain. Pour le dessert, il y a un gâteau. Le dimanche, c'est un jour super !","tr":"Pazar günleri hep birlikte yemek yeriz. En sevdiğim yemek peynirli makarna. Makarnayı babam yapar. Tom pilavlı tavuğu seviyor. Mamie ekmekle birlikte güzel bir çorba yapar. Tatlı olarak bir pasta var. Pazar günü harika bir gün!"}]},"vocab":[{"w":"le fromage","ipa":"/lə fʁɔ.maʒ/","pos":"🧀","tr":"peynir","ex":"J'adore les pâtes avec du fromage !","exTr":"Peynirli makarnaya bayılırım!"},{"w":"le pain","ipa":"/lə pɛ̃/","pos":"🍞","tr":"ekmek","ex":"Je mange la soupe avec du pain.","exTr":"Çorbayı ekmekle yerim."},{"w":"les pâtes","ipa":"/le pɑt/","pos":"🍝","tr":"makarna","ex":"J'adore les pâtes !","exTr":"Makarnaya bayılırım!"},{"w":"le poulet","ipa":"/lə pu.lɛ/","pos":"🍗","tr":"tavuk","ex":"Il y a du poulet et du riz.","exTr":"Tavuk ve pilav var."},{"w":"le riz","ipa":"/lə ʁi/","pos":"🍚","tr":"pilav","ex":"Je n'aime pas le riz.","exTr":"Pilavı sevmem."},{"w":"la soupe","ipa":"/la sup/","pos":"🍲","tr":"çorba","ex":"Aujourd'hui, il y a de la soupe.","exTr":"Bugün çorba var."},{"w":"le gâteau","ipa":"/lə ɡɑ.to/","pos":"🍰","tr":"pasta, kek","ex":"Et après, le gâteau !","exTr":"Sonra da pasta!"},{"w":"la pizza","ipa":"/la pid.za/","pos":"🍕","tr":"pizza","ex":"Mon plat préféré, c'est la pizza !","exTr":"En sevdiğim yemek pizza!"}],"chunks":[{"en":"À table !","tr":"Sofraya!"},{"en":"C'est bon !","tr":"Güzel!"},{"en":"Quel est ton plat préféré ?","tr":"En sevdiğin yemek ne?"},{"en":"Mon plat préféré, c'est la pizza.","tr":"En sevdiğim yemek pizza."}],"grammar":{"point":"Mon plat préféré, c'est…","tr":"En sevdiğimiz yemeği 'Mon plat préféré, c'est…' diyerek söyleriz. Yemeğin önüne 'le', 'la' ya da 'l'' koyarız. Karşımızdakine 'Quel est ton plat préféré ?' diye sorarız.","examples":["Mon plat préféré, c'est la pizza.","Mon plat préféré, c'est le poulet.","Mon plat préféré, c'est la soupe.","Quel est ton plat préféré ?"]},"questions":[{"q":"Qu'est-ce que Tom n'aime pas ?","a":"Il n'aime pas le riz."},{"q":"Quel est le plat préféré de Hugo ?","a":"C'est la pizza."},{"q":"Qu'est-ce que Léa mange avec la soupe chez Mamie ?","a":"Elle mange du pain."}],"quiz":[{"q":"🍕 C'est…","o":["la pizza","le pizza","les pizza"],"a":0,"why":"Pizza dişil olduğu için 'la pizza' deriz."},{"q":"Léa aime les pâtes avec du…","o":["riz","poulet","fromage"],"a":2,"why":""},{"q":"Mamie fait une bonne…","o":["pizza","soupe","pâtes"],"a":1,"why":""},{"q":"Quel est ton plat préféré ?","o":["Je m'appelle Léa.","J'ai six ans.","Mon plat préféré, c'est le gâteau."],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Mon plat préféré, c'est la pizza.","cue":"soupe","answer":"Mon plat préféré, c'est la soupe."},{"type":"Yerine koyma","prompt":"Mon plat préféré, c'est le poulet.","cue":"gâteau","answer":"Mon plat préféré, c'est le gâteau."},{"type":"Soru yap","prompt":"Mon plat préféré, c'est la pizza.","cue":"Quel… ?","answer":"Quel est ton plat préféré ?"}],"sounds":[{"focus":"Sessiz son harfler","tr":"Fransızca'da kelime sonundaki harflerin çoğu okunmaz: 'poulet' kelimesinde t, 'riz' kelimesinde z, 'pain' kelimesinde n duyulmaz. Dişil halde ise son ünsüz duyulur: 'petit' [pəti], 'petite' [pətit].","pairs":["petit / petite","chaud / chaude","grand / grande"]}],"mission":{"brief":"Oyun: Yemek sohbeti! Claude, arkadaşın Hugo olacak. Hugo'ya en sevdiği yemeği sor ve kendi en sevdiğin yemeği Fransızca anlat.","persona":"Hugo, a cheerful 7-year-old French boy. Uses very short, simple French and asks one question at a time. Hidden fact: Hugo's favourite dessert is the chocolate cake made by his Mamie, but he only says it if the child asks « Et ton dessert préféré ? ».","goal":"'Quel est ton plat préféré ?' diye sor ve 'Mon plat préféré, c'est…' ile yanıt ver.","opener":"Salut ! J'ai faim ! Mon plat préféré, c'est la pizza. Et toi ?"}},"FK1-013":{"objectives":["Havayı Fransızca söylemek: il fait chaud, il pleut…","'Quel temps fait-il ?' sorusunu sormak ve yanıtlamak","Güneş, yağmur, rüzgâr ve kar gibi kelimeleri kullanmak"],"dialogues":[{"title":"Il fait beau !","setting":"Léa ve Tom sabah pencereden havaya bakıyor.","lines":[{"s":"Léa","en":"Tom, regarde ! Il fait beau !","tr":"Tom, bak! Hava güzel!"},{"s":"Tom","en":"Oui ! Il y a du soleil.","tr":"Evet! Güneş var."},{"s":"Léa","en":"Il fait chaud ?","tr":"Hava sıcak mı?"},{"s":"Tom","en":"Oui, il fait chaud !","tr":"Evet, hava sıcak!"},{"s":"Léa","en":"On joue dehors ?","tr":"Dışarıda oynayalım mı?"},{"s":"Tom","en":"Oui, super !","tr":"Evet, harika!"}]},{"title":"Il pleut !","setting":"Dışarıda yağmur yağıyor; Maman ve Léa evden çıkmaya hazırlanıyor.","lines":[{"s":"Maman","en":"Quel temps fait-il, Léa ?","tr":"Hava nasıl, Léa?"},{"s":"Léa","en":"Il pleut, Maman. Je vois la pluie.","tr":"Yağmur yağıyor anne. Yağmuru görüyorum."},{"s":"Maman","en":"Prends ton parapluie !","tr":"Şemsiyeni al!"},{"s":"Léa","en":"Il est où ?","tr":"Nerede?"},{"s":"Maman","en":"Il est dans l'entrée.","tr":"Girişte."},{"s":"Léa","en":"Le voilà ! Merci.","tr":"İşte burada! Teşekkürler."}]},{"title":"En classe","setting":"Sınıfta Madame Martin çocuklara bugünkü havayı soruyor.","lines":[{"s":"Madame Martin","en":"Quel temps fait-il aujourd'hui ?","tr":"Bugün hava nasıl?"},{"s":"Hugo","en":"Il fait froid. Il y a du vent !","tr":"Hava soğuk. Rüzgâr var!"},{"s":"Elif","en":"Regardez, il neige !","tr":"Bakın, kar yağıyor!"},{"s":"Madame Martin","en":"Oui, c'est la neige. Elle est blanche.","tr":"Evet, bu kar. Beyaz."},{"s":"Hugo","en":"Il y a un gros nuage gris.","tr":"Büyük gri bir bulut var."},{"s":"Madame Martin","en":"Bravo, les enfants !","tr":"Aferin çocuklar!"}]}],"reading":{"title":"Le temps d'aujourd'hui","paras":[{"en":"Je m'appelle Léa. Aujourd'hui, il fait beau. Il y a du soleil et il fait chaud. Tom et moi, nous jouons dans le jardin. Soudain, un nuage arrive avec le vent. Il pleut ! Nous courons sous le parapluie de Papa. Demain, il fait froid et il neige peut-être. J'aime la pluie et la neige !","tr":"Benim adım Léa. Bugün hava güzel. Güneş var ve hava sıcak. Tom'la ben bahçede oynuyoruz. Birden rüzgârla birlikte bir bulut geliyor. Yağmur yağıyor! Babamın şemsiyesinin altında koşuyoruz. Yarın belki hava soğuk olur ve kar yağar. Yağmuru da karı da severim!"}]},"vocab":[{"w":"le soleil","ipa":"/lə sɔ.lɛj/","pos":"☀️","tr":"güneş","ex":"Il y a du soleil.","exTr":"Güneş var."},{"w":"la pluie","ipa":"/la plɥi/","pos":"🌧️","tr":"yağmur","ex":"Je vois la pluie.","exTr":"Yağmuru görüyorum."},{"w":"le vent","ipa":"/lə vɑ̃/","pos":"💨","tr":"rüzgâr","ex":"Il y a du vent !","exTr":"Rüzgâr var!"},{"w":"la neige","ipa":"/la nɛʒ/","pos":"❄️","tr":"kar","ex":"C'est la neige.","exTr":"Bu kar."},{"w":"le nuage","ipa":"/lə nɥaʒ/","pos":"☁️","tr":"bulut","ex":"Il y a un gros nuage gris.","exTr":"Büyük gri bir bulut var."},{"w":"chaud","ipa":"/ʃo/","pos":"🥵","tr":"sıcak","ex":"Il fait chaud !","exTr":"Hava sıcak!"},{"w":"froid","ipa":"/fʁwa/","pos":"🥶","tr":"soğuk","ex":"Il fait froid.","exTr":"Hava soğuk."},{"w":"le parapluie","ipa":"/lə pa.ʁa.plɥi/","pos":"☂️","tr":"şemsiye","ex":"Prends ton parapluie !","exTr":"Şemsiyeni al!"}],"chunks":[{"en":"Quel temps fait-il ?","tr":"Hava nasıl?"},{"en":"Il fait beau.","tr":"Hava güzel."},{"en":"Il pleut.","tr":"Yağmur yağıyor."},{"en":"Il y a du soleil.","tr":"Güneş var."}],"grammar":{"point":"Il fait… / Il y a…","tr":"Havayı anlatırken 'Il fait…' kullanırız: il fait chaud (sıcak), il fait froid (soğuk). Bir şeyin var olduğunu söylerken 'Il y a…' deriz: il y a du vent. Yağmur ve kar için fiil kullanırız: il pleut, il neige.","examples":["Il fait chaud.","Il fait froid.","Il pleut.","Il y a du soleil."]},"questions":[{"q":"Quel temps fait-il au début ?","a":"Il fait beau et chaud."},{"q":"Qui a un parapluie dans l'histoire de Léa ?","a":"Papa."},{"q":"Qu'est-ce qui arrive avec le vent ?","a":"Un nuage."}],"quiz":[{"q":"☀️ = ?","o":["la pluie","le soleil","la neige"],"a":1,"why":""},{"q":"Quand il y a de la neige, il fait…","o":["chaud","beau","froid"],"a":2,"why":"Kar olunca hava soğuktur."},{"q":"« ___ temps fait-il ? »","o":["Quel","Qui","Où"],"a":0,"why":""},{"q":"Léa prend…","o":["un nuage","un parapluie","le vent"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Il fait chaud.","cue":"froid","answer":"Il fait froid."},{"type":"Dönüştürme","prompt":"Il fait beau.","cue":"Il pleut","answer":"Il pleut."},{"type":"Soru yap","prompt":"Il fait froid.","cue":"Quel…?","answer":"Quel temps fait-il ?"}],"sounds":[{"focus":"/ʁ/","tr":"Fransızca r, Türkçedeki r gibi dil ucuyla çıkmaz. Dilin ucu alt dişlerin arkasında kalır, boğazın arkasından hafif bir 'hırıltı' gibi çıkar: 'froid', 'pluie'.","pairs":["rue / lu","froid / roi"]}],"mission":{"brief":"Oyun: Hava durumu görüşmesi! Claude, Fransa'da yaşayan arkadaşın Hugo olacak. Hugo'ya havanın nasıl olduğunu Fransızca sor ve kendi bulunduğun yerin havasını söyle.","persona":"Hugo, a cheerful 7-year-old French boy on a video call. Uses very short simple French sentences. Hidden fact: it is snowing at Hugo's house today, but he only says so if the child asks « Quel temps fait-il ? ».","goal":"Hugo'ya 'Quel temps fait-il ?' diye sor ve en az iki hava durumu söyle.","opener":"Salut ! Je suis Hugo. Chez toi, il fait beau ?"}},"FK1-014":{"objectives":["Haftanın günlerini Fransızca sırayla saymak","'C'est quel jour ?' sorusunu sormak ve yanıtlamak","Hafta içi ve hafta sonu planlarını kısaca anlatmak"],"dialogues":[{"title":"C'est quel jour ?","setting":"Tom, Léa'ya bugünün hangi gün olduğunu soruyor.","lines":[{"s":"Tom","en":"Léa, c'est quel jour aujourd'hui ?","tr":"Léa, bugün hangi gün?"},{"s":"Léa","en":"C'est lundi.","tr":"Pazartesi."},{"s":"Tom","en":"Lundi ? On va à l'école ?","tr":"Pazartesi mi? Okula gidiyor muyuz?"},{"s":"Léa","en":"Oui, on va à l'école.","tr":"Evet, okula gidiyoruz."},{"s":"Tom","en":"Et demain ?","tr":"Peki yarın?"},{"s":"Léa","en":"Demain, c'est mardi.","tr":"Yarın salı."}]},{"title":"La semaine","setting":"Madame Martin sınıfta haftanın günlerini öğretiyor.","lines":[{"s":"Madame Martin","en":"Il y a sept jours dans la semaine.","tr":"Haftada yedi gün var."},{"s":"Hugo","en":"Lundi, mardi, mercredi !","tr":"Pazartesi, salı, çarşamba!"},{"s":"Madame Martin","en":"Très bien ! Et après ?","tr":"Çok iyi! Peki sonra?"},{"s":"Elif","en":"Jeudi et vendredi !","tr":"Perşembe ve cuma!"},{"s":"Madame Martin","en":"Bravo, Elif !","tr":"Aferin Elif!"},{"s":"Hugo","en":"Après, c'est samedi et dimanche.","tr":"Sonra cumartesi ve pazar."}]},{"title":"Le week-end","setting":"Papa ve Léa hafta sonu için plan yapıyor.","lines":[{"s":"Papa","en":"Léa, samedi, on va chez Mamie.","tr":"Léa, cumartesi büyükanneye gidiyoruz."},{"s":"Léa","en":"Super ! Et dimanche ?","tr":"Harika! Peki pazar?"},{"s":"Papa","en":"Dimanche, on joue au parc.","tr":"Pazar günü parkta oynuyoruz."},{"s":"Léa","en":"J'aime le week-end !","tr":"Hafta sonunu seviyorum!"},{"s":"Papa","en":"Moi aussi. Pas d'école !","tr":"Ben de. Okul yok!"}]}],"reading":{"title":"Ma semaine","paras":[{"en":"Je suis Léa. Il y a sept jours dans la semaine. Le lundi, le mardi, le jeudi et le vendredi, je vais à l'école. Le mercredi, je fais de la danse. Le samedi, je vais chez Mamie. Le dimanche, je joue avec Tom et Papa. J'aime le dimanche ! Et toi, quel jour tu aimes ?","tr":"Ben Léa. Haftada yedi gün var. Pazartesi, salı, perşembe ve cuma okula gidiyorum. Çarşamba dans yapıyorum. Cumartesi büyükanneme gidiyorum. Pazar günü Tom ve babamla oynuyorum. Pazarı seviyorum! Peki sen hangi günü seversin?"}]},"vocab":[{"w":"lundi","ipa":"/lœ̃.di/","pos":"1️⃣","tr":"pazartesi","ex":"Lundi, on va à l'école.","exTr":"Pazartesi okula gidiyoruz."},{"w":"mardi","ipa":"/maʁ.di/","pos":"2️⃣","tr":"salı","ex":"Demain, c'est mardi.","exTr":"Yarın salı."},{"w":"mercredi","ipa":"/mɛʁ.kʁə.di/","pos":"3️⃣","tr":"çarşamba","ex":"Le mercredi, je fais de la danse.","exTr":"Çarşamba dans yapıyorum."},{"w":"jeudi","ipa":"/ʒø.di/","pos":"4️⃣","tr":"perşembe","ex":"Jeudi et vendredi !","exTr":"Perşembe ve cuma!"},{"w":"vendredi","ipa":"/vɑ̃.dʁə.di/","pos":"5️⃣","tr":"cuma","ex":"Le vendredi, je vais à l'école.","exTr":"Cuma okula gidiyorum."},{"w":"samedi","ipa":"/sam.di/","pos":"🎉","tr":"cumartesi","ex":"Samedi, on va chez Mamie.","exTr":"Cumartesi büyükanneye gidiyoruz."},{"w":"dimanche","ipa":"/di.mɑ̃ʃ/","pos":"🌞","tr":"pazar","ex":"Dimanche, on joue au parc.","exTr":"Pazar günü parkta oynuyoruz."},{"w":"la semaine","ipa":"/la sə.mɛn/","pos":"📅","tr":"hafta","ex":"Il y a sept jours dans la semaine.","exTr":"Haftada yedi gün var."}],"chunks":[{"en":"C'est quel jour ?","tr":"Hangi gün?"},{"en":"Aujourd'hui, c'est lundi.","tr":"Bugün pazartesi."},{"en":"Demain, c'est mardi.","tr":"Yarın salı."},{"en":"J'aime le week-end !","tr":"Hafta sonunu seviyorum!"}],"grammar":{"point":"C'est + jour","tr":"Hangi gün olduğunu söylerken 'C'est…' deriz: c'est lundi. Günü sormak için 'C'est quel jour ?' deriz. 'Aujourd'hui' bugün, 'demain' yarın demektir.","examples":["C'est lundi.","Aujourd'hui, c'est mardi.","Demain, c'est mercredi.","C'est quel jour aujourd'hui ?"]},"questions":[{"q":"Combien de jours y a-t-il dans la semaine ?","a":"Il y a sept jours."},{"q":"Quel jour Léa va-t-elle chez Mamie ?","a":"Le samedi."},{"q":"Que fait Léa le dimanche ?","a":"Elle joue avec Tom et Papa."}],"quiz":[{"q":"Après lundi, c'est…","o":["mardi","dimanche","jeudi"],"a":0,"why":""},{"q":"Il y a ___ jours dans la semaine.","o":["cinq","six","sept"],"a":2,"why":""},{"q":"Le week-end, c'est samedi et…","o":["vendredi","dimanche","mercredi"],"a":1,"why":""},{"q":"« C'est quel jour ? » veut dire…","o":["Hangi gün?","Saat kaç?","Hava nasıl?"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Aujourd'hui, c'est lundi.","cue":"mardi","answer":"Aujourd'hui, c'est mardi."},{"type":"Genişletme","prompt":"C'est samedi.","cue":"demain","answer":"Demain, c'est samedi."},{"type":"Soru yap","prompt":"C'est lundi.","cue":"Quel…?","answer":"C'est quel jour ?"}],"sounds":[{"focus":"/y/ ve /u/","tr":"Fransızca 'u' Türkçedeki ü gibidir: dudakları öne uzat, 'i' de. 'ou' ise Türkçedeki u gibidir. İki sesi karıştırma: 'rue' (ü) ile 'roue' (u) farklı kelimelerdir.","pairs":["rue / roue","tu / tout"]}],"mission":{"brief":"Oyun: Hafta planı! Claude, arkadaşın Léa olacak. Léa'ya hangi gün ne yaptığını Fransızca sor ve kendi hafta planını anlat.","persona":"Léa, a cheerful 7-year-old French girl. Very short simple French sentences. Hidden fact: her favourite day is Saturday because she goes to Mamie's, but she only says it if the child asks « Quel jour tu aimes ? ».","goal":"Léa'ya en az iki gün sor ve 'C'est…' ile bir günü söyle.","opener":"Salut ! Je suis Léa. Aujourd'hui, c'est lundi. Et chez toi, c'est quel jour ?"}},"FK1-015":{"objectives":["Evin odalarını Fransızca söylemek","'Il y a…' ile evde neler olduğunu anlatmak","'Où est… ?' sorusunu sormak ve yanıtlamak"],"dialogues":[{"title":"Voici ma maison","setting":"Léa, arkadaşı Elif'e evini gezdiriyor.","lines":[{"s":"Léa","en":"Voici ma maison, Elif !","tr":"İşte benim evim Elif!"},{"s":"Elif","en":"Elle est grande !","tr":"Çok büyük!"},{"s":"Léa","en":"Oui. Voici la porte.","tr":"Evet. İşte kapı."},{"s":"Elif","en":"Et là, c'est la cuisine ?","tr":"Peki orası mutfak mı?"},{"s":"Léa","en":"Oui, Maman est dans la cuisine.","tr":"Evet, annem mutfakta."},{"s":"Elif","en":"J'aime ta maison !","tr":"Evini seviyorum!"}]},{"title":"Où est Minou ?","setting":"Tom, kedisi Minou'yu evde arıyor.","lines":[{"s":"Tom","en":"Maman, où est Minou ?","tr":"Anne, Minou nerede?"},{"s":"Maman","en":"Il n'est pas dans la cuisine.","tr":"Mutfakta değil."},{"s":"Tom","en":"Il est dans le salon ?","tr":"Salonda mı?"},{"s":"Maman","en":"Regarde près de la fenêtre.","tr":"Pencerenin yanına bak."},{"s":"Tom","en":"Oui ! Le voilà !","tr":"Evet! İşte orada!"},{"s":"Maman","en":"Minou aime le soleil.","tr":"Minou güneşi sever."}]},{"title":"Dans le jardin","setting":"Papa, Léa'yı arıyor; Rex bahçede oynuyor.","lines":[{"s":"Papa","en":"Où es-tu, Léa ?","tr":"Neredesin Léa?"},{"s":"Léa","en":"Je suis dans la salle de bains.","tr":"Banyodayım."},{"s":"Papa","en":"Viens ! Rex est dans le jardin.","tr":"Gel! Rex bahçede."},{"s":"Léa","en":"J'arrive !","tr":"Geliyorum!"},{"s":"Papa","en":"Il joue avec ton ballon.","tr":"Topunla oynuyor."},{"s":"Léa","en":"Rex, c'est mon ballon !","tr":"Rex, bu benim topum!"}]}],"reading":{"title":"Ma maison","paras":[{"en":"Voici ma maison. Elle est grande et jolie. Il y a une cuisine, un salon, une chambre et une salle de bains. Il y a aussi un jardin. Dans le jardin, il y a Rex. Il y a une porte rouge et une fenêtre bleue. J'aime ma maison. Et toi, tu aimes ta maison ?","tr":"İşte benim evim. Büyük ve güzel. Bir mutfak, bir salon, bir oda ve bir banyo var. Bir de bahçe var. Bahçede Rex var. Kırmızı bir kapı ve mavi bir pencere var. Evimi seviyorum. Peki sen evini seviyor musun?"}]},"vocab":[{"w":"la maison","ipa":"/la mɛ.zɔ̃/","pos":"🏠","tr":"ev","ex":"Voici ma maison.","exTr":"İşte benim evim."},{"w":"la cuisine","ipa":"/la kɥi.zin/","pos":"🍳","tr":"mutfak","ex":"Maman est dans la cuisine.","exTr":"Annem mutfakta."},{"w":"le salon","ipa":"/lə sa.lɔ̃/","pos":"🛋️","tr":"salon","ex":"Il est dans le salon ?","exTr":"Salonda mı?"},{"w":"la chambre","ipa":"/la ʃɑ̃bʁ/","pos":"🛏️","tr":"yatak odası","ex":"Il y a une chambre.","exTr":"Bir yatak odası var."},{"w":"la salle de bains","ipa":"/la sal də bɛ̃/","pos":"🛁","tr":"banyo","ex":"Je suis dans la salle de bains.","exTr":"Banyodayım."},{"w":"le jardin","ipa":"/lə ʒaʁ.dɛ̃/","pos":"🌳","tr":"bahçe","ex":"Rex est dans le jardin.","exTr":"Rex bahçede."},{"w":"la porte","ipa":"/la pɔʁt/","pos":"🚪","tr":"kapı","ex":"Voici la porte.","exTr":"İşte kapı."},{"w":"la fenêtre","ipa":"/la fə.nɛtʁ/","pos":"🪟","tr":"pencere","ex":"Regarde près de la fenêtre.","exTr":"Pencerenin yanına bak."}],"chunks":[{"en":"Voici ma maison.","tr":"İşte benim evim."},{"en":"Il y a un jardin.","tr":"Bir bahçe var."},{"en":"Où est Minou ?","tr":"Minou nerede?"},{"en":"Le voilà !","tr":"İşte orada!"}],"grammar":{"point":"Il y a… / Où est… ?","tr":"'Il y a…' bir şeyin var olduğunu söyler: il y a une cuisine. 'Où est… ?' bir şeyin nerede olduğunu sorar. Cevap için 'Il est dans…' (o … içinde) deriz.","examples":["Il y a un jardin.","Il y a une porte.","Où est Minou ?","Il est dans le salon."]},"questions":[{"q":"Où est Maman ?","a":"Elle est dans la cuisine."},{"q":"Où est Minou ?","a":"Il est près de la fenêtre."},{"q":"Qui est dans le jardin ?","a":"Rex."}],"quiz":[{"q":"🍳 = ?","o":["la cuisine","le salon","la porte"],"a":0,"why":""},{"q":"Rex est dans…","o":["la chambre","le jardin","la cuisine"],"a":1,"why":""},{"q":"« Où est Minou ? » veut dire…","o":["Minou kim?","Minou ne yapıyor?","Minou nerede?"],"a":2,"why":""},{"q":"Léa est dans…","o":["la salle de bains","le salon","le jardin"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Maman est dans la cuisine.","cue":"le salon","answer":"Maman est dans le salon."},{"type":"Genişletme","prompt":"Il y a un jardin.","cue":"grand","answer":"Il y a un grand jardin."},{"type":"Soru yap","prompt":"Minou est dans le salon.","cue":"Où…?","answer":"Où est Minou ?"}],"sounds":[{"focus":"/ɔ̃/","tr":"'on' sesi burun ünlüsüdür. Ağzını 'o' gibi yuvarla ve sesi burnundan da çıkar; sondaki 'n'yi söyleme. 'maison' 'mezon' değil, 'mezõ' gibi biter.","pairs":["bon / banc","son / sans"]}],"mission":{"brief":"Oyun: Ev turu! Claude, arkadaşın Elif olacak. Elif'e evinin odalarını Fransızca anlat ve onun evinde neler olduğunu sor.","persona":"Elif, a cheerful 7-year-old Turkish girl living in France who speaks simple French. Hidden fact: she has a tortoise called Pamuk in her garden, but she only says so if the child asks « Il y a un animal dans ton jardin ? ».","goal":"Evinde en az üç yeri 'Il y a…' veya 'Voici…' ile anlat.","opener":"Salut ! Je suis Elif. Voici ma maison. Et toi, tu as une grande maison ?"}},"FK1-016":{"objectives":["Oda eşyalarını Fransızca söylemek","Eşyanın nerede olduğunu 'sur, sous, dans' ile anlatmak","Kendi odasını kısaca tarif etmek"],"dialogues":[{"title":"Voici ma chambre","setting":"Léa, büyükannesine odasını gösteriyor.","lines":[{"s":"Léa","en":"Mamie, voici ma chambre !","tr":"Büyükanne, işte benim odam!"},{"s":"Mamie","en":"Elle est jolie, ta chambre !","tr":"Odan çok güzel!"},{"s":"Léa","en":"Voici mon lit. Il est rose.","tr":"İşte yatağım. Pembe."},{"s":"Mamie","en":"Et qu'est-ce que c'est ?","tr":"Peki bu ne?"},{"s":"Léa","en":"C'est ma peluche. Elle s'appelle Choco.","tr":"Bu benim peluş oyuncağım. Adı Choco."},{"s":"Mamie","en":"Elle est mignonne.","tr":"Çok sevimli."}]},{"title":"Où est mon livre ?","setting":"Tom kitabını arıyor, Léa ona yardım ediyor.","lines":[{"s":"Tom","en":"Léa, où est mon livre ?","tr":"Léa, kitabım nerede?"},{"s":"Léa","en":"Il est sur le bureau.","tr":"Çalışma masasının üstünde."},{"s":"Tom","en":"Non, il n'est pas sur le bureau.","tr":"Hayır, masanın üstünde değil."},{"s":"Léa","en":"Regarde sur la chaise !","tr":"Sandalyenin üstüne bak!"},{"s":"Tom","en":"Le voilà ! Merci !","tr":"İşte burada! Teşekkürler!"},{"s":"Léa","en":"De rien, Tom.","tr":"Rica ederim Tom."}]},{"title":"On range","setting":"Maman, Léa'dan odasını toplamasını istiyor.","lines":[{"s":"Maman","en":"Léa, ta chambre est en désordre !","tr":"Léa, odan dağınık!"},{"s":"Léa","en":"Oui, Maman. La poupée est sous le lit.","tr":"Evet anne. Bebek yatağın altında."},{"s":"Maman","en":"Et la lampe ?","tr":"Peki lamba?"},{"s":"Léa","en":"Elle est sur le bureau.","tr":"Çalışma masasının üstünde."},{"s":"Maman","en":"Range la poupée dans l'armoire.","tr":"Bebeği dolaba kaldır."},{"s":"Léa","en":"D'accord, Maman !","tr":"Tamam anne!"}]}],"reading":{"title":"Ma chambre","paras":[{"en":"Voici ma chambre. Il y a un lit et une armoire. Sur le bureau, il y a une lampe et un livre. Ma peluche est sur le lit. Ma poupée est sur la chaise. Tom entre dans ma chambre. Il dit : « Elle est jolie ! » J'aime beaucoup ma chambre. C'est ma maison dans la maison !","tr":"İşte benim odam. Bir yatak ve bir dolap var. Çalışma masasının üstünde bir lamba ve bir kitap var. Peluş oyuncağım yatağın üstünde. Bebeğim sandalyenin üstünde. Tom odama giriyor. Diyor ki: 'Çok güzel!' Odamı çok seviyorum. Evin içinde benim küçük evim!"}]},"vocab":[{"w":"le lit","ipa":"/lə li/","pos":"🛏️","tr":"yatak","ex":"Voici mon lit.","exTr":"İşte yatağım."},{"w":"la lampe","ipa":"/la lɑ̃p/","pos":"💡","tr":"lamba","ex":"La lampe est sur le bureau.","exTr":"Lamba çalışma masasının üstünde."},{"w":"le bureau","ipa":"/lə by.ʁo/","pos":"🖥️","tr":"çalışma masası","ex":"Le livre est sur le bureau.","exTr":"Kitap çalışma masasının üstünde."},{"w":"l'armoire","ipa":"/laʁ.mwaʁ/","pos":"🚪","tr":"dolap","ex":"La poupée est dans l'armoire.","exTr":"Bebek dolabın içinde."},{"w":"la peluche","ipa":"/la pə.lyʃ/","pos":"🧸","tr":"peluş oyuncak","ex":"Ma peluche est sur le lit.","exTr":"Peluş oyuncağım yatağın üstünde."},{"w":"le livre","ipa":"/lə livʁ/","pos":"📖","tr":"kitap","ex":"Où est mon livre ?","exTr":"Kitabım nerede?"},{"w":"la chaise","ipa":"/la ʃɛz/","pos":"🪑","tr":"sandalye","ex":"Regarde sur la chaise !","exTr":"Sandalyenin üstüne bak!"},{"w":"la poupée","ipa":"/la pu.pe/","pos":"🪆","tr":"oyuncak bebek","ex":"La poupée est sous le lit.","exTr":"Bebek yatağın altında."}],"chunks":[{"en":"Voici ma chambre.","tr":"İşte benim odam."},{"en":"Où est mon livre ?","tr":"Kitabım nerede?"},{"en":"Il est sur le bureau.","tr":"Çalışma masasının üstünde."},{"en":"Le voilà !","tr":"İşte orada!"}],"grammar":{"point":"sur, sous, dans","tr":"Bir şeyin yerini söylerken 'sur' (üstünde), 'sous' (altında) ve 'dans' (içinde) kullanırız. 'Il est sur le bureau' = Çalışma masasının üstünde. Dikkat: 'le' erkek, 'la' dişi kelimelerle kullanılır.","examples":["Le livre est sur le bureau.","La poupée est sous le lit.","La peluche est sur le lit.","La poupée est dans l'armoire."]},"questions":[{"q":"Où est le livre de Tom ?","a":"Il est sur la chaise."},{"q":"Où est la poupée au début ?","a":"Elle est sous le lit."},{"q":"Comment s'appelle la peluche de Léa ?","a":"Elle s'appelle Choco."}],"quiz":[{"q":"🧸 = ?","o":["la lampe","la peluche","la chaise"],"a":1,"why":""},{"q":"La lampe est ___ le bureau.","o":["sur","sous","dans"],"a":0,"why":""},{"q":"La poupée est ___ le lit.","o":["sur","dans","sous"],"a":2,"why":"Dialogue: 'La poupée est sous le lit.'"},{"q":"« Sur » veut dire…","o":["altında","içinde","üstünde"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Le livre est sur le bureau.","cue":"la chaise","answer":"Le livre est sur la chaise."},{"type":"Yerine koyma","prompt":"La poupée est sous le lit.","cue":"dans l'armoire","answer":"La poupée est dans l'armoire."},{"type":"Soru yap","prompt":"La lampe est sur le bureau.","cue":"Où…?","answer":"Où est la lampe ?"}],"sounds":[{"focus":"lettres finales muettes","tr":"Fransızcada kelimenin sonundaki harfler çoğu zaman okunmaz. 'lit' kelimesinde t okunmaz: 'li'. Ama dişil 'petite' kelimesinde e olduğu için t okunur.","pairs":["lit / lire","petit / petite"]}],"mission":{"brief":"Oyun: Oda turu! Claude, arkadaşın Hugo olacak. Hugo'ya odasında neler olduğunu ve eşyaların nerede olduğunu Fransızca sor.","persona":"Hugo, a cheerful 7-year-old French boy. Short simple French sentences. Hidden fact: Hugo hides a toy dinosaur under his bed, but only says so if the child asks « Qu'est-ce qu'il y a sous ton lit ? ».","goal":"Hugo'ya en az iki eşyanın yerini sor ve 'sur / sous / dans' kullan.","opener":"Salut ! Je suis Hugo. Voici ma chambre. Il y a un lit. Et toi, qu'est-ce qu'il y a dans ta chambre ?"}},"FK1-017":{"objectives":["Parktaki oyun alanı ve nesneleri Fransızca söylemek","'Je joue au…' ve 'Je vais au…' kalıplarını kullanmak","Arkadaşını oyuna davet etmek"],"dialogues":[{"title":"Au parc","setting":"Léa ve Tom parka geliyor ve Hugo'yu görüyor.","lines":[{"s":"Tom","en":"Léa, regarde le parc !","tr":"Léa, bak park!"},{"s":"Léa","en":"Oh, il est grand !","tr":"Oh, çok büyük!"},{"s":"Tom","en":"Je vais sur le toboggan !","tr":"Ben kaydıraktan kayacağım!"},{"s":"Léa","en":"Moi, je vais sur la balançoire.","tr":"Ben de salıncağa gidiyorum."},{"s":"Tom","en":"Hugo est là aussi !","tr":"Hugo da orada!"},{"s":"Léa","en":"Salut, Hugo !","tr":"Merhaba Hugo!"}]},{"title":"Le ballon","setting":"Hugo ve Léa top oynuyor.","lines":[{"s":"Hugo","en":"Tu veux jouer au ballon ?","tr":"Top oynamak ister misin?"},{"s":"Léa","en":"Oui, avec plaisir !","tr":"Evet, memnuniyetle!"},{"s":"Hugo","en":"Attention, le ballon !","tr":"Dikkat, top!"},{"s":"Léa","en":"Oh là là ! Il est sous le banc.","tr":"Aman! Bankın altında."},{"s":"Hugo","en":"Je le prends.","tr":"Ben alıyorum."},{"s":"Léa","en":"Merci, Hugo !","tr":"Teşekkürler Hugo!"}]},{"title":"Les animaux","setting":"Papa ve Tom parkta bir köpek ve bir kuş görüyor.","lines":[{"s":"Papa","en":"Regarde, Tom ! Un chien !","tr":"Bak Tom! Bir köpek!"},{"s":"Tom","en":"C'est Rex ?","tr":"Rex mi?"},{"s":"Papa","en":"Non, ce n'est pas Rex. Rex est à la maison.","tr":"Hayır, Rex değil. Rex evde."},{"s":"Tom","en":"Et là, un oiseau !","tr":"Peki orada, bir kuş!"},{"s":"Papa","en":"Oui, il est petit et jaune.","tr":"Evet, küçük ve sarı."},{"s":"Tom","en":"Papa, je fais du vélo ?","tr":"Baba, bisiklete bineyim mi?"},{"s":"Papa","en":"Oui, mais doucement !","tr":"Evet, ama yavaş!"}]}],"reading":{"title":"Une journée au parc","paras":[{"en":"Aujourd'hui, nous allons au parc. Il y a un grand toboggan et une balançoire. Tom joue avec son vélo. Moi, je joue au ballon avec Hugo. Papa est sur un banc. Un chien et un oiseau sont là aussi. Nous sommes très contents ! J'aime le parc.","tr":"Bugün parka gidiyoruz. Büyük bir kaydırak ve bir salıncak var. Tom bisikletiyle oynuyor. Ben Hugo'yla top oynuyorum. Babam bir bankta oturuyor. Bir köpek ve bir kuş da orada. Çok mutluyuz! Parkı seviyorum."}]},"vocab":[{"w":"le parc","ipa":"/lə paʁk/","pos":"🌳","tr":"park","ex":"Le parc est grand.","exTr":"Park büyük."},{"w":"le toboggan","ipa":"/lə tɔ.bɔ.ɡɑ̃/","pos":"🛝","tr":"kaydırak","ex":"Je vais sur le toboggan !","exTr":"Kaydıraktan kayacağım!"},{"w":"la balançoire","ipa":"/la ba.lɑ̃.swaʁ/","pos":"🎠","tr":"salıncak","ex":"Je vais sur la balançoire.","exTr":"Salıncağa gidiyorum."},{"w":"le ballon","ipa":"/lə ba.lɔ̃/","pos":"⚽","tr":"top","ex":"Je joue au ballon.","exTr":"Top oynuyorum."},{"w":"le vélo","ipa":"/lə ve.lo/","pos":"🚲","tr":"bisiklet","ex":"Tom joue avec son vélo.","exTr":"Tom bisikletiyle oynuyor."},{"w":"le banc","ipa":"/lə bɑ̃/","pos":"🪑","tr":"bank","ex":"Le ballon est sous le banc.","exTr":"Top bankın altında."},{"w":"le chien","ipa":"/lə ʃjɛ̃/","pos":"🐕","tr":"köpek","ex":"Regarde, un chien !","exTr":"Bak, bir köpek!"},{"w":"l'oiseau","ipa":"/lwa.zo/","pos":"🐦","tr":"kuş","ex":"Là, un oiseau !","exTr":"Orada bir kuş!"}],"chunks":[{"en":"Tu veux jouer ?","tr":"Oynamak ister misin?"},{"en":"Je joue au ballon.","tr":"Top oynuyorum."},{"en":"Avec plaisir !","tr":"Memnuniyetle!"},{"en":"Attention !","tr":"Dikkat!"}],"grammar":{"point":"au / à la","tr":"'Jouer' (oynamak) fiilinden sonra 'à' kullanırız. Erkek kelimeyle 'au' olur: je joue au ballon. Dişil kelimeyle 'à la' olur: je vais à la balançoire. Parka giderken de 'je vais au parc' deriz.","examples":["Je joue au ballon.","Je vais au parc.","Je vais à la balançoire.","Tu joues au ballon ?"]},"questions":[{"q":"Avec qui Léa joue-t-elle au ballon ?","a":"Avec Hugo."},{"q":"Où est le ballon ?","a":"Il est sous le banc."},{"q":"De quelle couleur est l'oiseau ?","a":"Il est jaune."}],"quiz":[{"q":"🛝 = ?","o":["le banc","le toboggan","le vélo"],"a":1,"why":""},{"q":"Je joue ___ ballon.","o":["à la","au","dans"],"a":1,"why":""},{"q":"Le ballon est…","o":["sur le banc","dans le parc","sous le banc"],"a":2,"why":""},{"q":"Tom joue avec son…","o":["vélo","chien","oiseau"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Je joue au ballon.","cue":"parc","answer":"Je joue au parc."},{"type":"Dönüştürme","prompt":"Je vais au parc.","cue":"la balançoire","answer":"Je vais à la balançoire."},{"type":"Soru yap","prompt":"Tu joues au ballon.","cue":"?","answer":"Tu joues au ballon ?"}],"sounds":[{"focus":"/ɑ̃/ ve /ɛ̃/","tr":"Fransızcada burun ünlüleri vardır. 'banc' kelimesinde ağzını açık tut, 'an' sesini burnundan çıkar ve n'yi söyleme. 'chien' sonundaki 'ien' de burundan çıkar, 'şiyen' değil.","pairs":["banc / bain","grand / grain"]}],"mission":{"brief":"Oyun: Parkta buluşma! Claude, arkadaşın Hugo olacak. Hugo'yu oyuna davet et ve parkta ne gördüğünü Fransızca söyle.","persona":"Hugo, a cheerful 7-year-old French boy at the park. Short simple French sentences. Hidden fact: Hugo's bike is blue and has a bell, but he only says so if the child asks « Il est comment, ton vélo ? ».","goal":"Hugo'yu 'Tu veux jouer ?' ile oyuna davet et ve parkta iki şeyi söyle.","opener":"Salut ! Je suis au parc. Je joue au ballon. Tu veux jouer ?"}},"FK1-018":{"objectives":["Duygularını Fransızca söylemek: content, triste…","'Je suis…' ve 'J'ai peur' kalıplarını kullanmak","Birine 'Ça va ?' diye sormak ve cevap vermek"],"dialogues":[{"title":"Un câlin","setting":"Tom üzgün; Maman ona sarılıyor.","lines":[{"s":"Maman","en":"Tom, tu es triste ?","tr":"Tom, üzgün müsün?"},{"s":"Tom","en":"Oui, Maman.","tr":"Evet anne."},{"s":"Maman","en":"Pourquoi ?","tr":"Neden?"},{"s":"Tom","en":"Léa est en colère.","tr":"Léa kızgın."},{"s":"Maman","en":"Viens, un câlin !","tr":"Gel, bir sarılma!"},{"s":"Tom","en":"Merci ! Je suis content.","tr":"Teşekkürler! Mutluyum."}]},{"title":"À l'école","setting":"Léa, okulda arkadaşı Elif'in iyi olmadığını fark ediyor.","lines":[{"s":"Léa","en":"Ça va, Elif ?","tr":"İyi misin Elif?"},{"s":"Elif","en":"Non. Je suis fatiguée.","tr":"Hayır. Yorgunum."},{"s":"Léa","en":"Pourquoi ?","tr":"Neden?"},{"s":"Elif","en":"La nuit, j'ai peur.","tr":"Geceleri korkuyorum."},{"s":"Léa","en":"Oh ! Moi aussi, j'ai un peu peur !","tr":"Oh! Ben de biraz korkuyorum!"},{"s":"Elif","en":"Merci, Léa. Tu es gentille.","tr":"Teşekkürler Léa. Çok naziksin."}]},{"title":"Mamie arrive","setting":"Léa hasta; babası ona iyi bir haber veriyor.","lines":[{"s":"Papa","en":"Tu es malade, Léa ?","tr":"Hasta mısın Léa?"},{"s":"Léa","en":"Oui, Papa. Je suis fatiguée.","tr":"Evet baba. Yorgunum."},{"s":"Papa","en":"Repose-toi, ma puce.","tr":"Dinlen, tatlım."},{"s":"Léa","en":"Mamie arrive ?","tr":"Büyükanne geliyor mu?"},{"s":"Papa","en":"Oui ! Elle arrive ce soir.","tr":"Evet! Bu akşam geliyor."},{"s":"Léa","en":"Quelle joie ! Je suis contente !","tr":"Ne büyük mutluluk! Çok mutluyum!"}]}],"reading":{"title":"Mes émotions","paras":[{"en":"Aujourd'hui, j'ai beaucoup d'émotions. Le matin, je suis contente : c'est samedi ! Mais Tom est triste et je suis un peu en colère. Alors, Maman nous fait un câlin. Le soir, je suis fatiguée. Minou est content aussi. Il dort sur mon lit. Et toi, comment tu es ?","tr":"Bugün çok duygum var. Sabah mutluyum: bugün cumartesi! Ama Tom üzgün ve ben biraz kızgınım. Sonra annem bize sarılıyor. Akşam yorgunum. Minou da mutlu. Yatağımda uyuyor. Peki sen nasılsın?"}]},"vocab":[{"w":"content(e)","ipa":"/kɔ̃.tɑ̃(t)/","pos":"😊","tr":"mutlu, memnun","ex":"Je suis contente !","exTr":"Mutluyum!"},{"w":"triste","ipa":"/tʁist/","pos":"😢","tr":"üzgün","ex":"Tom est triste.","exTr":"Tom üzgün."},{"w":"en colère","ipa":"/ɑ̃ kɔ.lɛʁ/","pos":"😠","tr":"kızgın","ex":"Je suis un peu en colère.","exTr":"Biraz kızgınım."},{"w":"fatigué(e)","ipa":"/fa.ti.ɡe/","pos":"😴","tr":"yorgun","ex":"Le soir, je suis fatiguée.","exTr":"Akşam yorgunum."},{"w":"malade","ipa":"/ma.lad/","pos":"🤒","tr":"hasta","ex":"Tu es malade ?","exTr":"Hasta mısın?"},{"w":"la peur","ipa":"/la pœʁ/","pos":"😨","tr":"korku","ex":"J'ai peur.","exTr":"Korkuyorum."},{"w":"le câlin","ipa":"/lə ka.lɛ̃/","pos":"🤗","tr":"sarılma","ex":"Viens, un câlin !","exTr":"Gel, bir sarılma!"},{"w":"la joie","ipa":"/la ʒwa/","pos":"🥳","tr":"sevinç","ex":"Quelle joie !","exTr":"Ne büyük sevinç!"}],"chunks":[{"en":"Ça va ?","tr":"İyi misin?"},{"en":"Je suis content.","tr":"Mutluyum."},{"en":"J'ai peur.","tr":"Korkuyorum."},{"en":"Un câlin, s'il te plaît.","tr":"Bir sarılma lütfen."}],"grammar":{"point":"Je suis… / J'ai…","tr":"Nasıl hissettiğini söylerken 'Je suis…' deriz: je suis triste. Kız çocuk 'contente, fatiguée' der, erkek çocuk 'content, fatigué' der. Korkmak için 'j'ai peur' deriz.","examples":["Je suis content.","Tu es triste ?","Elle est fatiguée.","Il est en colère."]},"questions":[{"q":"Pourquoi Tom est-il triste ?","a":"Parce que Léa est en colère."},{"q":"Pourquoi Elif est-elle fatiguée ?","a":"Parce que la nuit, elle a peur."},{"q":"Qui arrive ce soir ?","a":"Mamie."}],"quiz":[{"q":"😢 = ?","o":["content","triste","malade"],"a":1,"why":""},{"q":"Quand je dors mal, je suis…","o":["fatigué","en colère","content"],"a":0,"why":"Uykusuz kalınca yorgun oluruz."},{"q":"« Quelle joie ! » veut dire…","o":["Ne korku!","Ne büyük sevinç!","Ne yorgunluk!"],"a":1,"why":""},{"q":"Léa est contente parce que…","o":["Mamie arrive","Rex est malade","Tom pleure"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Je suis content.","cue":"triste","answer":"Je suis triste."},{"type":"Dönüştürme","prompt":"Tom est fatigué.","cue":"Léa","answer":"Léa est fatiguée."},{"type":"Soru yap","prompt":"Tu es malade.","cue":"?","answer":"Tu es malade ?"}],"sounds":[{"focus":"/ʁ/","tr":"Fransızca r boğazın arkasından çıkar, Türkçe r gibi dilin ucuyla değil. Gargara yapar gibi hafifçe titret: 'rire', 'triste', 'peur'.","pairs":["rire / lire","rue / lue"]}],"mission":{"brief":"Oyun: Nasılsın? Claude, arkadaşın Elif olacak. Elif'e nasıl olduğunu Fransızca sor ve kendi duygunu 'Je suis…' ile söyle.","persona":"Elif, a kind 7-year-old Turkish girl in France who speaks simple French. Hidden fact: she is sad today because her cat Pamuk is lost, but she only says so if the child asks « Pourquoi tu es triste ? ».","goal":"Elif'e 'Ça va ?' diye sor ve en az iki duygu söyle.","opener":"Salut ! Je suis Elif. Ça va ? Moi, je suis un peu fatiguée."}},"FK1-019":{"objectives":["Fransızca 'Je sais + fiil' ile neler yapabildiğini söylemek","'Tu sais nager ?' diye sormak ve cevap vermek","'Je ne sais pas' diyerek bir şeyi yapamadığını söylemek"],"dialogues":[{"title":"Dans la cour","setting":"Teneffüste Léa ve Hugo okul bahçesinde oynuyor.","lines":[{"s":"Hugo","en":"Regarde, Léa ! Je sais sauter !","tr":"Bak Léa! Zıplayabiliyorum!"},{"s":"Léa","en":"Bravo, Hugo ! Moi aussi, je sais sauter.","tr":"Aferin Hugo! Ben de zıplayabiliyorum."},{"s":"Hugo","en":"Tu sais courir ?","tr":"Koşabiliyor musun?"},{"s":"Léa","en":"Oui, je sais courir très vite !","tr":"Evet, çok hızlı koşabiliyorum!"},{"s":"Hugo","en":"Moi, je ne sais pas grimper.","tr":"Ben tırmanamıyorum."},{"s":"Léa","en":"Ce n'est pas grave. Je t'aide !","tr":"Önemli değil. Sana yardım ederim!"}]},{"title":"À la piscine","setting":"Papa, Léa ve Tom havuzda; Tom yüzmeyi öğreniyor.","lines":[{"s":"Papa","en":"Tom, tu sais nager ?","tr":"Tom, yüzebiliyor musun?"},{"s":"Tom","en":"Non, je ne sais pas nager.","tr":"Hayır, yüzemiyorum."},{"s":"Léa","en":"Moi, je sais nager, Tom !","tr":"Ben yüzebiliyorum Tom!"},{"s":"Papa","en":"Léa est une championne !","tr":"Léa bir şampiyon!"},{"s":"Tom","en":"Je veux nager aussi !","tr":"Ben de yüzmek istiyorum!"},{"s":"Papa","en":"Viens, Tom. Je t'aide.","tr":"Gel Tom. Sana yardım ederim."},{"s":"Tom","en":"Super ! Je nage !","tr":"Harika! Yüzüyorum!"}]},{"title":"Le spectacle","setting":"Sınıfta Madame Martin, Elif ve Léa gösteri hazırlıyor.","lines":[{"s":"Madame Martin","en":"Elif, tu sais chanter ?","tr":"Elif, şarkı söyleyebiliyor musun?"},{"s":"Elif","en":"Oui, je sais chanter !","tr":"Evet, şarkı söyleyebiliyorum!"},{"s":"Madame Martin","en":"Et toi, Léa, tu sais danser ?","tr":"Peki sen Léa, dans edebiliyor musun?"},{"s":"Léa","en":"Oui, je sais danser. Je sais aussi dessiner.","tr":"Evet, dans edebiliyorum. Resim de yapabiliyorum."},{"s":"Madame Martin","en":"Super ! Elif chante, Léa danse.","tr":"Harika! Elif şarkı söyler, Léa dans eder."},{"s":"Elif","en":"Et je sais lire une histoire !","tr":"Bir de hikâye okuyabiliyorum!"}]}],"reading":{"title":"Léa sait tout faire","paras":[{"en":"Je m'appelle Léa. J'ai sept ans. Je sais sauter et je sais courir. Je sais nager dans la piscine. Je sais danser et chanter avec mes amis. Je sais aussi dessiner mon chat Minou. Mais je ne sais pas grimper aux arbres. Papa dit : « Ce n'est pas grave ! » Et toi, qu'est-ce que tu sais faire ?","tr":"Benim adım Léa. Yedi yaşındayım. Zıplayabilirim ve koşabilirim. Havuzda yüzebilirim. Arkadaşlarımla dans edip şarkı söyleyebilirim. Kedim Minou'nun resmini de yapabilirim. Ama ağaçlara tırmanamam. Babam: « Önemli değil! » der. Peki sen, neler yapabilirsin?"}]},"vocab":[{"w":"sauter","ipa":"/so.te/","pos":"🤸","tr":"zıplamak","ex":"Je sais sauter !","exTr":"Zıplayabiliyorum!"},{"w":"courir","ipa":"/ku.ʁiʁ/","pos":"🏃","tr":"koşmak","ex":"Je sais courir très vite.","exTr":"Çok hızlı koşabiliyorum."},{"w":"nager","ipa":"/na.ʒe/","pos":"🏊","tr":"yüzmek","ex":"Tu sais nager ?","exTr":"Yüzebiliyor musun?"},{"w":"danser","ipa":"/dɑ̃.se/","pos":"💃","tr":"dans etmek","ex":"Je sais danser.","exTr":"Dans edebiliyorum."},{"w":"chanter","ipa":"/ʃɑ̃.te/","pos":"🎤","tr":"şarkı söylemek","ex":"Elif sait chanter.","exTr":"Elif şarkı söyleyebiliyor."},{"w":"dessiner","ipa":"/de.si.ne/","pos":"🖍️","tr":"resim çizmek","ex":"Je sais dessiner mon chat.","exTr":"Kedimin resmini çizebiliyorum."},{"w":"grimper","ipa":"/gʁɛ̃.pe/","pos":"🧗","tr":"tırmanmak","ex":"Je ne sais pas grimper.","exTr":"Tırmanamıyorum."},{"w":"lire","ipa":"/liʁ/","pos":"📖","tr":"okumak","ex":"Je sais lire une histoire.","exTr":"Bir hikâye okuyabiliyorum."}],"chunks":[{"en":"Je sais nager !","tr":"Yüzebiliyorum!"},{"en":"Tu sais danser ?","tr":"Dans edebiliyor musun?"},{"en":"Je ne sais pas.","tr":"Bilmiyorum. / Yapamıyorum."},{"en":"Moi aussi !","tr":"Ben de!"}],"grammar":{"point":"Je sais + verbe","tr":"Bir şeyi yapabildiğimizi söylerken 'Je sais' ve fiilin yalın hâlini kullanırız: 'Je sais nager.' Yapamıyorsak 'Je ne sais pas' deriz. Sormak için 'Tu sais nager ?' diyoruz.","examples":["Je sais sauter.","Tu sais courir ?","Je ne sais pas grimper.","Elif sait chanter."]},"questions":[{"q":"Qui sait nager dans la piscine ?","a":"Léa sait nager."},{"q":"Qu'est-ce que Hugo ne sait pas faire ?","a":"Il ne sait pas grimper."},{"q":"Qui sait chanter ?","a":"Elif sait chanter."}],"quiz":[{"q":"🏊 Je sais ___.","o":["courir","nager","danser"],"a":1,"why":""},{"q":"« Tu sais danser ? » Réponse : « Oui, ___ »","o":["je sais danser","je ne sais pas","tu sais danser"],"a":0,"why":"Soruya 'Je sais…' ile cevap verilir."},{"q":"Tom ne sait pas ___.","o":["lire","chanter","nager"],"a":2,"why":""},{"q":"Hugo : « Je ne sais pas ___. »","o":["grimper","sauter","courir"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Je sais sauter.","cue":"nager","answer":"Je sais nager."},{"type":"Dönüştürme","prompt":"Je sais danser.","cue":"Je ne… pas","answer":"Je ne sais pas danser."},{"type":"Soru yap","prompt":"Tu sais courir.","cue":"Tu… ?","answer":"Tu sais courir ?"}],"sounds":[{"focus":"/ɑ̃/","tr":"Fransızca 'danser' ve 'chanter' içindeki 'an' sesi burundan çıkar. 'a' de ve 'n' sesini söyleme; havayı burnundan bırak. Türkçedeki 'an' gibi okumayın.","pairs":["danser / chanter","dans / chance"]}],"mission":{"brief":"Oyun: Yetenek gösterisi! Claude, arkadaşın Hugo olacak. Ona Fransızca olarak neler yapabildiğini söyle ve ona 'Tu sais … ?' diye sor.","persona":"Hugo, a cheerful 7-year-old French boy. Speaks in very short, simple French sentences and encourages the child. Asks one question at a time. Hidden fact: Hugo secretly knows how to play the piano (jouer du piano), but he only says it if the child asks 'Tu sais jouer du piano ?' or 'Qu'est-ce que tu sais faire d'autre ?'.","goal":"En az üç şeyi 'Je sais…' ile söyle ve Hugo'ya bir 'Tu sais … ?' sorusu sor.","opener":"Salut ! Je suis Hugo. Je sais sauter très haut ! Et toi, tu sais sauter ?"}},"FK1-020":{"objectives":["Temel şekilleri Fransızca söylemek","'Qu'est-ce que c'est ?' sorusunu sormak ve 'C'est un / une…' ile cevap vermek","Çevredeki nesnelerin şeklini söylemek"],"dialogues":[{"title":"Le cours de dessin","setting":"Resim dersinde Madame Martin çocuklara şekilleri gösteriyor.","lines":[{"s":"Madame Martin","en":"Léa, qu'est-ce que c'est ?","tr":"Léa, bu ne?"},{"s":"Léa","en":"C'est un cercle !","tr":"Bir daire!"},{"s":"Madame Martin","en":"Bravo ! Et ça, Hugo ?","tr":"Aferin! Peki bu, Hugo?"},{"s":"Hugo","en":"C'est un carré.","tr":"Bir kare."},{"s":"Madame Martin","en":"Oui ! Et là, c'est un triangle.","tr":"Evet! Şurada da bir üçgen var."},{"s":"Léa","en":"J'aime les formes !","tr":"Şekilleri seviyorum!"}]},{"title":"Ma maison","setting":"Tom, ablası Léa'ya çizdiği evi gösteriyor.","lines":[{"s":"Tom","en":"Regarde ma maison, Léa !","tr":"Bak evime Léa!"},{"s":"Léa","en":"Le toit, c'est un triangle.","tr":"Çatı bir üçgen."},{"s":"Tom","en":"Oui ! Et la fenêtre, c'est un carré.","tr":"Evet! Pencere de bir kare."},{"s":"Léa","en":"Et la porte ? C'est un rectangle !","tr":"Peki kapı? Bir dikdörtgen!"},{"s":"Tom","en":"Là, il y a le soleil. C'est un cercle.","tr":"Orada güneş var. O da bir daire."},{"s":"Léa","en":"Il est beau, ton dessin !","tr":"Çizimin çok güzel!"},{"s":"Tom","en":"Merci !","tr":"Teşekkürler!"}]},{"title":"Le jeu des formes","setting":"Elif ve Léa evde şekil oyunu oynuyor.","lines":[{"s":"Elif","en":"Je cherche une étoile jaune.","tr":"Sarı bir yıldız arıyorum."},{"s":"Léa","en":"La voilà ! C'est une étoile.","tr":"İşte burada! Bu bir yıldız."},{"s":"Elif","en":"Super ! Et un cœur rouge ?","tr":"Süper! Peki kırmızı bir kalp?"},{"s":"Léa","en":"Voilà le cœur. J'aime le cœur !","tr":"İşte kalp. Kalbi seviyorum!"},{"s":"Elif","en":"Et ça, c'est un losange ?","tr":"Peki bu bir eşkenar dörtgen mi?"},{"s":"Léa","en":"Oui, c'est un losange. Quelle belle forme !","tr":"Evet, bu bir eşkenar dörtgen. Ne güzel bir şekil!"}]}],"reading":{"title":"Les formes dans ma chambre","paras":[{"en":"Dans ma chambre, il y a beaucoup de formes. La fenêtre est un rectangle. Mon tapis est un carré. Mon ballon est un cercle. Sur le mur, il y a une étoile et un cœur. Le toit de ma maison de poupée est un triangle. Je dessine un losange rose. J'aime les formes !","tr":"Odamda çok şekil var. Pencere bir dikdörtgen. Halım bir kare. Topum bir daire. Duvarda bir yıldız ve bir kalp var. Oyuncak evimin çatısı bir üçgen. Pembe bir eşkenar dörtgen çiziyorum. Şekilleri seviyorum!"}]},"vocab":[{"w":"le cercle","ipa":"/lə sɛʁkl/","pos":"⭕","tr":"daire","ex":"Le soleil, c'est un cercle.","exTr":"Güneş bir daire."},{"w":"le carré","ipa":"/lə ka.ʁe/","pos":"🟦","tr":"kare","ex":"La fenêtre, c'est un carré.","exTr":"Pencere bir kare."},{"w":"le triangle","ipa":"/lə tʁi.ɑ̃gl/","pos":"🔺","tr":"üçgen","ex":"Le toit, c'est un triangle.","exTr":"Çatı bir üçgen."},{"w":"le rectangle","ipa":"/lə ʁɛk.tɑ̃gl/","pos":"🚪","tr":"dikdörtgen","ex":"La porte, c'est un rectangle.","exTr":"Kapı bir dikdörtgen."},{"w":"l'étoile","ipa":"/le.twal/","pos":"⭐","tr":"yıldız","ex":"C'est une étoile jaune.","exTr":"Bu sarı bir yıldız."},{"w":"le cœur","ipa":"/lə kœʁ/","pos":"❤️","tr":"kalp","ex":"J'aime le cœur rouge.","exTr":"Kırmızı kalbi seviyorum."},{"w":"le losange","ipa":"/lə lo.zɑ̃ʒ/","pos":"🔶","tr":"eşkenar dörtgen","ex":"C'est un losange rose.","exTr":"Bu pembe bir eşkenar dörtgen."},{"w":"la forme","ipa":"/la fɔʁm/","pos":"🔷","tr":"şekil","ex":"J'aime les formes !","exTr":"Şekilleri seviyorum!"}],"chunks":[{"en":"Qu'est-ce que c'est ?","tr":"Bu ne?"},{"en":"C'est un cercle.","tr":"Bu bir daire."},{"en":"C'est une étoile.","tr":"Bu bir yıldız."},{"en":"Il y a un triangle.","tr":"Bir üçgen var."}],"grammar":{"point":"C'est un / une…","tr":"Bir şeyin ne olduğunu söylerken 'C'est' deriz. Eril kelimelerin önüne 'un', dişil kelimelerin önüne 'une' koyarız: 'un cercle', 'une étoile'. Sormak için 'Qu'est-ce que c'est ?' deriz.","examples":["C'est un cercle.","C'est une étoile.","Qu'est-ce que c'est ?","La porte, c'est un rectangle."]},"questions":[{"q":"Qu'est-ce que c'est, le toit de la maison de Tom ?","a":"C'est un triangle."},{"q":"Quelle forme a la porte ?","a":"C'est un rectangle."},{"q":"Qu'est-ce que Elif cherche ?","a":"Elle cherche une étoile jaune."}],"quiz":[{"q":"⭐ C'est ___ étoile.","o":["un","une","le"],"a":1,"why":"Étoile dişil bir kelime olduğu için 'une' kullanılır."},{"q":"La fenêtre de Tom est ___.","o":["un triangle","un cercle","un carré"],"a":2,"why":""},{"q":"« ___ ? » « C'est un cœur. »","o":["Qu'est-ce que c'est","Tu as quel âge","Où est le chat"],"a":0,"why":""},{"q":"🔺 C'est un ___.","o":["triangle","cercle","rectangle"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"C'est un cercle.","cue":"carré","answer":"C'est un carré."},{"type":"Yerine koyma","prompt":"C'est un triangle.","cue":"étoile","answer":"C'est une étoile."},{"type":"Soru yap","prompt":"C'est un cœur.","cue":"Qu'est-ce que… ?","answer":"Qu'est-ce que c'est ?"}],"sounds":[{"focus":"/y/","tr":"Fransızca 'u' sesi Türkçedeki 'ü' gibidir. Dudaklarını 'u' der gibi öne yuvarla, ama dilini 'i' demek gibi öne ver: 'une', 'rue'. 'ou' harfleri ise Türkçedeki 'u'dur.","pairs":["une / ou","rue / roue","tu / tout"]}],"mission":{"brief":"Oyun: Şekil avı! Claude, arkadaşın Léa olacak. Etrafındaki nesnelerin şeklini Fransızca söyle ve Léa'ya 'Qu'est-ce que c'est ?' diye sor.","persona":"Léa, a cheerful 7-year-old French girl. Uses very short, simple French sentences and lots of encouragement. Asks one question at a time. Hidden fact: Léa's secret favourite shape is the star (l'étoile), but she only says it if the child asks 'Quelle est ta forme préférée ?' or 'Tu aimes quelle forme ?'.","goal":"En az üç şekli 'C'est un / une…' ile söyle.","opener":"Salut ! Je suis Léa. Regarde mon dessin. Qu'est-ce que c'est ?"}},"FK1-021":{"objectives":["'Joyeux anniversaire !' demek ve yaşını söylemek","Doğum günü eşyalarını Fransızca adlandırmak","'J'ai … ans' ve 'Voici un cadeau pour toi' cümlelerini kullanmak"],"dialogues":[{"title":"Le grand jour","setting":"Tom'un doğum günü sabahı; Maman ve Papa onu uyandırıyor.","lines":[{"s":"Maman","en":"Joyeux anniversaire, Tom !","tr":"Doğum günün kutlu olsun Tom!"},{"s":"Tom","en":"Merci, Maman !","tr":"Teşekkürler anne!"},{"s":"Papa","en":"Tu as six ans aujourd'hui !","tr":"Bugün altı yaşındasın!"},{"s":"Tom","en":"Oui, j'ai six ans ! Il y a une fête ?","tr":"Evet, altı yaşındayım! Parti var mı?"},{"s":"Maman","en":"Oui, avec un grand gâteau.","tr":"Evet, büyük bir pastayla."},{"s":"Tom","en":"Super ! J'aime le gâteau !","tr":"Süper! Pastayı severim!"}]},{"title":"Les cadeaux","setting":"Parti başladı; Hugo ve Elif Tom'a hediye getiriyor.","lines":[{"s":"Hugo","en":"Bonjour Tom ! Voici un cadeau pour toi.","tr":"Merhaba Tom! İşte senin için bir hediye."},{"s":"Tom","en":"Oh, merci ! C'est un ballon ?","tr":"Oh, teşekkürler! Bir balon mu?"},{"s":"Hugo","en":"Non, ouvre le cadeau !","tr":"Hayır, hediyeyi aç!"},{"s":"Tom","en":"C'est une voiture rouge ! Merci, Hugo !","tr":"Kırmızı bir araba! Teşekkürler Hugo!"},{"s":"Elif","en":"Et voici une carte de moi.","tr":"Bir de benden bir kart."},{"s":"Tom","en":"Elle est très jolie, Elif !","tr":"Çok güzel Elif!"},{"s":"Elif","en":"Joyeux anniversaire, Tom !","tr":"Doğum günün kutlu olsun Tom!"}]},{"title":"Le gâteau","setting":"Pasta zamanı! Herkes mumları üflemeye hazırlanıyor.","lines":[{"s":"Mamie","en":"Voici le gâteau !","tr":"İşte pasta!"},{"s":"Léa","en":"Il y a six bougies, Tom !","tr":"Altı mum var Tom!"},{"s":"Tom","en":"Un, deux, trois, quatre, cinq, six !","tr":"Bir, iki, üç, dört, beş, altı!"},{"s":"Mamie","en":"Souffle les bougies, mon chéri !","tr":"Mumları üfle canım!"},{"s":"Tom","en":"Hop ! C'est fini !","tr":"Hop! Bitti!"},{"s":"Léa","en":"Bravo ! Qui veut du jus ?","tr":"Aferin! Meyve suyu isteyen var mı?"}]}],"reading":{"title":"La fête de Tom","paras":[{"en":"Aujourd'hui, c'est l'anniversaire de Tom. Il a six ans. Il y a une fête dans le jardin. Il y a des ballons de toutes les couleurs. Maman prépare un gâteau avec six bougies. Les amis arrivent avec des cadeaux. Tom est très content. Il dit : « Merci à tous ! C'est une belle fête ! »","tr":"Bugün Tom'un doğum günü. Altı yaşında. Bahçede bir parti var. Her renkten balonlar var. Annem altı mumlu bir pasta hazırlıyor. Arkadaşlar hediyelerle geliyor. Tom çok mutlu. « Hepinize teşekkürler! Çok güzel bir parti! » diyor."}]},"vocab":[{"w":"l'anniversaire","ipa":"/la.ni.vɛʁ.sɛʁ/","pos":"🎂","tr":"doğum günü","ex":"Joyeux anniversaire, Tom !","exTr":"Doğum günün kutlu olsun Tom!"},{"w":"le gâteau","ipa":"/lə ɡa.to/","pos":"🍰","tr":"pasta","ex":"J'aime le gâteau !","exTr":"Pastayı severim!"},{"w":"la bougie","ipa":"/la bu.ʒi/","pos":"🕯️","tr":"mum","ex":"Il y a six bougies.","exTr":"Altı mum var."},{"w":"le cadeau","ipa":"/lə ka.do/","pos":"🎁","tr":"hediye","ex":"Voici un cadeau pour toi.","exTr":"İşte senin için bir hediye."},{"w":"le ballon","ipa":"/lə ba.lɔ̃/","pos":"🎈","tr":"balon","ex":"C'est un ballon ?","exTr":"Bir balon mu?"},{"w":"la fête","ipa":"/la fɛt/","pos":"🎉","tr":"parti, şenlik","ex":"Il y a une fête dans le jardin.","exTr":"Bahçede bir parti var."},{"w":"la carte","ipa":"/la kaʁt/","pos":"💌","tr":"kart","ex":"Voici une carte de moi.","exTr":"İşte benden bir kart."},{"w":"le jus","ipa":"/lə ʒy/","pos":"🧃","tr":"meyve suyu","ex":"Qui veut du jus ?","exTr":"Meyve suyu isteyen var mı?"}],"chunks":[{"en":"Joyeux anniversaire !","tr":"Doğum günün kutlu olsun!"},{"en":"J'ai six ans.","tr":"Altı yaşındayım."},{"en":"Voici un cadeau pour toi.","tr":"İşte senin için bir hediye."},{"en":"Merci beaucoup !","tr":"Çok teşekkürler!"}],"grammar":{"point":"J'ai… ans","tr":"Fransızcada yaşı söylerken 'olmak' değil 'sahip olmak' fiilini (avoir) kullanırız: 'J'ai sept ans.' Karşımızdakine 'Tu as six ans' deriz; bir kişiden bahsederken 'Il a six ans' deriz.","examples":["J'ai sept ans.","Tu as six ans.","Tom a six ans.","Tu as quel âge ?"]},"questions":[{"q":"Quel âge a Tom ?","a":"Il a six ans."},{"q":"Combien de bougies y a-t-il sur le gâteau ?","a":"Il y a six bougies."},{"q":"Qu'est-ce que Hugo offre à Tom ?","a":"Il offre une voiture rouge."}],"quiz":[{"q":"🎂 On dit : « ___ anniversaire ! »","o":["Bonne nuit","Joyeux","Bonjour"],"a":1,"why":""},{"q":"Tom ___ six ans.","o":["a","est","ai"],"a":0,"why":"Yaş söylerken 'avoir' kullanılır: il a."},{"q":"Hugo apporte ___.","o":["un cadeau","une bougie","un gâteau"],"a":0,"why":""},{"q":"🎈 C'est un ___.","o":["jus","ballon","gâteau"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"J'ai six ans.","cue":"sept","answer":"J'ai sept ans."},{"type":"Dönüştürme","prompt":"J'ai six ans.","cue":"Tom","answer":"Tom a six ans."},{"type":"Soru yap","prompt":"Tu as six ans.","cue":"Quel… ?","answer":"Tu as quel âge ?"}],"sounds":[{"focus":"/ɔ̃/","tr":"'ballon' kelimesindeki 'on' burun sesidir. Dudaklarını yuvarlak tut, 'o' de ve havayı burnundan bırak. Sonda 'n' sesi duyulmaz: 'ballon', 'bonbon'.","pairs":["ballon / bonbon","bon / beau"]}],"mission":{"brief":"Oyun: Doğum günü partisi! Claude, arkadaşın Hugo olacak. Ona 'Joyeux anniversaire !' de, kaç yaşında olduğunu sor ve ona bir hediye ver.","persona":"Hugo, a cheerful French boy whose birthday party it is today. Uses very short, simple French sentences and lots of excitement. Asks one question at a time. Hidden fact: Hugo is turning seven today and his secret wish is a red bicycle (un vélo rouge), but he only says it if the child asks 'Quel âge as-tu ?' and 'Qu'est-ce que tu veux comme cadeau ?'.","goal":"Hugo'ya doğum gününü kutla, yaşını sor ve bir hediye ver.","opener":"Salut ! C'est mon anniversaire aujourd'hui ! Il y a un gâteau et des ballons. Tu aimes les fêtes ?"}},"FK1-022":{"objectives":["Plajdaki temel şeyleri Fransızca adlandırmak","'Il y a…' ile gördüğü şeyleri söylemek","'Je veux…' ile plajda ne istediğini söylemek"],"dialogues":[{"title":"On arrive !","setting":"Léa ailesiyle plaja yeni varıyor.","lines":[{"s":"Léa","en":"Papa, regarde ! La plage !","tr":"Baba bak! Plaj!"},{"s":"Papa","en":"Oui ! Il y a du soleil aujourd'hui.","tr":"Evet! Bugün güneş var."},{"s":"Tom","en":"Et la mer ? Elle est grande !","tr":"Peki deniz? Çok büyük!"},{"s":"Léa","en":"Oui, et le sable est chaud.","tr":"Evet, kum da sıcak."},{"s":"Maman","en":"Voici le parasol et les serviettes.","tr":"İşte şemsiye ve havlular."},{"s":"Tom","en":"Super ! Je veux jouer !","tr":"Süper! Oynamak istiyorum!"}]},{"title":"Un château de sable","setting":"Léa ve Tom kumda oynuyor.","lines":[{"s":"Tom","en":"Léa, tu as un seau ?","tr":"Léa, kovan var mı?"},{"s":"Léa","en":"Oui, j'ai un seau bleu.","tr":"Evet, mavi bir kovam var."},{"s":"Tom","en":"Je fais un château de sable.","tr":"Bir kumdan kale yapıyorum."},{"s":"Léa","en":"Moi aussi. Il est grand !","tr":"Ben de. Çok büyük!"},{"s":"Tom","en":"Oh non, la mer arrive !","tr":"Aman, deniz geliyor!"},{"s":"Léa","en":"Ha ha ! Le château est dans l'eau !","tr":"Ha ha! Kale suyun içinde!"},{"s":"Tom","en":"On fait un autre château !","tr":"Başka bir kale yapalım!"}]},{"title":"Une glace","setting":"Mamie plajda çocuklara dondurma alıyor.","lines":[{"s":"Mamie","en":"Vous avez chaud ? Une glace ?","tr":"Sıcak mı bastı? Dondurma ister misiniz?"},{"s":"Léa","en":"Oui, s'il te plaît, Mamie !","tr":"Evet, lütfen Mamie!"},{"s":"Mamie","en":"Tu veux quel parfum ?","tr":"Hangi tadı istersin?"},{"s":"Léa","en":"Je veux une glace à la fraise.","tr":"Çilekli dondurma istiyorum."},{"s":"Tom","en":"Moi, je veux une glace au chocolat.","tr":"Ben çikolatalı dondurma istiyorum."},{"s":"Mamie","en":"Voilà ! Et on dit ?","tr":"Buyurun! Peki ne diyoruz?"},{"s":"Léa","en":"Merci, Mamie !","tr":"Teşekkürler Mamie!"}]}],"reading":{"title":"Une journée à la plage","paras":[{"en":"Aujourd'hui, nous sommes à la plage. Il y a du soleil et la mer est bleue. Le sable est chaud. Papa met le parasol et Maman étend les serviettes. Tom joue avec son seau. Moi, je mange une glace. Il y a beaucoup de monde sur la plage. C'est une belle journée !","tr":"Bugün plajdayız. Güneş var ve deniz mavi. Kum sıcak. Babam şemsiyeyi dikiyor, annem havluları seriyor. Tom kovasıyla oynuyor. Ben dondurma yiyorum. Plajda çok insan var. Ne güzel bir gün!"}]},"vocab":[{"w":"la plage","ipa":"/la plaʒ/","pos":"🏖️","tr":"plaj","ex":"Papa, regarde ! La plage !","exTr":"Baba bak! Plaj!"},{"w":"la mer","ipa":"/la mɛʁ/","pos":"🌊","tr":"deniz","ex":"La mer est bleue.","exTr":"Deniz mavi."},{"w":"le sable","ipa":"/lə sabl/","pos":"⏳","tr":"kum","ex":"Le sable est chaud.","exTr":"Kum sıcak."},{"w":"le soleil","ipa":"/lə sɔ.lɛj/","pos":"☀️","tr":"güneş","ex":"Il y a du soleil.","exTr":"Güneş var."},{"w":"le seau","ipa":"/lə so/","pos":"🪣","tr":"kova","ex":"J'ai un seau bleu.","exTr":"Mavi bir kovam var."},{"w":"la serviette","ipa":"/la sɛʁ.vjɛt/","pos":"🏝️","tr":"havlu","ex":"Voici les serviettes.","exTr":"İşte havlular."},{"w":"le parasol","ipa":"/lə pa.ʁa.sɔl/","pos":"⛱️","tr":"plaj şemsiyesi","ex":"Voici le parasol.","exTr":"İşte plaj şemsiyesi."},{"w":"la glace","ipa":"/la ɡlas/","pos":"🍦","tr":"dondurma","ex":"Je veux une glace.","exTr":"Dondurma istiyorum."}],"chunks":[{"en":"Il y a du soleil.","tr":"Güneş var."},{"en":"Je veux jouer !","tr":"Oynamak istiyorum!"},{"en":"Je veux une glace.","tr":"Dondurma istiyorum."},{"en":"S'il te plaît.","tr":"Lütfen."}],"grammar":{"point":"Il y a…","tr":"Bir yerde bir şey olduğunu söylerken 'Il y a' deriz; 'var' anlamına gelir. Eril kelimelerle 'un', dişil kelimelerle 'une' kullanırız: 'Il y a un seau', 'Il y a une glace'. Soru için 'Il y a… ?' diye yükselerek söyleriz.","examples":["Il y a du soleil.","Il y a un parasol.","Il y a une glace.","Il y a un seau ?"]},"questions":[{"q":"Comment est le sable ?","a":"Il est chaud."},{"q":"De quelle couleur est le seau de Léa ?","a":"Il est bleu."},{"q":"Quelle glace veut Tom ?","a":"Il veut une glace au chocolat."}],"quiz":[{"q":"🌊 C'est ___.","o":["le sable","la mer","le soleil"],"a":1,"why":""},{"q":"Il y a ___ soleil.","o":["une","un","du"],"a":2,"why":"Soleil gibi sayılamayan şeylerle 'du' kullanılır."},{"q":"Léa veut une glace à la ___.","o":["fraise","mer","plage"],"a":0,"why":""},{"q":"🪣 Tom a un ___.","o":["parasol","seau","sable"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Il y a un parasol.","cue":"seau","answer":"Il y a un seau."},{"type":"Yerine koyma","prompt":"Il y a un seau.","cue":"glace","answer":"Il y a une glace."},{"type":"Genişletme","prompt":"Je veux une glace.","cue":"s'il te plaît","answer":"Je veux une glace, s'il te plaît."}],"sounds":[{"focus":"/ʁ/","tr":"Fransızca 'r' Türkçedeki gibi dil ucuyla değil, boğazın arkasından çıkar. 'Gargara' yapar gibi hafifçe boğazını titret: 'mer', 'serviette', 'parasol'.","pairs":["mer / mes","rat / là","rue / lu"]}],"mission":{"brief":"Oyun: Plajda bir gün! Claude, arkadaşın Hugo olacak. Plajda gördüğün şeyleri 'Il y a…' ile söyle ve Hugo'ya ne istediğini sor.","persona":"Hugo, a cheerful 7-year-old French boy at the beach. Uses very short, simple French sentences and lots of encouragement. Asks one question at a time. Hidden fact: Hugo is afraid of crabs (les crabes), but he only says it if the child asks 'Tu as peur de quelque chose ?' or 'Tu aimes les crabes ?'.","goal":"'Il y a…' ile en az üç şey söyle ve 'Je veux…' ile bir şey iste.","opener":"Salut ! Je suis Hugo. Regarde la mer ! Il y a du soleil. Tu veux jouer avec moi ?"}},"FK1-023":{"objectives":["Deniz hayvanlarının adlarını Fransızca söylemek","'Il est grand' / 'Elle est grande' gibi cümlelerle hayvanları tarif etmek","'J'aime…' ile en sevdiği deniz hayvanını söylemek"],"dialogues":[{"title":"À l'aquarium","setting":"Léa ve Tom babalarıyla akvaryumu geziyor.","lines":[{"s":"Tom","en":"Papa, regarde ! Un poisson !","tr":"Baba bak! Bir balık!"},{"s":"Papa","en":"Oui, il est orange et il est petit.","tr":"Evet, turuncu ve küçük."},{"s":"Léa","en":"Et là, c'est un dauphin !","tr":"Şurada da bir yunus var!"},{"s":"Tom","en":"Il est gris. Il est beau !","tr":"Gri. Çok güzel!"},{"s":"Papa","en":"Regardez la baleine. Elle est énorme !","tr":"Balinaya bakın. Çok büyük!"},{"s":"Léa","en":"Oh là là ! Elle est très grande !","tr":"Vay vay! Çok büyük!"}]},{"title":"Le crabe et la tortue","setting":"Elif ve Léa kıyıdaki kayalıklarda hayvanları arıyor.","lines":[{"s":"Elif","en":"Léa, un crabe !","tr":"Léa, bir yengeç!"},{"s":"Léa","en":"Il est rouge et il est rigolo !","tr":"Kırmızı ve çok komik!"},{"s":"Elif","en":"Et dans l'eau, il y a une tortue.","tr":"Suyun içinde de bir kaplumbağa var."},{"s":"Léa","en":"Elle est verte. Elle est lente.","tr":"Yeşil. Yavaş."},{"s":"Elif","en":"J'aime la tortue.","tr":"Ben kaplumbağayı severim."},{"s":"Léa","en":"Moi, j'aime le crabe !","tr":"Ben yengeci severim!"},{"s":"Elif","en":"Et nous aimons la mer !","tr":"Biz de denizi severiz!"}]},{"title":"Le livre de Madame Martin","setting":"Sınıfta Madame Martin deniz hayvanları kitabını gösteriyor.","lines":[{"s":"Madame Martin","en":"Regardez cette page. Qui est-ce ?","tr":"Bu sayfaya bakın. Bu kim?"},{"s":"Hugo","en":"C'est un requin ! Il est grand !","tr":"Bir köpekbalığı! Çok büyük!"},{"s":"Madame Martin","en":"Oui. Et ici ?","tr":"Evet. Peki burada?"},{"s":"Léa","en":"C'est une pieuvre. Elle est violette.","tr":"Bir ahtapot. Mor."},{"s":"Madame Martin","en":"Très bien ! Elle a huit bras.","tr":"Çok güzel! Sekiz kolu var."},{"s":"Hugo","en":"Huit ! Elle est drôle !","tr":"Sekiz tane! Çok komik!"}]}],"reading":{"title":"Mon animal préféré","paras":[{"en":"J'aime les animaux de la mer. Le poisson est petit et rapide. Le requin est grand. La baleine est énorme. La tortue est lente, mais elle est gentille. Le crabe est rouge. Mon animal préféré, c'est le dauphin. Il est gris et très intelligent. Il joue dans l'eau avec ses amis.","tr":"Deniz hayvanlarını severim. Balık küçük ve hızlıdır. Köpekbalığı büyüktür. Balina çok iridir. Kaplumbağa yavaştır ama sevimlidir. Yengeç kırmızıdır. En sevdiğim hayvan yunus. Gri ve çok zekidir. Arkadaşlarıyla suda oynar."}]},"vocab":[{"w":"le poisson","ipa":"/lə pwa.sɔ̃/","pos":"🐟","tr":"balık","ex":"Le poisson est petit.","exTr":"Balık küçük."},{"w":"le dauphin","ipa":"/lə do.fɛ̃/","pos":"🐬","tr":"yunus","ex":"Le dauphin est gris.","exTr":"Yunus gri."},{"w":"la baleine","ipa":"/la ba.lɛn/","pos":"🐳","tr":"balina","ex":"La baleine est énorme.","exTr":"Balina çok büyük."},{"w":"le requin","ipa":"/lə ʁə.kɛ̃/","pos":"🦈","tr":"köpekbalığı","ex":"Le requin est grand.","exTr":"Köpekbalığı büyük."},{"w":"la tortue","ipa":"/la tɔʁ.ty/","pos":"🐢","tr":"kaplumbağa","ex":"La tortue est lente.","exTr":"Kaplumbağa yavaş."},{"w":"le crabe","ipa":"/lə kʁab/","pos":"🦀","tr":"yengeç","ex":"Le crabe est rouge.","exTr":"Yengeç kırmızı."},{"w":"la pieuvre","ipa":"/la pjœvʁ/","pos":"🐙","tr":"ahtapot","ex":"La pieuvre a huit bras.","exTr":"Ahtapotun sekiz kolu var."},{"w":"grand","ipa":"/ɡʁɑ̃/","pos":"📏","tr":"büyük, uzun","ex":"Le requin est grand.","exTr":"Köpekbalığı büyük."}],"chunks":[{"en":"Il est grand.","tr":"O büyük. (eril)"},{"en":"Elle est petite.","tr":"O küçük. (dişil)"},{"en":"J'aime le dauphin.","tr":"Yunusu severim."},{"en":"Oh là là !","tr":"Vay vay! / Aman!"}],"grammar":{"point":"Il est… / Elle est…","tr":"Eril kelimeler (le poisson) için 'il est', dişil kelimeler (la baleine) için 'elle est' deriz. Dişil olunca sıfatın sonuna çoğunlukla -e eklenir: 'grand' → 'grande', 'petit' → 'petite'.","examples":["Le requin est grand.","La baleine est grande.","Il est petit.","Elle est petite."]},"questions":[{"q":"De quelle couleur est le crabe ?","a":"Il est rouge."},{"q":"Comment est la tortue ?","a":"Elle est lente."},{"q":"Combien de bras a la pieuvre ?","a":"Elle a huit bras."}],"quiz":[{"q":"🐳 La baleine est ___.","o":["grand","grande","petit"],"a":1,"why":"Baleine dişil olduğu için 'grande' kullanılır."},{"q":"🐬 C'est un ___.","o":["crabe","requin","dauphin"],"a":2,"why":""},{"q":"Le poisson est ___.","o":["petit","petite","grande"],"a":0,"why":""},{"q":"La pieuvre a ___ bras.","o":["six","huit","deux"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Le requin est grand.","cue":"poisson / petit","answer":"Le poisson est petit."},{"type":"Dönüştürme","prompt":"Il est grand.","cue":"Elle","answer":"Elle est grande."},{"type":"Genişletme","prompt":"Le dauphin est gris.","cue":"très beau","answer":"Le dauphin est gris et très beau."}],"sounds":[{"focus":"/ɛ̃/","tr":"'dauphin' ve 'requin' içindeki 'in' burun sesidir. Ağzını yarı açık tut, 'e' de ve havayı burnundan bırak. Sonda 'n' sesi duyulmaz.","pairs":["requin / reine","vin / va","pain / pas"]}],"mission":{"brief":"Oyun: Akvaryum gezisi! Claude, arkadaşın Léa olacak. Gördüğün deniz hayvanlarını Fransızca adlandır ve 'Il est…' / 'Elle est…' ile tarif et.","persona":"Léa, a cheerful 7-year-old French girl visiting the aquarium. Uses very short, simple French sentences and lots of encouragement. Asks one question at a time. Hidden fact: Léa's secret favourite sea animal is the octopus (la pieuvre) because it has eight arms, but she only says it if the child asks 'Quel est ton animal préféré ?'.","goal":"En az üç deniz hayvanını adlandır ve birini 'Il est…' / 'Elle est…' ile tarif et.","opener":"Salut ! Je suis Léa. Regarde, un poisson ! Il est orange. Et toi, tu vois quel animal ?"}},"FK1-024":{"objectives":["Taşıtların adlarını Fransızca söylemek","'Je vais à l'école en bus' gibi cümlelerle nasıl gittiğini anlatmak","'Tu vas comment ?' sorusunu sormak ve cevaplamak"],"dialogues":[{"title":"Le matin","setting":"Sabah, Léa ve Hugo okula nasıl gittiklerini konuşuyor.","lines":[{"s":"Léa","en":"Salut Hugo ! Tu vas à l'école comment ?","tr":"Selam Hugo! Okula nasıl gidiyorsun?"},{"s":"Hugo","en":"Je vais à l'école en bus. Et toi ?","tr":"Okula otobüsle gidiyorum. Ya sen?"},{"s":"Léa","en":"Moi, je vais à l'école à vélo.","tr":"Ben okula bisikletle gidiyorum."},{"s":"Hugo","en":"Tu as un vélo rouge ?","tr":"Kırmızı bir bisikletin mi var?"},{"s":"Léa","en":"Oui ! Et Tom va à l'école en voiture avec Maman.","tr":"Evet! Tom da annemle arabayla okula gidiyor."},{"s":"Hugo","en":"Super ! À demain !","tr":"Süper! Yarın görüşürüz!"}]},{"title":"À la gare","setting":"Léa, Tom ve Papa Mamie'ye gitmek için tren istasyonunda.","lines":[{"s":"Tom","en":"Papa, c'est quoi, ça ?","tr":"Baba, bu da ne?"},{"s":"Papa","en":"C'est le train. Il est très long.","tr":"Bu tren. Çok uzun."},{"s":"Tom","en":"Nous allons chez Mamie en train ?","tr":"Mamie'ye trenle mi gidiyoruz?"},{"s":"Papa","en":"Oui ! Le train est rapide.","tr":"Evet! Tren hızlı."},{"s":"Léa","en":"Je vois un grand camion !","tr":"Büyük bir kamyon görüyorum!"},{"s":"Papa","en":"Il est jaune. Allez, montez !","tr":"Sarı. Hadi, binin!"},{"s":"Tom","en":"Youpi ! Le train arrive !","tr":"Yaşasın! Tren geliyor!"}]},{"title":"Les vacances","setting":"Elif, tatilde nasıl yolculuk edeceğini Léa'ya anlatıyor.","lines":[{"s":"Elif","en":"Léa, je vais en Turquie !","tr":"Léa, ben Türkiye'ye gidiyorum!"},{"s":"Léa","en":"Tu vas en Turquie en voiture ?","tr":"Türkiye'ye arabayla mı gidiyorsun?"},{"s":"Elif","en":"Non, je vais en avion.","tr":"Hayır, uçakla gidiyorum."},{"s":"Léa","en":"Oh, l'avion ! C'est génial !","tr":"Oh, uçak! Harika!"},{"s":"Elif","en":"Et après, je prends le bateau avec Papa.","tr":"Sonra babamla tekneye biniyorum."},{"s":"Léa","en":"Bon voyage, Elif !","tr":"İyi yolculuklar Elif!"}]}],"reading":{"title":"Comment on voyage ?","paras":[{"en":"Il y a beaucoup de transports. Papa va au travail en voiture. Moi, je vais à l'école à vélo. Hugo prend le bus. Pour aller chez Mamie, nous prenons le train. Le camion est grand et l'avion est rapide. Sur la mer, il y a un bateau. J'aime les transports !","tr":"Çok çeşit taşıt var. Babam işe arabayla gider. Ben okula bisikletle giderim. Hugo otobüse biner. Mamie'nin evine gitmek için trene bineriz. Kamyon büyüktür, uçak hızlıdır. Denizde bir tekne var. Taşıtları severim!"}]},"vocab":[{"w":"la voiture","ipa":"/la vwa.tyʁ/","pos":"🚗","tr":"araba","ex":"Tom va à l'école en voiture.","exTr":"Tom okula arabayla gidiyor."},{"w":"le vélo","ipa":"/lə ve.lo/","pos":"🚲","tr":"bisiklet","ex":"Je vais à l'école à vélo.","exTr":"Okula bisikletle gidiyorum."},{"w":"le bus","ipa":"/lə bys/","pos":"🚌","tr":"otobüs","ex":"Je vais à l'école en bus.","exTr":"Okula otobüsle gidiyorum."},{"w":"le train","ipa":"/lə tʁɛ̃/","pos":"🚆","tr":"tren","ex":"Le train est rapide.","exTr":"Tren hızlı."},{"w":"l'avion","ipa":"/la.vjɔ̃/","pos":"✈️","tr":"uçak","ex":"Je vais en avion.","exTr":"Uçakla gidiyorum."},{"w":"le bateau","ipa":"/lə ba.to/","pos":"🚢","tr":"tekne, gemi","ex":"Je prends le bateau.","exTr":"Tekneye biniyorum."},{"w":"le camion","ipa":"/lə ka.mjɔ̃/","pos":"🚚","tr":"kamyon","ex":"Je vois un grand camion.","exTr":"Büyük bir kamyon görüyorum."},{"w":"l'école","ipa":"/le.kɔl/","pos":"🏫","tr":"okul","ex":"Tu vas à l'école comment ?","exTr":"Okula nasıl gidiyorsun?"}],"chunks":[{"en":"Tu vas comment ?","tr":"Nasıl gidiyorsun?"},{"en":"Je vais en bus.","tr":"Otobüsle gidiyorum."},{"en":"Je vais à vélo.","tr":"Bisikletle gidiyorum."},{"en":"Bon voyage !","tr":"İyi yolculuklar!"}],"grammar":{"point":"Je vais en… / à…","tr":"Bir yere nasıl gittiğimizi söylerken 'Je vais' deriz. Araba, otobüs, tren, uçak gibi taşıtlarla 'en' kullanırız: 'en bus', 'en train'. Bisikletle gitmek için ise 'à vélo' deriz.","examples":["Je vais à l'école en bus.","Tu vas en train ?","Il va en voiture.","Je vais à vélo."]},"questions":[{"q":"Comment Hugo va-t-il à l'école ?","a":"Il va à l'école en bus."},{"q":"Comment Léa va-t-elle à l'école ?","a":"Elle va à l'école à vélo."},{"q":"Comment Elif va-t-elle en Turquie ?","a":"Elle va en Turquie en avion."}],"quiz":[{"q":"🚆 Nous allons chez Mamie en ___.","o":["bateau","train","camion"],"a":1,"why":""},{"q":"Je vais à l'école ___ vélo.","o":["en","au","à"],"a":2,"why":"Bisikletle gitmek için 'à vélo' denir."},{"q":"✈️ C'est ___.","o":["l'avion","le bus","la voiture"],"a":0,"why":""},{"q":"Hugo va à l'école ___.","o":["en voiture","à vélo","en bus"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Je vais à l'école en bus.","cue":"voiture","answer":"Je vais à l'école en voiture."},{"type":"Dönüştürme","prompt":"Je vais en train.","cue":"Tom","answer":"Tom va en train."},{"type":"Soru yap","prompt":"Je vais à l'école en bus.","cue":"Tu… comment ?","answer":"Tu vas à l'école comment ?"}],"sounds":[{"focus":"/z/ (liaison)","tr":"Fransızcada bir kelimenin sonundaki sessiz harf, ardından sesli harfle başlayan kelime gelince duyulabilir: 'les avions' → 'le-za-vyon'. Bu 'liaison' denir. Bu yüzden 'les' sonundaki s, 'avions' ile birleşip 'z' gibi okunur.","pairs":["les avions / les bus","des amis / des chats"]}],"mission":{"brief":"Oyun: Okula nasıl gidiyorsun? Claude, arkadaşın Hugo olacak. Okula nasıl gittiğini Fransızca anlat ve Hugo'ya 'Tu vas comment ?' diye sor.","persona":"Hugo, a cheerful 7-year-old French boy. Uses very short, simple French sentences and lots of encouragement. Asks one question at a time. Hidden fact: Hugo's secret dream is to travel by hot-air balloon (en montgolfière), but he only says it if the child asks 'Tu veux voyager comment ?' or 'Tu aimes quel transport ?'.","goal":"Okula nasıl gittiğini söyle ve en az iki taşıtı Fransızca adlandır.","opener":"Salut ! Je suis Hugo. Moi, je vais à l'école en bus. Et toi, tu vas à l'école comment ?"}},"FK1-025":{"objectives":["Evcil hayvanlarını Fransızca tanıtmak","'J'ai un chat' gibi cümlelerle hayvanın olduğunu söylemek","'Il est…' ile hayvanını tarif etmek"],"dialogues":[{"title":"Voici Minou !","setting":"Léa arkadaşı Hugo'ya kedisini tanıtıyor.","lines":[{"s":"Léa","en":"Salut Hugo ! J'ai un chat.","tr":"Selam Hugo! Benim bir kedim var."},{"s":"Hugo","en":"Il s'appelle comment ?","tr":"Adı ne?"},{"s":"Léa","en":"Il s'appelle Minou.","tr":"Adı Minou."},{"s":"Hugo","en":"Il est gentil ?","tr":"Uslu mu?"},{"s":"Léa","en":"Oui, il est très gentil !","tr":"Evet, çok uslu!"},{"s":"Hugo","en":"Et il est grand ?","tr":"Peki büyük mü?"},{"s":"Léa","en":"Non, il est petit.","tr":"Hayır, küçük."}]},{"title":"Chez Elif","setting":"Elif, Léa'ya evindeki hayvanları gösteriyor.","lines":[{"s":"Elif","en":"Regarde, Léa ! Voici mon chien.","tr":"Bak Léa! İşte köpeğim."},{"s":"Léa","en":"Il est beau ! Il s'appelle comment ?","tr":"Çok güzel! Adı ne?"},{"s":"Elif","en":"Il s'appelle Can.","tr":"Adı Can."},{"s":"Léa","en":"Tu as un autre animal ?","tr":"Başka hayvanın var mı?"},{"s":"Elif","en":"Oui, j'ai un poisson rouge.","tr":"Evet, bir kırmızı balığım var."},{"s":"Léa","en":"Il est joli !","tr":"Çok şirin!"}]},{"title":"Le petit lapin","setting":"Tom, Mamie'ye yeni tavşanını gösteriyor.","lines":[{"s":"Tom","en":"Mamie, j'ai un lapin !","tr":"Mamie, benim bir tavşanım var!"},{"s":"Mamie","en":"Oh, il est mignon ! Il mange quoi ?","tr":"Ah, çok sevimli! Ne yer?"},{"s":"Tom","en":"Il mange une carotte.","tr":"Havuç yer."},{"s":"Mamie","en":"Il a de longues oreilles !","tr":"Uzun kulakları var!"},{"s":"Tom","en":"Oui, et il a une petite queue.","tr":"Evet, bir de küçük kuyruğu var."},{"s":"Mamie","en":"Tu aimes ton lapin ?","tr":"Tavşanını seviyor musun?"},{"s":"Tom","en":"Oui, je l'aime beaucoup !","tr":"Evet, onu çok seviyorum!"}]}],"reading":{"title":"Mon chat Minou","paras":[{"en":"J'ai un chat. Il s'appelle Minou. Il est petit et il est gris. Il a une longue queue et quatre pattes. Minou mange du poisson. Il aime jouer avec moi. Le soir, il dort sur mon lit. Je l'aime beaucoup. Et toi, tu as un animal ?","tr":"Benim bir kedim var. Adı Minou. Küçük ve gri. Uzun bir kuyruğu ve dört patisi var. Minou balık yer. Benimle oynamayı sever. Akşamları yatağımda uyur. Onu çok seviyorum. Peki sen, bir hayvanın var mı?"}]},"vocab":[{"w":"le chat","ipa":"/lə ʃa/","pos":"🐱","tr":"kedi","ex":"J'ai un chat.","exTr":"Benim bir kedim var."},{"w":"le chien","ipa":"/lə ʃjɛ̃/","pos":"🐶","tr":"köpek","ex":"Voici mon chien.","exTr":"İşte köpeğim."},{"w":"le lapin","ipa":"/lə la.pɛ̃/","pos":"🐰","tr":"tavşan","ex":"J'ai un lapin !","exTr":"Benim bir tavşanım var!"},{"w":"le poisson","ipa":"/lə pwa.sɔ̃/","pos":"🐟","tr":"balık","ex":"Minou mange du poisson.","exTr":"Minou balık yer."},{"w":"la queue","ipa":"/la kø/","pos":"🐈","tr":"kuyruk","ex":"Il a une longue queue.","exTr":"Uzun bir kuyruğu var."},{"w":"la patte","ipa":"/la pat/","pos":"🐾","tr":"pati","ex":"Il a quatre pattes.","exTr":"Dört patisi var."},{"w":"petit","ipa":"/pə.ti/","pos":"🤏","tr":"küçük","ex":"Il est petit.","exTr":"O küçük."},{"w":"gentil","ipa":"/ʒɑ̃.ti/","pos":"😊","tr":"uslu, nazik","ex":"Il est très gentil.","exTr":"O çok uslu."}],"chunks":[{"en":"J'ai un chat.","tr":"Benim bir kedim var."},{"en":"Il s'appelle comment ?","tr":"Adı ne?"},{"en":"Il est mignon !","tr":"O çok sevimli!"},{"en":"Je l'aime beaucoup.","tr":"Onu çok seviyorum."}],"grammar":{"point":"J'ai… / Il est…","tr":"Bir hayvanın olduğunu söylerken 'J'ai un chat' deriz; 'j'ai' aslında 'je ai' olur ama 'e' düşer. Hayvanı anlatırken erkek hayvan için 'Il est petit', dişi için 'Elle est petite' deriz.","examples":["J'ai un chien.","J'ai une souris.","Il est petit.","Elle est gentille."]},"questions":[{"q":"Il s'appelle comment, le chat de Léa ?","a":"Il s'appelle Minou."},{"q":"Qu'est-ce que Tom a ?","a":"Il a un lapin."},{"q":"Où dort Minou le soir ?","a":"Il dort sur le lit."}],"quiz":[{"q":"🐶 = ?","o":["le chat","le chien","le lapin"],"a":1,"why":""},{"q":"J'___ un poisson.","o":["ai","suis","est"],"a":0,"why":"'J'ai' = bende var."},{"q":"Minou mange du ___.","o":["lapin","chien","poisson"],"a":2,"why":""},{"q":"Le chien d'Elif s'appelle…","o":["Rex","Minou","Can"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"J'ai un chat.","cue":"chien","answer":"J'ai un chien."},{"type":"Yerine koyma","prompt":"Il est petit.","cue":"gentil","answer":"Il est gentil."},{"type":"Soru yap","prompt":"Il s'appelle Minou.","cue":"Il s'appelle…?","answer":"Il s'appelle comment ?"}],"sounds":[{"focus":"/ɛ̃/ ve /ɑ̃/","tr":"Fransızcada burun sesli harfleri vardır: 'chien' ve 'lapin' sonundaki 'n' okunmaz, ses burundan çıkar. 'ɛ̃' için 'e'yi hafifçe burnundan söyle; 'n' ya da 'm' harfini ayrıca söyleme.","pairs":["lapin / lapine","chien / chat","gentil / petit"]}],"mission":{"brief":"Oyun: Evcil hayvan sohbeti! Claude, arkadaşın Léa olacak. Léa'ya hayvanı olup olmadığını sor, adını ve nasıl biri olduğunu Fransızca öğren.","persona":"Léa, a cheerful 7-year-old French girl. Speaks very short, simple French sentences and asks one question at a time. Hidden fact: Léa's cat Minou is grey and sleeps on her bed, but she only tells the child its colour or where it sleeps if the child asks.","goal":"Léa'nın hayvanının adını ve bir özelliğini Fransızca sorup öğren.","opener":"Salut ! Je suis Léa. J'ai un animal. Et toi, tu as un animal ?"}},"FK1-026":{"objectives":["Sabah rutinini Fransızca anlatmak","'Je me lève', 'je mange' gibi cümleler kurmak","'Tu te lèves à quelle heure ?' sorusunu sormak ve yanıtlamak"],"dialogues":[{"title":"Debout, Léa !","setting":"Sabah, Maman Léa'yı yatağından kaldırıyor.","lines":[{"s":"Maman","en":"Bonjour Léa ! Il est sept heures.","tr":"Günaydın Léa! Saat yedi."},{"s":"Léa","en":"Oh, j'ai sommeil, Maman.","tr":"Ah, uykum var anne."},{"s":"Maman","en":"Debout ! Lève-toi !","tr":"Kalk bakalım! Yataktan çık!"},{"s":"Léa","en":"D'accord, je me lève.","tr":"Tamam, kalkıyorum."},{"s":"Maman","en":"Va à la salle de bains.","tr":"Banyoya git."},{"s":"Léa","en":"Je me brosse les dents !","tr":"Dişlerimi fırçalıyorum!"}]},{"title":"Le petit-déjeuner","setting":"Aile kahvaltı masasında. Papa, Léa ve Tom konuşuyor.","lines":[{"s":"Papa","en":"Tu as faim, Léa ?","tr":"Acıktın mı Léa?"},{"s":"Léa","en":"Oui, j'ai très faim !","tr":"Evet, çok acıktım!"},{"s":"Papa","en":"Tu manges quoi ?","tr":"Ne yiyorsun?"},{"s":"Léa","en":"Je mange du pain et je bois du lait.","tr":"Ekmek yiyorum ve süt içiyorum."},{"s":"Tom","en":"Moi, je mange des céréales.","tr":"Ben mısır gevreği yiyorum."},{"s":"Papa","en":"Bon appétit, les enfants !","tr":"Afiyet olsun çocuklar!"}]},{"title":"Vite, l'école !","setting":"Léa ve Elif sabah okula gitmeden önce telefonda konuşuyor.","lines":[{"s":"Elif","en":"Allô Léa ! Tu te lèves à quelle heure ?","tr":"Alo Léa! Kaçta kalkıyorsun?"},{"s":"Léa","en":"Je me lève à sept heures.","tr":"Yedide kalkıyorum."},{"s":"Elif","en":"Et tu prends ton petit-déjeuner ?","tr":"Kahvaltını yapıyor musun?"},{"s":"Léa","en":"Oui, puis je m'habille.","tr":"Evet, sonra giyiniyorum."},{"s":"Elif","en":"Tu as ton sac ?","tr":"Çantan hazır mı?"},{"s":"Léa","en":"Oui ! À tout à l'heure à l'école !","tr":"Evet! Birazdan okulda görüşürüz!"}]}],"reading":{"title":"Le matin de Léa","paras":[{"en":"Le matin, je me lève à sept heures. Je vais à la salle de bains. Je me lave et je me brosse les dents. Puis je m'habille. Je mange mon petit-déjeuner avec Papa et Tom. Je prends mon sac. Maman me dit : « Au revoir, Léa ! » Je vais à l'école. J'aime le matin !","tr":"Sabahları yedide kalkarım. Banyoya giderim. Yıkanırım ve dişlerimi fırçalarım. Sonra giyinirim. Kahvaltımı Papa ve Tom ile yaparım. Çantamı alırım. Maman bana: « Hoşça kal Léa! » der. Okula giderim. Sabahı severim!"}]},"vocab":[{"w":"le matin","ipa":"/lə ma.tɛ̃/","pos":"🌅","tr":"sabah","ex":"Le matin, je me lève à sept heures.","exTr":"Sabahları yedide kalkarım."},{"w":"le lit","ipa":"/lə li/","pos":"🛏️","tr":"yatak","ex":"Je me lève du lit.","exTr":"Yataktan kalkarım."},{"w":"les dents","ipa":"/le dɑ̃/","pos":"🦷","tr":"dişler","ex":"Je me brosse les dents.","exTr":"Dişlerimi fırçalarım."},{"w":"le petit-déjeuner","ipa":"/lə pə.ti de.ʒœ.ne/","pos":"🥐","tr":"kahvaltı","ex":"Je mange mon petit-déjeuner.","exTr":"Kahvaltımı yaparım."},{"w":"le pain","ipa":"/lə pɛ̃/","pos":"🍞","tr":"ekmek","ex":"Je mange du pain.","exTr":"Ekmek yerim."},{"w":"le lait","ipa":"/lə lɛ/","pos":"🥛","tr":"süt","ex":"Je bois du lait.","exTr":"Süt içerim."},{"w":"le sac","ipa":"/lə sak/","pos":"🎒","tr":"çanta","ex":"Je prends mon sac.","exTr":"Çantamı alırım."},{"w":"s'habiller","ipa":"/sa.bi.je/","pos":"👕","tr":"giyinmek","ex":"Puis je m'habille.","exTr":"Sonra giyinirim."}],"chunks":[{"en":"Je me lève à sept heures.","tr":"Yedide kalkarım."},{"en":"Je me brosse les dents.","tr":"Dişlerimi fırçalarım."},{"en":"J'ai très faim !","tr":"Çok acıktım!"},{"en":"Bon appétit !","tr":"Afiyet olsun!"}],"grammar":{"point":"Je me lève / Je mange","tr":"Günlük işleri anlatırken 'je' ile başlarız: 'Je mange', 'Je prends'. Kendimize yaptığımız işlerde 'me' de ekleriz: 'Je me lève', 'Je me lave'. 'Me' ünlü harfle başlayan kelimeden önce 'm'' olur: 'Je m'habille'.","examples":["Je me lève à sept heures.","Je me lave.","Je m'habille.","Je mange du pain."]},"questions":[{"q":"Léa se lève à quelle heure ?","a":"Elle se lève à sept heures."},{"q":"Qu'est-ce que Léa mange et boit ?","a":"Elle mange du pain et elle boit du lait."},{"q":"Avec qui Léa mange son petit-déjeuner ?","a":"Avec Papa et Tom."}],"quiz":[{"q":"🦷 = ?","o":["les dents","le lait","le sac"],"a":0,"why":""},{"q":"Je ___ lève à sept heures.","o":["te","me","se"],"a":1,"why":"'Je' ile 'me' kullanılır."},{"q":"Je bois du ___.","o":["pain","sac","lait"],"a":2,"why":""},{"q":"Après le petit-déjeuner, Léa…","o":["s'habille","dort","joue"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Je mange du pain.","cue":"boire / lait","answer":"Je bois du lait."},{"type":"Yerine koyma","prompt":"Je me lève à sept heures.","cue":"huit heures","answer":"Je me lève à huit heures."},{"type":"Soru yap","prompt":"Je me lève à sept heures.","cue":"Tu… à quelle heure ?","answer":"Tu te lèves à quelle heure ?"}],"sounds":[{"focus":"/y/","tr":"Fransızca 'u' harfi Türkçedeki 'ü' gibi okunur. Dudaklarını öne doğru yuvarla ve 'i' demeye çalış: 'sur', 'salut', 'tu'. 'ou' ise Türkçe 'u' gibidir.","pairs":["tu / tout","rue / roue","sur / sous"]}],"mission":{"brief":"Oyun: Sabah sohbeti! Claude, arkadaşın Hugo olacak. Hugo'ya sabah kaçta kalktığını ve kahvaltıda ne yediğini Fransızca sor.","persona":"Hugo, a cheerful 7-year-old French boy. Speaks very short, simple French sentences and asks one question at a time. Hidden fact: Hugo gets up at half past six because he walks his dog Rex before school, but he only says this if the child asks what time he gets up or what he does in the morning.","goal":"Hugo'ya en az iki soru sor ve cevaplarını anla.","opener":"Bonjour ! Je suis Hugo. Le matin, j'ai sommeil ! Et toi, tu te lèves à quelle heure ?"}},"FK1-027":{"objectives":["Yatma saati rutinini Fransızca anlatmak","'Bonne nuit' ve 'Je dors' gibi kalıpları kullanmak","'J'ai sommeil' ve 'Je veux une histoire' demek"],"dialogues":[{"title":"Il est huit heures","setting":"Akşam, Papa Léa ve Tom'a yatma vaktinin geldiğini söylüyor.","lines":[{"s":"Papa","en":"Il est huit heures. C'est l'heure du coucher !","tr":"Saat sekiz. Yatma vakti!"},{"s":"Tom","en":"Oh non, Papa ! Je ne suis pas fatigué.","tr":"Ah hayır baba! Ben yorgun değilim."},{"s":"Léa","en":"Moi, j'ai sommeil.","tr":"Benim uykum var."},{"s":"Papa","en":"Mettez votre pyjama, s'il vous plaît.","tr":"Pijamalarınızı giyin lütfen."},{"s":"Tom","en":"Mon pyjama est bleu !","tr":"Benim pijamam mavi!"},{"s":"Léa","en":"Et le mien est rose.","tr":"Benimki de pembe."}]},{"title":"Une histoire, s'il te plaît","setting":"Léa yatağında, Maman'dan hikâye istiyor.","lines":[{"s":"Léa","en":"Maman, tu lis une histoire ?","tr":"Anne, bir hikâye okur musun?"},{"s":"Maman","en":"Oui, ma chérie. Quel livre tu veux ?","tr":"Evet, canım. Hangi kitabı istiyorsun?"},{"s":"Léa","en":"Je veux le livre du petit chat.","tr":"Küçük kedinin kitabını istiyorum."},{"s":"Maman","en":"D'accord. Voilà ton doudou.","tr":"Tamam. İşte oyuncağın."},{"s":"Léa","en":"Merci, Maman. Je t'aime.","tr":"Teşekkürler anne. Seni seviyorum."},{"s":"Maman","en":"Moi aussi, je t'aime. Un câlin ?","tr":"Ben de seni seviyorum. Bir sarılma?"},{"s":"Léa","en":"Oui, un gros câlin !","tr":"Evet, kocaman bir sarılma!"}]},{"title":"Bonne nuit !","setting":"Işıklar kapanıyor. Léa ve Mamie telefonda iyi geceler diliyor.","lines":[{"s":"Mamie","en":"Allô Léa ! Tu vas au lit ?","tr":"Alo Léa! Yatmaya mı gidiyorsun?"},{"s":"Léa","en":"Oui, Mamie. Il est nuit.","tr":"Evet Mamie. Gece oldu."},{"s":"Mamie","en":"Regarde la lune dans le ciel !","tr":"Gökyüzündeki aya bak!"},{"s":"Léa","en":"Oh, elle est belle !","tr":"Ah, çok güzel!"},{"s":"Mamie","en":"Éteins la lumière. Bonne nuit, Léa.","tr":"Işığı kapat. İyi geceler Léa."},{"s":"Léa","en":"Bonne nuit, Mamie. Je dors !","tr":"İyi geceler Mamie. Uyuyorum!"}]}],"reading":{"title":"Le soir de Léa","paras":[{"en":"Le soir, j'ai sommeil. Je mets mon pyjama. Je me brosse les dents. Maman lit une histoire dans mon lit. J'ai mon doudou avec moi. Puis Maman éteint la lumière. Par la fenêtre, je vois la lune. Je dis : « Bonne nuit, Maman ! » Et je dors.","tr":"Akşamları uykum gelir. Pijamamı giyerim. Dişlerimi fırçalarım. Maman yatağımda bir hikâye okur. Oyuncağım yanımda. Sonra Maman ışığı kapatır. Pencereden ayı görürüm. « İyi geceler Maman! » derim. Ve uyurum."}]},"vocab":[{"w":"le pyjama","ipa":"/lə pi.ʒa.ma/","pos":"👚","tr":"pijama","ex":"Mon pyjama est bleu.","exTr":"Pijamam mavi."},{"w":"le lit","ipa":"/lə li/","pos":"🛏️","tr":"yatak","ex":"Tu vas au lit ?","exTr":"Yatmaya mı gidiyorsun?"},{"w":"l'histoire","ipa":"/lis.twaʁ/","pos":"📖","tr":"hikâye","ex":"Maman lit une histoire.","exTr":"Maman bir hikâye okur."},{"w":"le doudou","ipa":"/lə du.du/","pos":"🧸","tr":"uyku oyuncağı","ex":"J'ai mon doudou.","exTr":"Oyuncağım yanımda."},{"w":"la lune","ipa":"/la lyn/","pos":"🌙","tr":"ay","ex":"Je vois la lune.","exTr":"Ayı görürüm."},{"w":"la lumière","ipa":"/la ly.mjɛʁ/","pos":"💡","tr":"ışık","ex":"Éteins la lumière.","exTr":"Işığı kapat."},{"w":"le câlin","ipa":"/lə ka.lɛ̃/","pos":"🤗","tr":"sarılma","ex":"Un gros câlin !","exTr":"Kocaman bir sarılma!"},{"w":"dormir","ipa":"/dɔʁ.miʁ/","pos":"😴","tr":"uyumak","ex":"Je dors.","exTr":"Uyuyorum."}],"chunks":[{"en":"Bonne nuit !","tr":"İyi geceler!"},{"en":"J'ai sommeil.","tr":"Uykum var."},{"en":"Je t'aime.","tr":"Seni seviyorum."},{"en":"Un gros câlin !","tr":"Kocaman bir sarılma!"}],"grammar":{"point":"Je veux… / Je dors","tr":"Bir şey istediğimizde 'Je veux' deriz: 'Je veux une histoire.' Nazik olmak için sonuna 's'il te plaît' ekleriz. 'Dormir' fiilinde 'je dors' (uyuyorum), 'tu dors' (uyuyorsun) deriz.","examples":["Je veux une histoire.","Je veux mon doudou.","Je dors.","Tu dors ?"]},"questions":[{"q":"De quelle couleur est le pyjama de Tom ?","a":"Il est bleu."},{"q":"Qu'est-ce que Maman lit à Léa ?","a":"Elle lit une histoire."},{"q":"Qu'est-ce que Léa voit par la fenêtre ?","a":"Elle voit la lune."}],"quiz":[{"q":"🌙 = ?","o":["la lune","la lumière","le lit"],"a":0,"why":""},{"q":"Le soir, Léa met son ___.","o":["sac","pyjama","pain"],"a":1,"why":""},{"q":"Avant de dormir, on dit…","o":["Bonjour !","Salut !","Bonne nuit !"],"a":2,"why":""},{"q":"Je ___ une histoire.","o":["veux","dors","vais"],"a":0,"why":"'Je veux' = istiyorum."}],"drills":[{"type":"Yerine koyma","prompt":"Je veux une histoire.","cue":"mon doudou","answer":"Je veux mon doudou."},{"type":"Dönüştürme","prompt":"Je dors.","cue":"Tu","answer":"Tu dors."},{"type":"Soru yap","prompt":"Tu vas au lit.","cue":"Tu…?","answer":"Tu vas au lit ?"}],"sounds":[{"focus":"/y/","tr":"Fransızca 'u' harfi Türkçedeki 'ü' gibi okunur. Dudaklarını öne doğru yuvarla ve 'i' demeye çalış: 'lune', 'lumière', 'tu'. 'ou' ise Türkçe 'u' gibidir.","pairs":["lune / loup","tu / tout","sur / sous"]}],"mission":{"brief":"Oyun: İyi geceler! Claude, küçük kardeşin Tom olacak. Tom'u yatağa götür: pijamasını giymesini söyle, hikâye sor ve ona iyi geceler dile.","persona":"Tom, a lively 5-year-old French boy who does not want to go to bed. Speaks very short, simple French sentences and asks one question at a time. Hidden fact: Tom cannot sleep without his doudou, a small blue rabbit, which is hidden under his bed; he only says this if the child asks what he needs or what he wants.","goal":"Tom'a yatma vaktini hatırlat ve onun ne istediğini sorup öğren.","opener":"Non ! Je ne veux pas dormir ! Je ne suis pas fatigué."}},"FK1-028":{"objectives":["Dört mevsimin adını Fransızca söylemek","'Il fait chaud' ve 'Il pleut' ile havayı anlatmak","'Quelle saison tu aimes ?' sorusunu sormak ve yanıtlamak"],"dialogues":[{"title":"Quelle saison ?","setting":"Madame Martin sınıfta çocuklara mevsimleri soruyor.","lines":[{"s":"Madame Martin","en":"Il y a quatre saisons. Qui les connaît ?","tr":"Dört mevsim var. Onları kim biliyor?"},{"s":"Léa","en":"Moi ! Le printemps, l'été, l'automne et l'hiver.","tr":"Ben! İlkbahar, yaz, sonbahar ve kış."},{"s":"Madame Martin","en":"Bravo, Léa ! Quelle saison tu aimes ?","tr":"Aferin Léa! Hangi mevsimi seviyorsun?"},{"s":"Léa","en":"J'aime l'été. Il fait chaud !","tr":"Yazı severim. Hava sıcak!"},{"s":"Hugo","en":"Moi, j'aime l'hiver. Il neige !","tr":"Ben kışı severim. Kar yağıyor!"},{"s":"Madame Martin","en":"Très bien, les enfants !","tr":"Çok güzel çocuklar!"}]},{"title":"Quel temps fait-il ?","setting":"Léa ve Papa pencereden dışarıya bakıyor.","lines":[{"s":"Papa","en":"Regarde, Léa. Quel temps fait-il ?","tr":"Bak Léa. Hava nasıl?"},{"s":"Léa","en":"Il pleut, Papa !","tr":"Yağmur yağıyor baba!"},{"s":"Papa","en":"Oui, c'est l'automne.","tr":"Evet, sonbahar bu."},{"s":"Léa","en":"Il y a des feuilles jaunes et rouges.","tr":"Sarı ve kırmızı yapraklar var."},{"s":"Papa","en":"Prends ton manteau et tes bottes.","tr":"Montunu ve çizmelerini al."},{"s":"Léa","en":"Super ! Je saute dans l'eau !","tr":"Süper! Su birikintisine atlıyorum!"}]},{"title":"Au téléphone avec Elif","setting":"Léa, Türkiye'deki arkadaşı Elif ile telefonda konuşuyor.","lines":[{"s":"Léa","en":"Allô Elif ! Il fait quel temps chez toi ?","tr":"Alo Elif! Sizde hava nasıl?"},{"s":"Elif","en":"Il fait beau. Il y a du soleil.","tr":"Hava güzel. Güneş var."},{"s":"Léa","en":"C'est aussi l'hiver chez toi ?","tr":"Sizde de kış mı?"},{"s":"Elif","en":"Oui, mais il y a du soleil !","tr":"Evet ama güneş var!"},{"s":"Léa","en":"Chez moi, il fait froid.","tr":"Bizde hava soğuk."},{"s":"Elif","en":"Il neige chez toi ?","tr":"Sizde kar yağıyor mu?"},{"s":"Léa","en":"Oui, c'est l'hiver !","tr":"Evet, kış bu!"}]}],"reading":{"title":"Mes quatre saisons","paras":[{"en":"J'aime les saisons. Au printemps, il y a des fleurs. En été, il fait chaud et il y a du soleil. En automne, il pleut et les feuilles tombent. En hiver, il fait froid et il neige. Ma saison préférée, c'est l'été. Je joue dehors avec Tom et Rex !","tr":"Mevsimleri severim. İlkbaharda çiçekler olur. Yazın hava sıcaktır ve güneş vardır. Sonbaharda yağmur yağar ve yapraklar düşer. Kışın hava soğuktur ve kar yağar. En sevdiğim mevsim yaz. Tom ve Rex ile dışarıda oynarım!"}]},"vocab":[{"w":"le printemps","ipa":"/lə pʁɛ̃.tɑ̃/","pos":"🌷","tr":"ilkbahar","ex":"Au printemps, il y a des fleurs.","exTr":"İlkbaharda çiçekler olur."},{"w":"l'été","ipa":"/le.te/","pos":"☀️","tr":"yaz","ex":"J'aime l'été.","exTr":"Yazı severim."},{"w":"l'automne","ipa":"/lo.tɔn/","pos":"🍂","tr":"sonbahar","ex":"C'est l'automne.","exTr":"Sonbahar bu."},{"w":"l'hiver","ipa":"/li.vɛʁ/","pos":"⛄","tr":"kış","ex":"C'est l'hiver !","exTr":"Kış bu!"},{"w":"la neige","ipa":"/la nɛʒ/","pos":"❄️","tr":"kar","ex":"En hiver, il neige.","exTr":"Kışın kar yağar."},{"w":"la pluie","ipa":"/la plɥi/","pos":"🌧️","tr":"yağmur","ex":"Il pleut, c'est la pluie.","exTr":"Yağmur yağıyor, bu yağmur."},{"w":"le soleil","ipa":"/lə sɔ.lɛj/","pos":"🌞","tr":"güneş","ex":"Il y a du soleil.","exTr":"Güneş var."},{"w":"la feuille","ipa":"/la fœj/","pos":"🍁","tr":"yaprak","ex":"Il y a des feuilles jaunes.","exTr":"Sarı yapraklar var."}],"chunks":[{"en":"Quelle saison tu aimes ?","tr":"Hangi mevsimi seviyorsun?"},{"en":"Quel temps fait-il ?","tr":"Hava nasıl?"},{"en":"Il fait chaud.","tr":"Hava sıcak."},{"en":"Il fait froid.","tr":"Hava soğuk."}],"grammar":{"point":"Il fait… / Il y a…","tr":"Havayı anlatırken 'Il fait chaud' (hava sıcak), 'Il fait froid' (hava soğuk) deriz. Yağmur ve kar için fiil kullanırız: 'Il pleut', 'Il neige'. Bir şeyin var olduğunu 'Il y a du soleil' diyerek söyleriz.","examples":["Il fait chaud.","Il fait froid.","Il pleut.","Il y a du soleil."]},"questions":[{"q":"Quelle saison Léa aime-t-elle ?","a":"Elle aime l'été."},{"q":"Quel temps fait-il en automne ?","a":"Il pleut et il y a des feuilles."},{"q":"Quel temps fait-il chez Léa au téléphone ?","a":"Il fait froid et il neige."}],"quiz":[{"q":"❄️ = ?","o":["la pluie","le soleil","la neige"],"a":2,"why":""},{"q":"En été, il fait ___.","o":["chaud","froid","neige"],"a":0,"why":""},{"q":"Hugo aime…","o":["l'été","l'hiver","l'automne"],"a":1,"why":""},{"q":"Il ___ chaud.","o":["pleut","neige","fait"],"a":2,"why":"'Il fait chaud' = hava sıcak."}],"drills":[{"type":"Yerine koyma","prompt":"J'aime l'été.","cue":"l'hiver","answer":"J'aime l'hiver."},{"type":"Yerine koyma","prompt":"Il fait chaud.","cue":"froid","answer":"Il fait froid."},{"type":"Soru yap","prompt":"J'aime l'été.","cue":"Quelle saison…?","answer":"Quelle saison tu aimes ?"}],"sounds":[{"focus":"/ʁ/","tr":"Fransızca 'r' Türkçe 'r' gibi dil ucuyla çıkmaz. Boğazının arkasında hafifçe hırıltı gibi çıkar, 'h' ile 'g' arası bir ses. Önce gargara yapar gibi dene: 'printemps', 'hiver', 'froid'.","pairs":["rouge / bouge","froid / foi","hiver / hier"]}],"mission":{"brief":"Oyun: Hava durumu! Claude, Fransa'da yaşayan arkadaşın Léa olacak. Léa'ya şimdi hava nasıl olduğunu ve hangi mevsimi sevdiğini Fransızca sor.","persona":"Léa, a cheerful 7-year-old French girl. Speaks very short, simple French sentences and asks one question at a time. Hidden fact: Léa's favourite season is summer because she plays at the beach with her brother Tom, but she only says this if the child asks which season she likes.","goal":"Léa'ya hava durumunu ve sevdiği mevsimi sor.","opener":"Salut ! C'est Léa. Chez moi, il fait froid. Et chez toi, il fait quel temps ?"}},"FK1-029":{"objectives":["Evde yaptığın işleri Fransızca söylemek","'J'aide Maman' ve 'Je range' gibi cümleler kurmak","'Tu peux m'aider ?' diyerek yardım istemek"],"dialogues":[{"title":"On met la table","setting":"Akşam yemeğinden önce Maman, Léa ve Tom ile masayı hazırlıyor.","lines":[{"s":"Maman","en":"Léa, tu peux m'aider ?","tr":"Léa, bana yardım edebilir misin?"},{"s":"Léa","en":"Oui, Maman ! Je mets la table.","tr":"Evet anne! Masayı kuruyorum."},{"s":"Maman","en":"Merci ! Et toi, Tom ?","tr":"Teşekkürler! Peki sen Tom?"},{"s":"Tom","en":"Moi, je mets les verres.","tr":"Ben bardakları koyuyorum."},{"s":"Maman","en":"Très bien, mes chéris !","tr":"Çok güzel canlarım!"},{"s":"Léa","en":"J'aime aider à la maison.","tr":"Evde yardım etmeyi severim."}]},{"title":"Range tes jouets !","setting":"Papa, Tom'a odasını toplamasını söylüyor.","lines":[{"s":"Papa","en":"Tom, ta chambre n'est pas propre.","tr":"Tom, odan temiz değil."},{"s":"Tom","en":"Oh non ! Il y a beaucoup de jouets.","tr":"Ah hayır! Çok oyuncak var."},{"s":"Papa","en":"Range tes jouets, s'il te plaît.","tr":"Oyuncaklarını topla lütfen."},{"s":"Tom","en":"D'accord, Papa. Léa m'aide.","tr":"Tamam baba. Léa bana yardım ediyor."},{"s":"Léa","en":"Je fais ton lit, Tom.","tr":"Yatağını ben topluyorum Tom."},{"s":"Papa","en":"Bravo, les enfants ! Merci !","tr":"Aferin çocuklar! Teşekkürler!"},{"s":"Tom","en":"Maintenant, la chambre est propre !","tr":"Şimdi oda temiz!"}]},{"title":"Chez Mamie","setting":"Hafta sonu Léa, Mamie'nin evinde ona yardım ediyor.","lines":[{"s":"Mamie","en":"Léa, tu peux arroser la plante ?","tr":"Léa, çiçeği sulayabilir misin?"},{"s":"Léa","en":"Oui, Mamie. Voilà !","tr":"Evet Mamie. Buyur!"},{"s":"Mamie","en":"Et la poubelle, s'il te plaît.","tr":"Bir de çöpü, lütfen."},{"s":"Léa","en":"Je sors la poubelle. C'est facile !","tr":"Çöpü çıkarıyorum. Çok kolay!"},{"s":"Mamie","en":"Tu es très gentille, ma puce.","tr":"Çok naziksin tatlım."},{"s":"Léa","en":"Je passe le balai aussi ?","tr":"Ben de süpüreyim mi?"}]}],"reading":{"title":"J'aide ma famille","paras":[{"en":"À la maison, j'aide Maman et Papa. Je mets la table pour le dîner. Je range mes jouets dans ma chambre. Je fais mon lit le matin. Le week-end, j'arrose la plante de Mamie. Mon frère Tom aide aussi. Nous sommes contents. Les parents disent : « Merci, les enfants ! »","tr":"Evde Maman ve Papa'ya yardım ederim. Akşam yemeği için masayı kurarım. Odamda oyuncaklarımı toplarım. Sabahları yatağımı yaparım. Hafta sonu Mamie'nin çiçeğini sularım. Kardeşim Tom da yardım eder. Mutluyuz. Anne babamız: « Teşekkürler çocuklar! » der."}]},"vocab":[{"w":"la table","ipa":"/la tabl/","pos":"🍽️","tr":"masa","ex":"Je mets la table.","exTr":"Masayı kuruyorum."},{"w":"les jouets","ipa":"/le ʒwɛ/","pos":"🧸","tr":"oyuncaklar","ex":"Range tes jouets.","exTr":"Oyuncaklarını topla."},{"w":"le lit","ipa":"/lə li/","pos":"🛏️","tr":"yatak","ex":"Je fais mon lit.","exTr":"Yatağımı yaparım."},{"w":"la chambre","ipa":"/la ʃɑ̃bʁ/","pos":"🚪","tr":"oda","ex":"La chambre est propre.","exTr":"Oda temiz."},{"w":"la plante","ipa":"/la plɑ̃t/","pos":"🪴","tr":"bitki, çiçek","ex":"J'arrose la plante.","exTr":"Çiçeği sularım."},{"w":"la poubelle","ipa":"/la pu.bɛl/","pos":"🗑️","tr":"çöp kutusu","ex":"Je sors la poubelle.","exTr":"Çöpü çıkarırım."},{"w":"le balai","ipa":"/lə ba.lɛ/","pos":"🧹","tr":"süpürge","ex":"Je passe le balai.","exTr":"Süpürürüm."},{"w":"aider","ipa":"/e.de/","pos":"🤝","tr":"yardım etmek","ex":"J'aime aider à la maison.","exTr":"Evde yardım etmeyi severim."}],"chunks":[{"en":"Tu peux m'aider ?","tr":"Bana yardım edebilir misin?"},{"en":"Je range mes jouets.","tr":"Oyuncaklarımı toplarım."},{"en":"C'est facile !","tr":"Çok kolay!"},{"en":"Merci, les enfants !","tr":"Teşekkürler çocuklar!"}],"grammar":{"point":"Je mets / Je range / Je fais","tr":"Ev işlerini 'je' ile söyleriz: 'Je mets la table', 'Je range', 'Je fais mon lit'. 'Mon, ma, mes' sahip olduğumuz şeyi gösterir: 'mon lit' (erkek), 'ma chambre' (dişi), 'mes jouets' (çoğul).","examples":["Je mets la table.","Je range mes jouets.","Je fais mon lit.","Je sors la poubelle."]},"questions":[{"q":"Qu'est-ce que Léa met pour le dîner ?","a":"Elle met la table."},{"q":"Qui range les jouets dans la chambre ?","a":"Tom range les jouets, et Léa l'aide."},{"q":"Qu'est-ce que Léa arrose chez Mamie ?","a":"Elle arrose la plante."}],"quiz":[{"q":"🧹 = ?","o":["la poubelle","le balai","la table"],"a":1,"why":""},{"q":"Je ___ la table.","o":["mets","dors","vais"],"a":0,"why":"Masa için 'mettre' kullanılır."},{"q":"Je range mes ___.","o":["plante","balai","jouets"],"a":2,"why":"'Mes' çoğul kelimeyle gelir."},{"q":"Tom dit : « Maintenant, la chambre est… »","o":["propre","petite","froide"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Je mets la table.","cue":"ranger / jouets","answer":"Je range les jouets."},{"type":"Yerine koyma","prompt":"Je fais mon lit.","cue":"sortir / poubelle","answer":"Je sors la poubelle."},{"type":"Soru yap","prompt":"Tu m'aides.","cue":"Tu peux…?","answer":"Tu peux m'aider ?"}],"sounds":[{"focus":"/ɑ̃/","tr":"Fransızcada burun sesli harfleri vardır. 'Chambre' ve 'plante' içindeki 'an', 'am' ve 'en' burundan çıkar: 'a' sesini söylerken sanki nezle olmuş gibi burnundan hava ver. 'n' ya da 'm'yi ayrıca söyleme.","pairs":["sans / son","dans / de","enfant / enfin"]}],"mission":{"brief":"Oyun: Evde yardım! Claude, arkadaşın Hugo olacak. Hugo'ya evde hangi işlerde yardım ettiğini sor, sen de yaptığın işleri Fransızca anlat.","persona":"Hugo, a cheerful 7-year-old French boy. Speaks very short, simple French sentences and asks one question at a time. Hidden fact: Hugo's favourite chore is taking out the bin because he can then see the neighbour's dog, but he only says this if the child asks which chore he likes.","goal":"Hugo'ya en az iki ev işini sor ve kendi yaptığın bir işi söyle.","opener":"Salut ! Je suis Hugo. À la maison, j'aide Papa. Et toi, tu aides ta famille ?"}},"FK1-030":{"objectives":["En iyi arkadaşını Fransızca tanıtmak","'Il est drôle', 'Elle est gentille' ile arkadaşını tarif etmek","'On joue ensemble' diyerek birlikte oynamayı teklif etmek"],"dialogues":[{"title":"Mon ami Hugo","setting":"Léa, Madame Martin'e en iyi arkadaşını anlatıyor.","lines":[{"s":"Madame Martin","en":"Léa, qui est ton meilleur ami ?","tr":"Léa, en iyi arkadaşın kim?"},{"s":"Léa","en":"C'est Hugo, Madame.","tr":"Hugo, öğretmenim."},{"s":"Madame Martin","en":"Comment il est ?","tr":"Nasıl biri?"},{"s":"Léa","en":"Il est gentil et très drôle.","tr":"Uslu ve çok komik."},{"s":"Madame Martin","en":"Vous jouez à quoi ?","tr":"Ne oynuyorsunuz?"},{"s":"Léa","en":"Nous jouons au ballon dans le parc.","tr":"Parkta top oynuyoruz."}]},{"title":"Au parc avec Elif","setting":"Léa parkta Türk arkadaşı Elif ile oynuyor.","lines":[{"s":"Léa","en":"Elif, tu es ma meilleure amie !","tr":"Elif, sen benim en iyi arkadaşımsın!"},{"s":"Elif","en":"Toi aussi, Léa ! On joue ensemble ?","tr":"Sen de Léa! Birlikte oynayalım mı?"},{"s":"Léa","en":"Oui ! Tu veux jouer au ballon ?","tr":"Evet! Top oynamak ister misin?"},{"s":"Elif","en":"Non, je veux faire un dessin.","tr":"Hayır, ben resim yapmak istiyorum."},{"s":"Léa","en":"Super idée ! Je dessine un chat.","tr":"Süper fikir! Ben bir kedi çiziyorum."},{"s":"Elif","en":"Moi, je dessine un grand soleil.","tr":"Ben büyük bir güneş çiziyorum."},{"s":"Léa","en":"Il est beau, ton dessin !","tr":"Resmin çok güzel!"}]},{"title":"Tu veux être mon ami ?","setting":"Okulda yeni gelen Can, Léa ve Hugo ile tanışıyor.","lines":[{"s":"Can","en":"Bonjour ! Je m'appelle Can.","tr":"Merhaba! Benim adım Can."},{"s":"Hugo","en":"Salut Can ! Moi, c'est Hugo.","tr":"Selam Can! Ben Hugo."},{"s":"Léa","en":"Et moi, je suis Léa. Tu es nouveau ?","tr":"Ben de Léa. Yeni misin?"},{"s":"Can","en":"Oui. Je n'ai pas d'ami ici.","tr":"Evet. Burada arkadaşım yok."},{"s":"Hugo","en":"Maintenant, tu as deux amis !","tr":"Artık iki arkadaşın var!"},{"s":"Can","en":"Merci ! Vous êtes super gentils.","tr":"Teşekkürler! Çok naziksiniz."}]}],"reading":{"title":"Mon meilleur ami","paras":[{"en":"Mon meilleur ami s'appelle Hugo. Il a sept ans. Il est gentil et très drôle. Il rit tout le temps ! Nous jouons au ballon dans le parc. Nous faisons aussi des dessins. Quand je suis triste, Hugo est là. Je suis contente d'avoir un ami comme lui.","tr":"En iyi arkadaşımın adı Hugo. Yedi yaşında. Uslu ve çok komik. Her zaman gülüyor! Parkta top oynuyoruz. Birlikte resim de yapıyoruz. Üzgün olduğumda Hugo yanımda. Onun gibi bir arkadaşım olduğu için mutluyum."}]},"vocab":[{"w":"l'ami","ipa":"/la.mi/","pos":"🧑‍🤝‍🧑","tr":"arkadaş (erkek)","ex":"Hugo est mon ami.","exTr":"Hugo benim arkadaşım."},{"w":"l'amie","ipa":"/la.mi/","pos":"👭","tr":"arkadaş (kız)","ex":"Elif est ma meilleure amie.","exTr":"Elif benim en iyi arkadaşım."},{"w":"le ballon","ipa":"/lə ba.lɔ̃/","pos":"⚽","tr":"top","ex":"Nous jouons au ballon.","exTr":"Top oynuyoruz."},{"w":"le parc","ipa":"/lə paʁk/","pos":"🌳","tr":"park","ex":"Nous jouons dans le parc.","exTr":"Parkta oynuyoruz."},{"w":"le dessin","ipa":"/lə de.sɛ̃/","pos":"🖍️","tr":"resim","ex":"Il est beau, ton dessin !","exTr":"Resmin çok güzel!"},{"w":"jouer","ipa":"/ʒwe/","pos":"🎲","tr":"oynamak","ex":"On joue ensemble ?","exTr":"Birlikte oynayalım mı?"},{"w":"drôle","ipa":"/dʁol/","pos":"😄","tr":"komik","ex":"Il est très drôle.","exTr":"O çok komik."},{"w":"gentil","ipa":"/ʒɑ̃.ti/","pos":"😊","tr":"uslu, nazik","ex":"Il est gentil.","exTr":"O nazik."}],"chunks":[{"en":"C'est mon meilleur ami.","tr":"O benim en iyi arkadaşım."},{"en":"On joue ensemble ?","tr":"Birlikte oynayalım mı?"},{"en":"Tu es super gentil !","tr":"Çok naziksin!"},{"en":"Moi aussi !","tr":"Ben de!"}],"grammar":{"point":"Il est… / Elle est…","tr":"Bir arkadaşı anlatırken erkek için 'Il est gentil', kız için 'Elle est gentille' deriz. Kız için sıfatın sonuna genelde bir 'e' eklenir. 'Drôle' zaten 'e' ile bittiği için aynı kalır: 'Il est drôle', 'Elle est drôle'.","examples":["Il est gentil.","Elle est gentille.","Il est drôle.","Elle est drôle."]},"questions":[{"q":"Comment est Hugo ?","a":"Il est gentil et très drôle."},{"q":"À quoi Léa et Hugo jouent-ils dans le parc ?","a":"Ils jouent au ballon."},{"q":"Qu'est-ce qu'Elif veut faire ?","a":"Elle veut faire un dessin."}],"quiz":[{"q":"⚽ = ?","o":["le parc","le dessin","le ballon"],"a":2,"why":""},{"q":"Elif est ma meilleure ___.","o":["amie","ami","ballon"],"a":0,"why":"Kız arkadaş için 'amie' denir."},{"q":"Hugo est…","o":["gentille","gentil","petite"],"a":1,"why":"Hugo erkek, bu yüzden 'gentil'."},{"q":"« On joue ensemble ? » veut dire…","o":["Birlikte uyuyalım mı?","Birlikte oynayalım mı?","Birlikte yiyelim mi?"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Il est gentil.","cue":"drôle","answer":"Il est drôle."},{"type":"Dönüştürme","prompt":"Il est gentil.","cue":"Elle","answer":"Elle est gentille."},{"type":"Soru yap","prompt":"On joue ensemble.","cue":"On…?","answer":"On joue ensemble ?"}],"sounds":[{"focus":"/ɔ̃/","tr":"'Ballon' ve 'on' içindeki burun sesi Türkçede yoktur. Dudaklarını yuvarla, 'o' de ve havayı burnundan da geçir. Sondaki 'n' harfini ayrıca söyleme: 'ballon', 'on', 'bonjour'.","pairs":["ballon / balle","on / eau","bon / beau"]}],"mission":{"brief":"Oyun: Yeni arkadaş! Claude, okula yeni gelen Can olacak. Can'la tanış, ona nasıl biri olduğunu ve neyi sevdiğini Fransızca sor ve onu oyuna davet et.","persona":"Can, a shy 7-year-old Turkish boy who is new at a French school and speaks simple French. Speaks very short sentences and asks one question at a time. Hidden fact: Can loves football and has a secret ball in his bag, but he only says this if the child asks what he likes to play.","goal":"Can'a adını ve ne oynamak istediğini sor, sonra onu oyuna davet et.","opener":"Bonjour ! Je m'appelle Can. Je suis nouveau. Tu es mon ami ?"}},"FK1-031":{"objectives":["Deniz hayvanlarının adlarını Fransızca söylemek","'Il y a…' ile resimde ne olduğunu anlatmak","Kısa bir deniz hikâyesini Fransızca anlamak"],"dialogues":[{"title":"Le livre de Léa","setting":"Léa ve Tom, deniz hayvanlarının olduğu bir hikâye kitabına bakıyor.","lines":[{"s":"Léa","en":"Regarde, Tom ! Il y a un poisson.","tr":"Bak Tom! Bir balık var."},{"s":"Tom","en":"Il est bleu !","tr":"Mavi!"},{"s":"Léa","en":"Oui ! Et il y a un crabe.","tr":"Evet! Bir de yengeç var."},{"s":"Tom","en":"Où est le crabe ?","tr":"Yengeç nerede?"},{"s":"Léa","en":"Là, dans la mer !","tr":"Şurada, denizde!"},{"s":"Tom","en":"J'aime ce livre !","tr":"Bu kitabı seviyorum!"}]},{"title":"Sur le bateau","setting":"Léa ve Papa küçük bir teknede ve denize bakıyorlar.","lines":[{"s":"Papa","en":"Qu'est-ce qu'il y a dans la mer, Léa ?","tr":"Denizde ne var Léa?"},{"s":"Léa","en":"Il y a un dauphin !","tr":"Bir yunus var!"},{"s":"Papa","en":"Super ! Il est grand ?","tr":"Harika! Büyük mü?"},{"s":"Léa","en":"Oui, il est très grand.","tr":"Evet, çok büyük."},{"s":"Papa","en":"Et là, une tortue.","tr":"Bir de şurada bir kaplumbağa."},{"s":"Léa","en":"Bonjour, madame la tortue !","tr":"Merhaba, bayan kaplumbağa!"}]},{"title":"L'histoire d'Elif","setting":"Elif sınıfta arkadaşlarına bir hikâye anlatıyor.","lines":[{"s":"Elif","en":"Il y a une pieuvre sous le bateau.","tr":"Teknenin altında bir ahtapot var."},{"s":"Hugo","en":"Elle a un coquillage ?","tr":"Elinde bir deniz kabuğu var mı?"},{"s":"Elif","en":"Oui, elle a un coquillage rose.","tr":"Evet, pembe bir deniz kabuğu var."},{"s":"Hugo","en":"Et le poisson ?","tr":"Peki ya balık?"},{"s":"Elif","en":"Il est content !","tr":"O mutlu!"},{"s":"Madame Martin","en":"Bravo, Elif ! Quelle belle histoire !","tr":"Aferin Elif! Ne güzel bir hikâye!"}]}],"reading":{"title":"Nino le poisson","paras":[{"en":"Voici l'histoire de Nino, le petit poisson. Nino habite dans la mer. Il y a un crabe rouge et une tortue verte. Un dauphin bleu dit : « Bonjour, Nino ! » Nino voit un bateau. Il y a une pieuvre sous le bateau. Elle a un coquillage. Nino est content. Il dit : « J'aime la mer ! »","tr":"İşte küçük balık Nino'nun hikâyesi. Nino denizde yaşıyor. Kırmızı bir yengeç ve yeşil bir kaplumbağa var. Mavi bir yunus şöyle diyor: «Merhaba Nino!» Nino bir tekne görüyor. Teknenin altında bir ahtapot var. Ahtapotun bir deniz kabuğu var. Nino mutlu. «Denizi seviyorum!» diyor."}]},"vocab":[{"w":"le poisson","ipa":"/lə pwa.sɔ̃/","pos":"🐟","tr":"balık","ex":"Le poisson est bleu.","exTr":"Balık mavi."},{"w":"la mer","ipa":"/la mɛʁ/","pos":"🌊","tr":"deniz","ex":"Nino habite dans la mer.","exTr":"Nino denizde yaşıyor."},{"w":"le crabe","ipa":"/lə kʁab/","pos":"🦀","tr":"yengeç","ex":"Il y a un crabe rouge.","exTr":"Kırmızı bir yengeç var."},{"w":"la tortue","ipa":"/la tɔʁ.ty/","pos":"🐢","tr":"kaplumbağa","ex":"La tortue est verte.","exTr":"Kaplumbağa yeşil."},{"w":"le dauphin","ipa":"/lə do.fɛ̃/","pos":"🐬","tr":"yunus","ex":"Le dauphin est grand.","exTr":"Yunus büyük."},{"w":"la pieuvre","ipa":"/la pjœvʁ/","pos":"🐙","tr":"ahtapot","ex":"La pieuvre a un coquillage.","exTr":"Ahtapotun bir deniz kabuğu var."},{"w":"le coquillage","ipa":"/lə kɔ.ki.jaʒ/","pos":"🐚","tr":"deniz kabuğu","ex":"Elle a un coquillage rose.","exTr":"Pembe bir deniz kabuğu var."},{"w":"le bateau","ipa":"/lə ba.to/","pos":"⛵","tr":"tekne","ex":"Il y a une pieuvre sous le bateau.","exTr":"Teknenin altında bir ahtapot var."}],"chunks":[{"en":"Il y a un poisson.","tr":"Bir balık var."},{"en":"Regarde !","tr":"Bak!"},{"en":"Où est le crabe ?","tr":"Yengeç nerede?"},{"en":"J'aime la mer !","tr":"Denizi seviyorum!"}],"grammar":{"point":"Il y a…","tr":"Bir şeyin orada olduğunu söylerken «Il y a» deriz. «Il y a un poisson» yani «Bir balık var». Erkek şeylerle «un», dişi şeylerle «une» kullanırız.","examples":["Il y a un crabe.","Il y a une tortue.","Il y a un bateau.","Il y a une pieuvre."]},"questions":[{"q":"Qu'est-ce qu'il y a sous le bateau ?","a":"Il y a une pieuvre."},{"q":"Comment est le dauphin ?","a":"Il est bleu."},{"q":"Où habite Nino ?","a":"Il habite dans la mer."}],"quiz":[{"q":"🦀 c'est…","o":["le crabe","le dauphin","la tortue"],"a":0,"why":""},{"q":"Il y a ___ tortue.","o":["un","une","le"],"a":1,"why":"Tortue dişil olduğu için «une» kullanılır."},{"q":"🐬 c'est…","o":["la pieuvre","le poisson","le dauphin"],"a":2,"why":""},{"q":"Nino habite dans…","o":["le bateau","la mer","le livre"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Il y a un crabe.","cue":"poisson","answer":"Il y a un poisson."},{"type":"Yerine koyma","prompt":"Il y a une tortue.","cue":"pieuvre","answer":"Il y a une pieuvre."},{"type":"Soru yap","prompt":"Le crabe est là.","cue":"Où…?","answer":"Où est le crabe ?"}],"sounds":[{"focus":"/ɔ̃/","tr":"Fransızcada «on» sesi burun sesidir. «n» harfini söylemeden, dudaklarını yuvarlayıp sesi burnundan geçir: «poisson», «bon». Türkçedeki «on» gibi sonunda n sesi çıkmaz.","pairs":["poisson / ballon","mon / son","bon / bonbon"]}],"mission":{"brief":"Oyun: Deniz hikâyesi! Claude, arkadaşın Léa olacak. Resimdeki deniz hayvanlarını «Il y a…» ile anlat ve Léa'ya sorular sor.","persona":"Léa, a cheerful 7-year-old French girl. Speaks very simple French, short sentences, one question at a time. Hidden fact: her favourite sea animal is the octopus (la pieuvre), but she only says so if the child asks « Quel est ton animal préféré ? ».","goal":"«Il y a…» ile en az üç deniz hayvanı söyle.","opener":"Salut ! Je suis Léa. Regarde mon livre. Qu'est-ce qu'il y a dans la mer ?"}},"FK1-032":{"objectives":["Masal kahramanlarının adlarını Fransızca söylemek","«Il est… / Elle est…» ile birini tarif etmek","«Il était une fois…» ile bir masala başlamak"],"dialogues":[{"title":"Le soir avec Mamie","setting":"Mamie akşam Léa ve Tom'a masal okuyor.","lines":[{"s":"Mamie","en":"Il était une fois un roi.","tr":"Bir zamanlar bir kral varmış."},{"s":"Tom","en":"Il est grand ?","tr":"Uzun boylu mu?"},{"s":"Mamie","en":"Oui, il est très grand.","tr":"Evet, çok uzun boylu."},{"s":"Léa","en":"Et la reine ? Elle est où ?","tr":"Peki kraliçe? O nerede?"},{"s":"Mamie","en":"Elle est dans le château.","tr":"Şatoda."},{"s":"Tom","en":"Un château ! Super !","tr":"Bir şato! Harika!"}]},{"title":"Dans la forêt","setting":"Léa ve Hugo oyunda masal kahramanlarını oynuyor.","lines":[{"s":"Hugo","en":"Je suis le chevalier.","tr":"Ben şövalyeyim."},{"s":"Léa","en":"Moi, je suis la princesse.","tr":"Ben de prensesim."},{"s":"Hugo","en":"Attention ! Il y a un dragon !","tr":"Dikkat! Bir ejderha var!"},{"s":"Léa","en":"Il est méchant ?","tr":"Kötü mü?"},{"s":"Hugo","en":"Non, il est gentil !","tr":"Hayır, iyi biri!"},{"s":"Léa","en":"Bonjour, monsieur le dragon !","tr":"Merhaba, bay ejderha!"}]},{"title":"La fée de Can","setting":"Can sınıfta kendi masalını anlatıyor.","lines":[{"s":"Can","en":"Il était une fois une fée.","tr":"Bir zamanlar bir peri varmış."},{"s":"Madame Martin","en":"Comment est la fée, Can ?","tr":"Peri nasıl, Can?"},{"s":"Can","en":"Elle est petite et jolie.","tr":"Küçük ve güzel."},{"s":"Madame Martin","en":"Elle habite où ?","tr":"Nerede yaşıyor?"},{"s":"Can","en":"Elle habite dans la forêt.","tr":"Ormanda yaşıyor."},{"s":"Madame Martin","en":"Très bien, Can !","tr":"Çok güzel, Can!"}]}],"reading":{"title":"La princesse et le dragon","paras":[{"en":"Il était une fois une princesse. Elle est petite et jolie. Elle habite dans un grand château. Dans la forêt, il y a un dragon. Il est vert et gentil. Un jour, le roi et la reine cherchent la princesse. Elle est dans la forêt avec le dragon ! Ils sont très contents.","tr":"Bir zamanlar bir prenses varmış. Küçük ve güzelmiş. Büyük bir şatoda yaşıyormuş. Ormanda bir ejderha var. Yeşil ve iyi biri. Bir gün kral ve kraliçe prensesi arıyor. O, ormanda ejderhayla birlikte! Çok mutlular."}]},"vocab":[{"w":"le roi","ipa":"/lə ʁwa/","pos":"🤴","tr":"kral","ex":"Le roi est grand.","exTr":"Kral uzun boylu."},{"w":"la reine","ipa":"/la ʁɛn/","pos":"👸","tr":"kraliçe","ex":"La reine est dans le château.","exTr":"Kraliçe şatoda."},{"w":"la princesse","ipa":"/la pʁɛ̃.sɛs/","pos":"👑","tr":"prenses","ex":"La princesse est petite et jolie.","exTr":"Prenses küçük ve güzel."},{"w":"le dragon","ipa":"/lə dʁa.ɡɔ̃/","pos":"🐉","tr":"ejderha","ex":"Le dragon est gentil.","exTr":"Ejderha iyi biri."},{"w":"le château","ipa":"/lə ʃa.to/","pos":"🏰","tr":"şato","ex":"Elle habite dans un grand château.","exTr":"Büyük bir şatoda yaşıyor."},{"w":"la fée","ipa":"/la fe/","pos":"🧚","tr":"peri","ex":"La fée est petite.","exTr":"Peri küçük."},{"w":"la forêt","ipa":"/la fɔ.ʁɛ/","pos":"🌲","tr":"orman","ex":"Il y a un dragon dans la forêt.","exTr":"Ormanda bir ejderha var."},{"w":"le chevalier","ipa":"/lə ʃə.va.lje/","pos":"🛡️","tr":"şövalye","ex":"Je suis le chevalier.","exTr":"Ben şövalyeyim."}],"chunks":[{"en":"Il était une fois…","tr":"Bir zamanlar…"},{"en":"Il est gentil.","tr":"O iyi biri."},{"en":"Elle est jolie.","tr":"O güzel."},{"en":"Super !","tr":"Harika!"}],"grammar":{"point":"Il est… / Elle est…","tr":"Bir erkeği ya da erkek bir şeyi tarif ederken «Il est», bir kadını ya da dişil bir şeyi tarif ederken «Elle est» deriz. «Il est grand» ama «Elle est grande». Dişil sözcüklerde sıfatın sonuna çoğu zaman bir «e» eklenir.","examples":["Il est grand.","Elle est petite.","Il est gentil.","Elle est jolie."]},"questions":[{"q":"Comment est la princesse ?","a":"Elle est petite et jolie."},{"q":"Où habite la princesse ?","a":"Elle habite dans un grand château."},{"q":"De quelle couleur est le dragon ?","a":"Il est vert."}],"quiz":[{"q":"Le dragon est…","o":["petite","gentil","jolie"],"a":1,"why":"Ejderha eril olduğu için «gentil» kullanılır."},{"q":"🏰 c'est…","o":["la forêt","la fée","le château"],"a":2,"why":""},{"q":"___ est petite.","o":["Il","Elle","Je"],"a":1,"why":"Dişil biri için «elle» kullanılır."},{"q":"Qui est dans la forêt ?","o":["le dragon","le roi","la reine"],"a":0,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Il est grand.","cue":"petite","answer":"Elle est petite."},{"type":"Dönüştürme","prompt":"Il est gentil.","cue":"elle","answer":"Elle est gentille."},{"type":"Soru yap","prompt":"Elle habite dans la forêt.","cue":"Où…?","answer":"Elle habite où ?"}],"sounds":[{"focus":"/y/","tr":"Fransızca «u» harfi Türkçedeki «ü» gibi okunur: dudaklarını «u» der gibi yuvarla, ama dilini «i» der gibi öne koy. «tu», «lune». Fransızca «ou» ise Türkçedeki «u» gibidir: «tout», «loup».","pairs":["tu / tout","rue / roue","lune / loup"]}],"mission":{"brief":"Oyun: Masal zamanı! Claude, büyükanne Mamie olacak. Mamie'ye masaldaki kahramanları sor ve «Il est… / Elle est…» ile tarif et.","persona":"Mamie, a kind French grandmother who tells simple fairy tales to a 7-year-old. Very short sentences, asks one question at a time. Hidden fact: the dragon in her story is called Pompon and he loves cakes, but she only tells this if the child asks « Comment s'appelle le dragon ? ».","goal":"En az iki kahramanı «Il est… / Elle est…» ile tarif et.","opener":"Bonsoir, ma puce ! Il était une fois un dragon dans une forêt. Il est comment, ce dragon ?"}},"FK1-033":{"objectives":["Hayvanat bahçesindeki hayvanların adlarını Fransızca söylemek","«Je vois…» ile gördüğün hayvanı söylemek","Hayvanların rengini ve büyüklüğünü basitçe tarif etmek"],"dialogues":[{"title":"À l'entrée du zoo","setting":"Léa, Tom ve Maman hayvanat bahçesine yeni girdiler.","lines":[{"s":"Tom","en":"Maman, je vois un éléphant !","tr":"Anne, bir fil görüyorum!"},{"s":"Maman","en":"Oui, il est très grand.","tr":"Evet, çok büyük."},{"s":"Léa","en":"Moi, je vois une girafe.","tr":"Ben de bir zürafa görüyorum."},{"s":"Tom","en":"Elle est grande !","tr":"Çok uzun!"},{"s":"Maman","en":"Regardez, les enfants !","tr":"Bakın çocuklar!"},{"s":"Léa","en":"Oh là là, c'est super !","tr":"Vay canına, harika!"}]},{"title":"Chez les singes","setting":"Léa ve arkadaşı Elif maymunların önünde duruyor.","lines":[{"s":"Elif","en":"Regarde le singe !","tr":"Maymuna bak!"},{"s":"Léa","en":"Il mange une banane.","tr":"Muz yiyor."},{"s":"Elif","en":"Il est drôle !","tr":"Çok komik!"},{"s":"Léa","en":"Et là, je vois un lion.","tr":"Şurada da bir aslan görüyorum."},{"s":"Elif","en":"Il est grand et jaune.","tr":"Büyük ve sarı."},{"s":"Léa","en":"J'ai un peu peur !","tr":"Biraz korkuyorum!"}]},{"title":"Le zèbre et l'ours","setting":"Hugo ve Papa hayvanat bahçesinde dolaşıyor.","lines":[{"s":"Hugo","en":"Papa, qu'est-ce que c'est ?","tr":"Baba, bu ne?"},{"s":"Papa","en":"C'est un zèbre.","tr":"Bu bir zebra."},{"s":"Hugo","en":"Il est noir et blanc !","tr":"Siyah beyaz!"},{"s":"Papa","en":"Oui. Et là, c'est un ours.","tr":"Evet. Şurada da bir ayı var."},{"s":"Hugo","en":"Il est brun et gros.","tr":"Kahverengi ve iri."},{"s":"Papa","en":"Tu aimes le zoo, Hugo ?","tr":"Hayvanat bahçesini seviyor musun Hugo?"},{"s":"Hugo","en":"Oui, j'adore !","tr":"Evet, bayılıyorum!"}]}],"reading":{"title":"Une visite au zoo","paras":[{"en":"Aujourd'hui, Léa et Tom sont au zoo. Léa voit une girafe. Elle est très grande. Tom voit un éléphant. Il est gris et grand. Il y a aussi un singe. Il mange une banane ! Léa rit. Tom dit : « Je n'ai pas peur ! » Ils sont contents. Le zoo, c'est super !","tr":"Bugün Léa ve Tom hayvanat bahçesinde. Léa bir zürafa görüyor. Zürafa çok uzun. Tom bir fil görüyor. Fil gri ve büyük. Bir de maymun var. Maymun muz yiyor! Léa gülüyor. Tom şöyle diyor: «Korkmuyorum!» İkisi de mutlu. Hayvanat bahçesi harika!"}]},"vocab":[{"w":"l'éléphant","ipa":"/le.le.fɑ̃/","pos":"🐘","tr":"fil","ex":"L'éléphant est gris.","exTr":"Fil gri."},{"w":"le singe","ipa":"/lə sɛ̃ʒ/","pos":"🐒","tr":"maymun","ex":"Le singe mange une banane.","exTr":"Maymun muz yiyor."},{"w":"le lion","ipa":"/lə ljɔ̃/","pos":"🦁","tr":"aslan","ex":"Le lion est grand et jaune.","exTr":"Aslan büyük ve sarı."},{"w":"la girafe","ipa":"/la ʒi.ʁaf/","pos":"🦒","tr":"zürafa","ex":"La girafe est grande.","exTr":"Zürafa uzun boylu."},{"w":"le zèbre","ipa":"/lə zɛbʁ/","pos":"🦓","tr":"zebra","ex":"Le zèbre est noir et blanc.","exTr":"Zebra siyah beyaz."},{"w":"l'ours","ipa":"/luʁs/","pos":"🐻","tr":"ayı","ex":"L'ours est brun et gros.","exTr":"Ayı kahverengi ve iri."},{"w":"le zoo","ipa":"/lə zo.o/","pos":"🎟️","tr":"hayvanat bahçesi","ex":"J'aime le zoo !","exTr":"Hayvanat bahçesini seviyorum!"},{"w":"la banane","ipa":"/la ba.nan/","pos":"🍌","tr":"muz","ex":"Le singe mange une banane.","exTr":"Maymun muz yiyor."}],"chunks":[{"en":"Je vois un lion.","tr":"Bir aslan görüyorum."},{"en":"Qu'est-ce que c'est ?","tr":"Bu ne?"},{"en":"C'est un zèbre.","tr":"Bu bir zebra."},{"en":"J'ai peur !","tr":"Korkuyorum!"}],"grammar":{"point":"Je vois…","tr":"Gördüğün şeyi söylerken «Je vois» deriz. «Je vois un lion» yani «Bir aslan görüyorum». Erkek hayvanlarla «un», dişi hayvanlarla «une» kullanırız. Ünlüyle başlayan sözcüklerde «le» ve «la» «l'» olur: «l'éléphant».","examples":["Je vois un lion.","Je vois une girafe.","Je vois un singe.","Je vois l'éléphant."]},"questions":[{"q":"Qu'est-ce que Léa voit ?","a":"Elle voit une girafe."},{"q":"De quelle couleur est l'éléphant ?","a":"Il est gris."},{"q":"Que mange le singe ?","a":"Il mange une banane."}],"quiz":[{"q":"🦒 c'est…","o":["la girafe","le zèbre","l'ours"],"a":0,"why":""},{"q":"Je ___ un lion.","o":["voit","vois","ai"],"a":1,"why":"«Je» ile «vois» kullanılır."},{"q":"L'éléphant est…","o":["jaune","gris","rose"],"a":1,"why":""},{"q":"Le zèbre est…","o":["brun","vert","noir et blanc"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Je vois un lion.","cue":"singe","answer":"Je vois un singe."},{"type":"Yerine koyma","prompt":"Je vois une girafe.","cue":"éléphant","answer":"Je vois un éléphant."},{"type":"Soru yap","prompt":"C'est un zèbre.","cue":"Qu'est-ce que…?","answer":"Qu'est-ce que c'est ?"}],"sounds":[{"focus":"/ʁ/","tr":"Fransızca «r» Türkçedeki «r» gibi dil ucuyla çıkmaz. Dilin ucu alt dişlerinde kalır, boğazının arkasından hafifçe gargara yapar gibi çıkar: «girafe», «zèbre», «ours». Türkçedeki «h»ye yakın, hafif hırıltılı bir ses düşün.","pairs":["riz / lit","rue / lu","roue / loup"]}],"mission":{"brief":"Oyun: Hayvanat bahçesi gezisi! Claude, arkadaşın Hugo olacak. Gördüğün hayvanları «Je vois…» ile söyle ve Hugo'ya ne gördüğünü sor.","persona":"Hugo, a cheerful 7-year-old French boy visiting the zoo. Very short, simple sentences, one question at a time. Hidden fact: Hugo is a little afraid of the lion, but he only says so if the child asks « Tu as peur du lion ? ».","goal":"«Je vois…» ile en az üç hayvan söyle.","opener":"Salut ! Je suis Hugo. Nous sommes au zoo ! Moi, je vois un éléphant. Et toi, qu'est-ce que tu vois ?"}},"FK1-034":{"objectives":["Bahçedeki bitki ve böceklerin adlarını Fransızca söylemek","«le / la / les» sözcüklerini doğru kullanmak","Bahçede gördüklerini kısaca anlatmak"],"dialogues":[{"title":"Dans le jardin de Mamie","setting":"Léa ve Tom, Mamie'nin bahçesinde oynuyor.","lines":[{"s":"Léa","en":"Mamie, regarde les fleurs !","tr":"Mamie, çiçeklere bak!"},{"s":"Mamie","en":"Elles sont belles, non ?","tr":"Güzeller, değil mi?"},{"s":"Tom","en":"La fleur rouge est pour moi !","tr":"Kırmızı çiçek benim için!"},{"s":"Mamie","en":"Oui, Tom. Et l'arbre est très grand.","tr":"Evet Tom. Ağaç da çok büyük."},{"s":"Léa","en":"Il y a des pommes dans l'arbre ?","tr":"Ağaçta elmalar var mı?"},{"s":"Mamie","en":"Pas encore, ma puce.","tr":"Henüz yok, tatlım."}]},{"title":"Les petits animaux","setting":"Léa ve Hugo bahçede küçük hayvanları arıyor.","lines":[{"s":"Hugo","en":"Regarde le papillon !","tr":"Kelebeğe bak!"},{"s":"Léa","en":"Il est jaune et bleu.","tr":"Sarı ve mavi."},{"s":"Hugo","en":"Et l'abeille ? Elle est où ?","tr":"Peki arı? Nerede?"},{"s":"Léa","en":"Elle est sur la fleur.","tr":"Çiçeğin üstünde."},{"s":"Hugo","en":"Oh, un escargot dans l'herbe !","tr":"Ah, çimenlerde bir salyangoz!"},{"s":"Léa","en":"Il est petit et lent !","tr":"Küçük ve yavaş!"}]},{"title":"Il fait beau","setting":"Papa ve Elif bahçede güneşli bir günün tadını çıkarıyor.","lines":[{"s":"Papa","en":"Le soleil est chaud aujourd'hui.","tr":"Güneş bugün sıcak."},{"s":"Elif","en":"J'aime le jardin, Papa.","tr":"Bahçeyi seviyorum Baba."},{"s":"Papa","en":"Moi aussi. Tu vois les arbres ?","tr":"Ben de. Ağaçları görüyor musun?"},{"s":"Elif","en":"Oui, je vois deux arbres.","tr":"Evet, iki ağaç görüyorum."},{"s":"Papa","en":"Et dans l'herbe ?","tr":"Peki çimenlerde?"},{"s":"Elif","en":"Je vois un escargot !","tr":"Bir salyangoz görüyorum!"}]}],"reading":{"title":"Le jardin de Mamie","paras":[{"en":"Le jardin de Mamie est très joli. Il y a des fleurs rouges, roses et jaunes. Il y a un grand arbre. Un papillon vole sur les fleurs. Une abeille est aussi là. Dans l'herbe, il y a un petit escargot. Léa aime le jardin. Tom aime les fleurs. Le soleil est chaud. C'est un beau jour !","tr":"Mamie'nin bahçesi çok güzel. Kırmızı, pembe ve sarı çiçekler var. Büyük bir ağaç var. Çiçeklerin üstünde bir kelebek uçuyor. Bir de arı var. Çimenlerde küçük bir salyangoz var. Léa bahçeyi seviyor. Tom çiçekleri seviyor. Güneş sıcak. Ne güzel bir gün!"}]},"vocab":[{"w":"la fleur","ipa":"/la flœʁ/","pos":"🌸","tr":"çiçek","ex":"La fleur est rouge.","exTr":"Çiçek kırmızı."},{"w":"l'arbre","ipa":"/laʁbʁ/","pos":"🌳","tr":"ağaç","ex":"L'arbre est très grand.","exTr":"Ağaç çok büyük."},{"w":"l'herbe","ipa":"/lɛʁb/","pos":"🌿","tr":"çimen, ot","ex":"Il y a un escargot dans l'herbe.","exTr":"Çimenlerde bir salyangoz var."},{"w":"le papillon","ipa":"/lə pa.pi.jɔ̃/","pos":"🦋","tr":"kelebek","ex":"Le papillon est jaune et bleu.","exTr":"Kelebek sarı ve mavi."},{"w":"l'abeille","ipa":"/la.bɛj/","pos":"🐝","tr":"arı","ex":"L'abeille est sur la fleur.","exTr":"Arı çiçeğin üstünde."},{"w":"l'escargot","ipa":"/lɛs.kaʁ.ɡo/","pos":"🐌","tr":"salyangoz","ex":"L'escargot est petit.","exTr":"Salyangoz küçük."},{"w":"le soleil","ipa":"/lə sɔ.lɛj/","pos":"☀️","tr":"güneş","ex":"Le soleil est chaud.","exTr":"Güneş sıcak."},{"w":"le jardin","ipa":"/lə ʒaʁ.dɛ̃/","pos":"🏡","tr":"bahçe","ex":"J'aime le jardin.","exTr":"Bahçeyi seviyorum."}],"chunks":[{"en":"Regarde la fleur !","tr":"Çiçeğe bak!"},{"en":"J'aime le jardin.","tr":"Bahçeyi seviyorum."},{"en":"Il est où ?","tr":"O nerede?"},{"en":"C'est joli !","tr":"Ne güzel!"}],"grammar":{"point":"Le / la / les","tr":"Fransızcada «the» yerine eril sözcüklerde «le», dişil sözcüklerde «la» deriz: «le jardin», «la fleur». Birden fazla şey varsa «les» kullanırız: «les fleurs». Ünlüyle başlayan sözcüklerde «l'» deriz: «l'arbre».","examples":["Le papillon est jaune.","La fleur est rose.","Les fleurs sont belles.","L'arbre est grand."]},"questions":[{"q":"Qu'est-ce qu'il y a dans l'herbe ?","a":"Il y a un escargot."},{"q":"De quelle couleur sont les fleurs ?","a":"Elles sont rouges, roses et jaunes."},{"q":"Qui aime les fleurs ?","a":"Tom aime les fleurs."}],"quiz":[{"q":"___ fleur est rose.","o":["Le","La","Les"],"a":1,"why":"Fleur dişil ve tek olduğu için «la» kullanılır."},{"q":"🦋 c'est…","o":["l'abeille","l'escargot","le papillon"],"a":2,"why":""},{"q":"___ arbre est grand.","o":["L'","La","Les"],"a":0,"why":"Ünlüyle başlayan sözcükte «l'» kullanılır."},{"q":"Il y a trois…","o":["fleurs","fleur","arbre"],"a":0,"why":"Üç tane olduğu için çoğul kullanılır."}],"drills":[{"type":"Yerine koyma","prompt":"La fleur est rose.","cue":"arbre / grand","answer":"L'arbre est grand."},{"type":"Dönüştürme","prompt":"La fleur est jolie.","cue":"plusieurs","answer":"Les fleurs sont jolies."},{"type":"Genişletme","prompt":"Le papillon est là.","cue":"jaune","answer":"Le papillon jaune est là."}],"sounds":[{"focus":"liaison","tr":"Fransızcada «s» harfi sözcük sonunda genelde okunmaz. Ama arkasından ünlüyle başlayan bir sözcük gelirse «z» gibi okunur ve sözcüklere bağlanır: «les arbres» /le zaʁbʁ/. Buna liaison denir.","pairs":["les arbres / les fleurs","un arbre / un jardin"]}],"mission":{"brief":"Oyun: Bahçe keşfi! Claude, arkadaşın Léa olacak. Bahçede gördüğün şeyleri «le / la / les» ile söyle ve Léa'ya ne gördüğünü sor.","persona":"Léa, a cheerful 7-year-old French girl in her grandmother's garden. Very short, simple sentences, one question at a time. Hidden fact: Léa has a secret favourite, the little snail called Gaston, but she only says so if the child asks « Quel est ton animal préféré dans le jardin ? ».","goal":"«le / la / les» ile en az üç şeyi söyle.","opener":"Salut ! Je suis Léa. Je suis dans le jardin de Mamie. Il y a des fleurs. Et toi, qu'est-ce que tu vois ?"}},"FK1-035":{"objectives":["Fırında satılan şeylerin adlarını Fransızca söylemek","«Je voudrais…» ile nazikçe bir şey istemek","«Combien ça coûte ?» sorusunu anlamak ve fiyatı söylemek"],"dialogues":[{"title":"Une baguette, s'il vous plaît","setting":"Léa ve Papa sabah fırına ekmek almaya geliyor.","lines":[{"s":"Boulangère","en":"Bonjour, mademoiselle !","tr":"Günaydın küçük hanım!"},{"s":"Léa","en":"Bonjour, madame ! Je voudrais une baguette, s'il vous plaît.","tr":"Günaydın hanımefendi! Bir baget istiyorum lütfen."},{"s":"Boulangère","en":"Voilà !","tr":"Buyurun!"},{"s":"Papa","en":"Et un pain, s'il vous plaît.","tr":"Bir de ekmek lütfen."},{"s":"Boulangère","en":"Ça fait deux euros.","tr":"İki euro tutuyor."},{"s":"Léa","en":"Merci, madame ! Au revoir !","tr":"Teşekkürler hanımefendi! Hoşça kalın!"}]},{"title":"Le goûter de Tom","setting":"Tom ve Maman çay saati için tatlı seçiyor.","lines":[{"s":"Tom","en":"Maman, je voudrais un croissant.","tr":"Anne, bir kruvasan istiyorum."},{"s":"Maman","en":"D'accord. Et un biscuit ?","tr":"Tamam. Bir bisküvi de ister misin?"},{"s":"Tom","en":"Oui ! Et un bonbon, s'il te plaît ?","tr":"Evet! Bir de şeker, lütfen?"},{"s":"Maman","en":"Non, pas de bonbon.","tr":"Hayır, şeker yok."},{"s":"Tom","en":"Oh non ! Alors un gâteau !","tr":"Of! O zaman bir pasta!"},{"s":"Maman","en":"Ha ha ! Un petit gâteau, d'accord.","tr":"Ha ha! Küçük bir pasta, tamam."}]},{"title":"L'anniversaire de Hugo","setting":"Elif ve Madame Martin, Hugo'nun doğum günü için fırında pasta alıyor.","lines":[{"s":"Elif","en":"Bonjour ! Je voudrais une tarte.","tr":"Merhaba! Bir tart istiyorum."},{"s":"Boulangère","en":"Une tarte aux pommes ?","tr":"Elmalı tart mı?"},{"s":"Elif","en":"Oui, s'il vous plaît.","tr":"Evet, lütfen."},{"s":"Madame Martin","en":"Et un gâteau pour Hugo.","tr":"Bir de Hugo için pasta."},{"s":"Boulangère","en":"Voilà. Ça fait dix euros.","tr":"Buyurun. On euro tutuyor."},{"s":"Elif","en":"Merci ! Joyeux anniversaire, Hugo !","tr":"Teşekkürler! Doğum günün kutlu olsun Hugo!"}]}],"reading":{"title":"Le matin chez la boulangère","paras":[{"en":"Le matin, Léa va à la boulangerie avec Papa. Il y a du pain, des croissants et des gâteaux. Léa dit : « Bonjour, madame ! Je voudrais une baguette, s'il vous plaît. » La dame sourit. Papa prend aussi un croissant pour Tom. Léa dit : « Merci, madame ! » Elle est très contente.","tr":"Sabah Léa, Babasıyla fırına gidiyor. Orada ekmek, kruvasan ve pastalar var. Léa şöyle diyor: «Günaydın hanımefendi! Bir baget istiyorum lütfen.» Fırıncı hanım gülümsüyor. Babası Tom için bir de kruvasan alıyor. Léa: «Teşekkürler hanımefendi!» diyor. Çok mutlu."}]},"vocab":[{"w":"le pain","ipa":"/lə pɛ̃/","pos":"🍞","tr":"ekmek","ex":"Je voudrais un pain.","exTr":"Bir ekmek istiyorum."},{"w":"la baguette","ipa":"/la ba.ɡɛt/","pos":"🥖","tr":"baget (uzun ekmek)","ex":"Je voudrais une baguette.","exTr":"Bir baget istiyorum."},{"w":"le croissant","ipa":"/lə kʁwa.sɑ̃/","pos":"🥐","tr":"kruvasan","ex":"Tom aime le croissant.","exTr":"Tom kruvasanı seviyor."},{"w":"le gâteau","ipa":"/lə ɡa.to/","pos":"🎂","tr":"pasta, kek","ex":"Un petit gâteau, d'accord.","exTr":"Küçük bir pasta, tamam."},{"w":"la tarte","ipa":"/la taʁt/","pos":"🥧","tr":"tart","ex":"Je voudrais une tarte.","exTr":"Bir tart istiyorum."},{"w":"le biscuit","ipa":"/lə bis.kɥi/","pos":"🍪","tr":"bisküvi","ex":"Et un biscuit ?","exTr":"Bir de bisküvi?"},{"w":"le bonbon","ipa":"/lə bɔ̃.bɔ̃/","pos":"🍬","tr":"şeker","ex":"Pas de bonbon !","exTr":"Şeker yok!"},{"w":"l'euro","ipa":"/lø.ʁo/","pos":"💶","tr":"euro","ex":"Ça fait deux euros.","exTr":"İki euro tutuyor."}],"chunks":[{"en":"Je voudrais une baguette.","tr":"Bir baget istiyorum."},{"en":"S'il vous plaît.","tr":"Lütfen."},{"en":"Voilà !","tr":"Buyurun!"},{"en":"Combien ça coûte ?","tr":"Ne kadar?"}],"grammar":{"point":"Je voudrais…","tr":"Bir şey isterken kibar olmak için «Je voudrais» deriz. «Je voudrais un croissant» yani «Bir kruvasan istiyorum». Sonuna «s'il vous plaît» (lütfen) eklemeyi unutma!","examples":["Je voudrais un pain.","Je voudrais une tarte.","Je voudrais un croissant, s'il vous plaît.","Je voudrais deux biscuits."]},"questions":[{"q":"Qu'est-ce que Léa voudrait ?","a":"Elle voudrait une baguette."},{"q":"Combien ça fait pour le pain et la baguette ?","a":"Ça fait deux euros."},{"q":"Pour qui est le croissant ?","a":"Il est pour Tom."}],"quiz":[{"q":"🥖 c'est…","o":["le gâteau","le bonbon","la baguette"],"a":2,"why":""},{"q":"Je ___ une tarte.","o":["voudrais","vois","suis"],"a":0,"why":"Nazikçe istemek için «je voudrais» kullanılır."},{"q":"Pour dire merci, on dit…","o":["Pardon","Merci","Voilà"],"a":1,"why":""},{"q":"Ça fait deux…","o":["pains","tartes","euros"],"a":2,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Je voudrais un pain.","cue":"croissant","answer":"Je voudrais un croissant."},{"type":"Yerine koyma","prompt":"Je voudrais une baguette.","cue":"tarte","answer":"Je voudrais une tarte."},{"type":"Genişletme","prompt":"Je voudrais un gâteau.","cue":"s'il vous plaît","answer":"Je voudrais un gâteau, s'il vous plaît."}],"sounds":[{"focus":"/ɛ̃/","tr":"Fransızca «pain» sözcüğündeki «ain» burun sesidir. Ağzını «e» der gibi yarı açık tut, sesi burnundan da geçir ve sondaki «n»yi söyleme: «pain», «matin», «jardin». Türkçedeki «en» gibi bitirme!","pairs":["pain / main","matin / jardin","bain / pan"]}],"mission":{"brief":"Oyun: Fırında alışveriş! Claude, fırıncı Madame Dupont olacak. Ondan «Je voudrais…» ile iki şey iste ve fiyatı sor.","persona":"Madame Dupont, a friendly French baker talking to a 7-year-old. Very simple French, short sentences, one question at a time. Hidden fact: today the chocolate croissants are free for children who say « s'il vous plaît », but she only tells this if the child asks « Qu'est-ce qu'il y a de spécial aujourd'hui ? ».","goal":"«Je voudrais…» ile en az iki şey iste.","opener":"Bonjour, mon petit cœur ! Bienvenue à la boulangerie. Qu'est-ce que tu voudrais ?"}},"FK1-036":{"objectives":["Nazik sözcükleri (merci, s'il te plaît, pardon) Fransızca söylemek","Selamlaşıp vedalaşmak (au revoir, à demain, bonne nuit)","«Merci» sözcüğüne «De rien» diye karşılık vermek"],"dialogues":[{"title":"À la sortie de l'école","setting":"Okul çıkışında Léa, Madame Martin'e veda ediyor.","lines":[{"s":"Léa","en":"Au revoir, Madame Martin !","tr":"Hoşça kalın Madame Martin!"},{"s":"Madame Martin","en":"Au revoir, Léa ! À demain !","tr":"Hoşça kal Léa! Yarın görüşürüz!"},{"s":"Léa","en":"À demain, Madame !","tr":"Yarın görüşürüz, öğretmenim!"},{"s":"Hugo","en":"Au revoir, Léa !","tr":"Güle güle Léa!"},{"s":"Léa","en":"Au revoir, Hugo ! À demain !","tr":"Güle güle Hugo! Yarın görüşürüz!"}]},{"title":"À la maison","setting":"Akşam evde Léa, Tom ve Maman sofrada.","lines":[{"s":"Léa","en":"Maman, de l'eau, s'il te plaît.","tr":"Anne, su lütfen."},{"s":"Maman","en":"Voilà, ma puce.","tr":"Buyur, tatlım."},{"s":"Léa","en":"Merci, Maman !","tr":"Teşekkürler Anne!"},{"s":"Maman","en":"De rien. Tom, tu veux du pain ?","tr":"Rica ederim. Tom, ekmek ister misin?"},{"s":"Tom","en":"Oui, s'il te plaît !","tr":"Evet, lütfen!"},{"s":"Tom","en":"Oh, pardon, Léa !","tr":"Ah, pardon Léa!"}]},{"title":"Bonne nuit","setting":"Yatma zamanı. Papa ve Léa iyi geceler diliyor.","lines":[{"s":"Papa","en":"C'est l'heure de dormir, Léa.","tr":"Uyku vakti Léa."},{"s":"Léa","en":"Bonne nuit, Papa !","tr":"İyi geceler Baba!"},{"s":"Papa","en":"Bonne nuit, ma princesse. Fais de beaux rêves.","tr":"İyi geceler prensesim. Güzel rüyalar gör."},{"s":"Léa","en":"Merci, Papa ! Et bonne nuit, Minou !","tr":"Teşekkürler Baba! İyi geceler Minou de!"},{"s":"Papa","en":"Minou dit : miaou !","tr":"Minou diyor ki: miyav!"}]}],"reading":{"title":"Les mots magiques","paras":[{"en":"Léa connaît les mots magiques. Le matin, elle dit : « Bonjour ! » À table, elle dit : « S'il te plaît » et « Merci ». Si elle a un problème, elle dit : « Pardon ». À l'école, elle dit : « Au revoir ! À demain ! » Le soir, elle dit : « Bonne nuit ! » Tout le monde est content.","tr":"Léa sihirli sözcükleri biliyor. Sabahları «Bonjour!» diyor. Sofrada «S'il te plaît» ve «Merci» diyor. Bir hata yaparsa «Pardon» diyor. Okulda «Au revoir! À demain!» diyor. Akşamları «Bonne nuit!» diyor. Herkes mutlu."}]},"vocab":[{"w":"merci","ipa":"/mɛʁ.si/","pos":"🙏","tr":"teşekkürler","ex":"Merci, Maman !","exTr":"Teşekkürler Anne!"},{"w":"s'il te plaît","ipa":"/sil tə plɛ/","pos":"🥺","tr":"lütfen","ex":"De l'eau, s'il te plaît.","exTr":"Su lütfen."},{"w":"pardon","ipa":"/paʁ.dɔ̃/","pos":"😳","tr":"pardon, özür dilerim","ex":"Oh, pardon, Léa !","exTr":"Ah, pardon Léa!"},{"w":"de rien","ipa":"/də ʁjɛ̃/","pos":"😊","tr":"rica ederim","ex":"Merci ! — De rien.","exTr":"Teşekkürler! — Rica ederim."},{"w":"au revoir","ipa":"/o ʁə.vwaʁ/","pos":"👋","tr":"hoşça kal, görüşürüz","ex":"Au revoir, Madame !","exTr":"Hoşça kalın öğretmenim!"},{"w":"à demain","ipa":"/a də.mɛ̃/","pos":"📅","tr":"yarın görüşürüz","ex":"Au revoir ! À demain !","exTr":"Hoşça kal! Yarın görüşürüz!"},{"w":"bonne nuit","ipa":"/bɔn nɥi/","pos":"🌙","tr":"iyi geceler","ex":"Bonne nuit, Papa !","exTr":"İyi geceler Baba!"},{"w":"bonjour","ipa":"/bɔ̃.ʒuʁ/","pos":"☀️","tr":"günaydın, merhaba","ex":"Le matin, elle dit : « Bonjour ! »","exTr":"Sabahları «Bonjour!» diyor."}],"chunks":[{"en":"Merci beaucoup !","tr":"Çok teşekkürler!"},{"en":"De rien.","tr":"Rica ederim."},{"en":"Au revoir, à demain !","tr":"Hoşça kal, yarın görüşürüz!"},{"en":"Bonne nuit !","tr":"İyi geceler!"}],"grammar":{"point":"Les mots magiques","tr":"Fransızcada nazik olmak için üç sihirli sözcük kullanırız: «s'il te plaît» bir şey isterken, «merci» teşekkür ederken, «pardon» özür dilerken. Büyüklere ve tanımadığımız kişilere «s'il te plaît» yerine «s'il vous plaît» deriz.","examples":["De l'eau, s'il te plaît.","Merci, Maman !","Pardon, Léa !","Au revoir, Madame !"]},"questions":[{"q":"Que dit Léa à table ?","a":"Elle dit : s'il te plaît et merci."},{"q":"Que dit Léa le soir ?","a":"Elle dit : bonne nuit."},{"q":"Que répond Maman à « Merci » ?","a":"Elle répond : de rien."}],"quiz":[{"q":"Pour dire merci à Maman, je dis…","o":["Pardon","Merci","Bonne nuit"],"a":1,"why":""},{"q":"Le soir, avant de dormir, je dis…","o":["Bonne nuit","Bonjour","De rien"],"a":0,"why":""},{"q":"Quand quelqu'un dit « Merci », je réponds…","o":["Pardon","Bonjour","De rien"],"a":2,"why":"Teşekküre «De rien» diye karşılık veririz."},{"q":"Pour demander de l'eau, je dis « De l'eau, ___ ».","o":["à demain","s'il te plaît","au revoir"],"a":1,"why":""}],"drills":[{"type":"Yerine koyma","prompt":"Merci, Maman !","cue":"Papa","answer":"Merci, Papa !"},{"type":"Yerine koyma","prompt":"Au revoir, Madame !","cue":"Hugo","answer":"Au revoir, Hugo !"},{"type":"Genişletme","prompt":"Du pain, s'il te plaît.","cue":"Maman","answer":"Du pain, s'il te plaît, Maman."}],"sounds":[{"focus":"sessiz harfler","tr":"Fransızcada sözcük sonundaki harfler çoğu zaman okunmaz. «merci» ve «petit» sözcüklerinin sonundaki «t» ve «s» sessizdir, «pardon» sözcüğündeki «n» de burun sesi olur. Sözcüğün sonunu sanki yutarmışsın gibi söyle.","pairs":["petit / petite","gris / grise","chat / chatte"]}],"mission":{"brief":"Oyun: Nazik arkadaş! Claude, arkadaşın Hugo olacak. Hugo'ya selam ver, bir şey iste, teşekkür et ve vedalaş.","persona":"Hugo, a polite and cheerful 7-year-old French boy. Very simple French, short sentences, one question at a time. Hidden fact: Hugo has a birthday party on Saturday, but he only says so if the child asks « Qu'est-ce que tu fais samedi ? ».","goal":"«Bonjour», «s'il te plaît», «merci» ve «au revoir» sözcüklerini kullan.","opener":"Bonjour ! Je suis Hugo. Tu as un crayon ? Moi, je voudrais un crayon, s'il te plaît."}}};